window.CODE_SNAPSHOT = {"files":[{"path":"analyze_icm_ablation.py","text":"\"\"\"\nAnalyze an ICM-normalization ablation written by run_icm_ablation.py.\n\n    python analyze_icm_ablation.py runs/icm_ablation\n\nPer run (metrics.jsonl of train_craftax.py), with `tail` = the last 10% of logged updates:\n    final_return      extrinsic episode return over the tail (the bonus is not included)\n    auc_return        extrinsic return averaged over the whole run (learning speed)\n    final_score       Craftax score (geometric mean of achievement rates) over the tail\n    final_achievements, final_coverage   achievements per episode / achievement types reached\n    coverage_ever     achievement types reached at least once during the run (exploration)\n    bonus_share_*     |bonus| / (|bonus| + |extrinsic|) per update: max, tail mean, and the\n                      fraction of updates above RUNAWAY_SHARE\n    bonus_growth      tail / head (first 10%) mean bonus per step\n    runaway           the bonus still dominates the reward at the end of training (tail share >\n                      RUNAWAY_SHARE) or grew more than RUNAWAY_GROWTH times. Early updates are not\n                      used: the extrinsic reward is close to zero there, so even a well-scaled bonus\n                      is most of the reward\n    raw_error_growth  last / first raw forward-model error (does the unnormalized error grow?)\n\nQuestions answered in report.md (paired by seed against the `ppo` baseline):\n    H1  Is the icm_mean bonus bounded, while unnormalized / std-normalized bonuses run away?\n    H2  Does icm_mean explore better than ppo (coverage_ever, final_score) without hurting\n        the extrinsic return? Needs >= 3 seeds and the same sign on every seed to count.\n\"\"\"\n\nimport argparse\nimport json\nimport math\nfrom pathlib import Path\n\nRUNAWAY_SHARE = 0.5   # the curiosity bonus is more than half of the total |reward|\nRUNAWAY_GROWTH = 2.0  # the mean bonus per step at the end is more than twice that at the start\nTAIL = 0.1\nMIN_VERDICT_STEPS = 5e7  # shorter runs (e.g. the CPU debug preset) only get \"too short\" verdicts\nARM_ORDER = [\"ppo\", \"icm_none\", \"icm_std\", \"icm_mean\", \"icm_ema\"]\nMIN_SEEDS = 3\nRUN_METRICS = [\"final_return\", \"auc_return\", \"final_score\", \"final_achievements\", \"final_coverage\",\n               \"coverage_ever\", \"bonus_share_max\", \"bonus_share_final\", \"runaway_fraction\", \"bonus_growth\", \"runaway\",\n               \"raw_error_growth\"]\n\n\ndef load_rows(path: Path):\n    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]\n\n\ndef _mean(xs):\n    xs = [x for x in xs if x is not None and not (isinstance(x, float) and math.isnan(x))]\n    return sum(xs) / len(xs) if xs else None\n\n\ndef _std(xs):\n    xs = [x for x in xs if x is not None]\n    if len(xs) < 2:\n        return 0.0 if xs else None\n    m = sum(xs) / len(xs)\n    return math.sqrt(sum((x - m) ** 2 for x in xs) / (len(xs) - 1))\n\n\ndef run_stats(rows):\n    \"\"\"Summary numbers of one run (see module docstring)\"\"\"\n    ep_rows = [r for r in rows if r.get(\"episodes\", 0) > 0] or rows\n    tail = ep_rows[-max(1, int(round(len(ep_rows) * TAIL))):]\n    ach_keys = sorted({k for r in rows for k in r if k.startswith(\"Achievements/\")})\n    s = {\n        \"updates\": rows[-1].get(\"update\") if rows else 0,\n        \"env_steps\": rows[-1].get(\"env_steps\") if rows else 0,\n        \"final_return\": _mean([r.get(\"episode_return\") for r in tail]),\n        \"auc_return\": _mean([r.get(\"episode_return\") for r in ep_rows]),\n        \"final_score\": _mean([r.get(\"craftax_score\") for r in tail]),\n        \"final_achievements\": _mean([r.get(\"achievements\") for r in tail]),\n        \"final_coverage\": _mean([r.get(\"achievement_coverage\") for r in tail]),\n        \"coverage_ever\": sum(1 for k in ach_keys if max(r.get(k, 0.0) for r in rows) > 0),\n        \"achievement_types\": len(ach_keys),\n    }\n    shares = [r[\"icm/bonus_share\"] for r in rows if \"icm/bonus_share\" in r]\n    if shares:\n        raw = [r[\"icm/raw_error_mean\"] for r in rows if \"icm/raw_error_mean\" in r]\n        bonus = [r[\"icm/bonus_mean\"] for r in rows if \"icm/bonus_mean\" in r]\n        n = max(1, int(round(len(shares) * TAIL)))\n        head, end = _mean(bonus[:n]), _mean(bonus[-n:])\n        growth = end / head if head and head > 0 else None\n        share_final = _mean(shares[-n:])\n        s.update({\n            \"bonus_share_max\": max(shares),\n            \"bonus_share_final\": share_final,\n            \"runaway_fraction\": sum(x > RUNAWAY_SHARE for x in shares) / len(shares),\n            \"bonus_growth\": growth,\n            \"runaway\": 1.0 if share_final > RUNAWAY_SHARE or (growth is not None and growth > RUNAWAY_GROWTH) else 0.0,\n            \"raw_error_growth\": raw[-1] / raw[0] if raw and raw[0] > 0 else None,\n            \"bonus_mean_final\": rows[-1].get(\"icm/bonus_mean\"),\n            \"bonus_max\": max(r.get(\"icm/bonus_max\", 0.0) for r in rows),\n        })\n    return s\n\n\ndef analyze(out_dir, arms=None):\n    out_dir = Path(out_dir)\n    if not arms:\n        found = [p.name for p in out_dir.iterdir() if p.is_dir()]\n        arms = [a for a in ARM_ORDER if a in found] + sorted(a for a in found if a not in ARM_ORDER)\n    result = {\"arms\": {}, \"runaway_share\": RUNAWAY_SHARE}\n    for arm in arms:\n        runs = {}\n        for f in sorted((out_dir / arm).glob(\"seed*/metrics.jsonl\")):\n            rows = load_rows(f)\n            if rows:\n                runs[int(f.parent.name[4:])] = run_stats(rows)\n        if not runs:\n            continue\n        agg = {k: {\"mean\": _mean([r.get(k) for r in runs.values()]), \"std\": _std([r.get(k) for r in runs.values()\n                                                                                if r.get(k) is not None])}\n               for k in RUN_METRICS if any(r.get(k) is not None for r in runs.values())}\n        result[\"arms\"][arm] = {\"seeds\": runs, \"aggregate\": agg}\n    result[\"comparisons\"] = {arm: paired(result, arm, \"ppo\") for arm in result[\"arms\"] if arm != \"ppo\"}\n    result[\"verdict\"] = verdict(result)\n    return result\n\n\ndef paired(result, arm, base):\n    \"\"\"Per-seed differences arm - base for the exploration and return metrics\"\"\"\n    a, b = result[\"arms\"].get(arm), result[\"arms\"].get(base)\n    if not a or not b:\n        return {}\n    seeds = sorted(set(a[\"seeds\"]) & set(b[\"seeds\"]))\n    out = {}\n    for k in [\"coverage_ever\", \"final_score\", \"final_achievements\", \"final_return\", \"auc_return\"]:\n        diffs = [a[\"seeds\"][s][k] - b[\"seeds\"][s][k] for s in seeds\n                 if a[\"seeds\"][s].get(k) is not None and b[\"seeds\"][s].get(k) is not None]\n        if diffs:\n            out[k] = {\"mean_diff\": _mean(diffs), \"std_diff\": _std(diffs), \"n\": len(diffs),\n                      \"positive\": sum(d > 0 for d in diffs), \"negative\": sum(d < 0 for d in diffs)}\n    return out\n\n\ndef _bounded(result, arm):\n    runs = result[\"arms\"].get(arm, {}).get(\"seeds\", {})\n    if not runs or any(\"runaway\" not in r for r in runs.values()):\n        return None\n    return all(r[\"runaway\"] == 0.0 for r in runs.values())\n\n\ndef verdict(result):\n    v = {}\n    steps = [r[\"env_steps\"] for a in result[\"arms\"].values() for r in a[\"seeds\"].values()]\n    if steps and min(steps) < MIN_VERDICT_STEPS:\n        why = f\"runs are too short ({min(steps):.3g} env steps < {MIN_VERDICT_STEPS:.0e}) to judge\"\n        return {\"H1\": (\"too short\", why), \"H2\": (\"too short\", why)}\n    mean_ok = _bounded(result, \"icm_mean\")\n    controls = {arm: _bounded(result, arm) for arm in (\"icm_none\", \"icm_std\") if arm in result[\"arms\"]}\n    ran_away = [arm for arm, ok in controls.items() if ok is False]\n    if mean_ok is None:\n        v[\"H1\"] = (\"missing\", \"no icm_mean runs\")\n    elif not mean_ok:\n        v[\"H1\"] = (\"not supported\", \"the icm_mean bonus ran away (dominated the reward at the end or grew) on at least one seed\")\n    elif ran_away:\n        v[\"H1\"] = (\"supported\", f\"icm_mean stayed bounded on every seed while {', '.join(ran_away)} ran away\")\n    else:\n        v[\"H1\"] = (\"inconclusive\", \"icm_mean stayed bounded, but no control arm ran away in this budget\")\n\n    c = result[\"comparisons\"].get(\"icm_mean\", {})\n    if not c:\n        v[\"H2\"] = (\"missing\", \"needs both ppo and icm_mean runs\")\n    else:\n        n = max(x[\"n\"] for x in c.values())\n        explore = [c[k] for k in (\"coverage_ever\", \"final_score\") if k in c]\n        all_up = any(x[\"positive\"] == x[\"n\"] for x in explore)\n        any_down = any(x[\"mean_diff\"] < 0 for x in explore)\n        ret = c.get(\"final_return\")\n        hurts = ret is not None and ret[\"negative\"] == ret[\"n\"]\n        if n < MIN_SEEDS:\n            v[\"H2\"] = (\"inconclusive\", f\"only {n} paired seed(s); need >= {MIN_SEEDS}\")\n        elif all_up and not any_down and not hurts:\n            v[\"H2\"] = (\"supported\", \"coverage or score higher than ppo on every seed, extrinsic return not lower on all seeds\")\n        elif any_down and not all_up:\n            v[\"H2\"] = (\"not supported\", \"exploration metrics are lower than ppo on average\")\n        else:\n            v[\"H2\"] = (\"inconclusive\", \"mixed signs across seeds or extrinsic return lower on every seed\")\n    return v\n\n\ndef _fmt(x, nd=2):\n    return \"-\" if x is None else (f\"{x:.{nd}f}\" if isinstance(x, float) else str(x))\n\n\ndef write_report(result, out_dir, debug=False):\n    out_dir = Path(out_dir)\n    lines = [\"# ICM normalization ablation\", \"\"]\n    if debug:\n        lines += [\"> CPU debug preset: tiny model and a few updates. This checks the pipeline only;\",\n                  \"> the numbers below do not test the hypothesis.\", \"\"]\n    lines += [\"Mean ± std over seeds. Return is extrinsic only. Runaway = over the last \"\n              f\"{TAIL:.0%} of updates the bonus is > {RUNAWAY_SHARE:.0%} of |reward|, or the mean bonus grew \"\n              f\"> {RUNAWAY_GROWTH:g}x; 'runaway' is the fraction of seeds.\", \"\",\n              \"| arm | seeds | final return | AUC return | Craftax score | coverage ever | bonus share (end) | bonus growth | runaway | raw error growth |\",\n              \"|---|---|---|---|---|---|---|---|---|---|\"]\n    for arm, data in result[\"arms\"].items():\n        a = data[\"aggregate\"]\n        cell = lambda k, nd=2: (f\"{_fmt(a[k]['mean'], nd)} ± {_fmt(a[k]['std'], nd)}\" if k in a else \"-\")\n        lines.append(f\"| {arm} | {len(data['seeds'])} | {cell('final_return')} | {cell('auc_return')} | \"\n                     f\"{cell('final_score')} | {cell('coverage_ever', 1)} | {cell('bonus_share_final')} | \"\n                     f\"{cell('bonus_growth')} | {cell('runaway')} | {cell('raw_error_growth')} |\")\n    lines += [\"\", \"Paired differences vs. ppo (same seeds): mean diff (seeds up / down)\", \"\",\n              \"| arm | coverage ever | Craftax score | achievements | final return | AUC return |\", \"|---|---|---|---|---|---|\"]\n    for arm, c in result[\"comparisons\"].items():\n        cell = lambda k: (f\"{c[k]['mean_diff']:+.2f} ({c[k]['positive']}↑/{c[k]['negative']}↓)\" if k in c else \"-\")\n        lines.append(f\"| {arm} | {cell('coverage_ever')} | {cell('final_score')} | {cell('final_achievements')} | \"\n                     f\"{cell('final_return')} | {cell('auc_return')} |\")\n    lines += [\"\", \"## Verdict\", \"\"]\n    names = {\"H1\": \"Moving-mean normalization keeps the curiosity bonus bounded\",\n             \"H2\": \"Moving-mean normalization improves exploration over PPO\"}\n    for h, (status, why) in result[\"verdict\"].items():\n        lines.append(f\"- **{h}** {names[h]}: **{status}** ({why})\")\n    report = \"\\n\".join(lines) + \"\\n\"\n    (out_dir / \"report.md\").write_text(report)\n    (out_dir / \"summary.json\").write_text(json.dumps(result, indent=2, default=str))\n    return report\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    parser.add_argument(\"out_dir\", help=\"directory written by run_icm_ablation.py\")\n    parser.add_argument(\"--arms\", nargs=\"+\")\n    args = parser.parse_args()\n    result = analyze(args.out_dir, args.arms)\n    print(write_report(result, args.out_dir))\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"compare_craftax_run.py","text":"\"\"\"\nCompare a Craftax run with the reference W&B results (docs/craftax_reference.json).\n\n    python compare_craftax_run.py runs/craftax/metrics.jsonl --ref ppo\n    python compare_craftax_run.py runs/craftax/metrics.jsonl --ref ppo_rnn --last 0.05\n\nMetrics are averaged over the last `--last` fraction of logged updates. The\nreference is the end of a 1e9-step run, so only full-length runs are comparable;\nfor shorter runs the table shows how far along the run is.\n\"\"\"\n\nimport argparse\nimport json\nfrom pathlib import Path\n\nimport numpy as np\n\n\ndef load_metrics(path):\n    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]\n\n\ndef compare(rows, reference, last: float = 0.05):\n    n = max(1, int(round(len(rows) * last)))\n    tail = rows[-n:]\n    results = []\n    for key, (lo, hi) in reference[\"metrics\"].items():\n        values = [r[key] for r in tail if key in r]\n        if not values:\n            results.append((key, None, lo, hi, \"missing\"))\n            continue\n        value = float(np.mean(values))\n        status = \"ok\" if lo <= value <= hi else (\"low\" if value < lo else \"high\")\n        results.append((key, value, lo, hi, status))\n    return results\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    parser.add_argument(\"metrics\", help=\"metrics.jsonl written by train_craftax.py\")\n    parser.add_argument(\"--ref\", default=\"ppo\", help=\"reference run: ppo | ppo_rnn\")\n    parser.add_argument(\"--reference-file\", default=str(Path(__file__).parent / \"docs\" / \"craftax_reference.json\"))\n    parser.add_argument(\"--last\", type=float, default=0.05, help=\"fraction of logged updates to average\")\n    args = parser.parse_args()\n\n    ref_all = json.loads(Path(args.reference_file).read_text())\n    reference = ref_all[\"runs\"][args.ref]\n    rows = load_metrics(args.metrics)\n    steps = rows[-1].get(\"env_steps\", 0)\n    print(f\"run: {args.metrics} ({len(rows)} logged updates, {steps:.3g} env steps)\")\n    print(f\"reference: {args.ref} - {reference['description']} at {ref_all['total_timesteps']:.0e} steps\")\n    if steps < 0.95 * ref_all[\"total_timesteps\"]:\n        print(f\"NOTE: run has {steps / ref_all['total_timesteps']:.1%} of the reference budget; \"\n              \"'low' rows are expected until it is complete\")\n    results = compare(rows, reference, args.last)\n    counts = {}\n    for key, value, lo, hi, status in results:\n        counts[status] = counts.get(status, 0) + 1\n        shown = \"-\" if value is None else f\"{value:8.2f}\"\n        print(f\"{key:40s} {shown:>8s}   ref [{lo:g}, {hi:g}]   {status}\")\n    print(\"summary: \" + \", \".join(f\"{k}={v}\" for k, v in sorted(counts.items())))\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"configs/benchmark.yaml","text":"# Benchmarking Configuration for Diffu_MoE_VLM\n# MineDojo-style evaluation settings\n\ndefaults:\n  - data: planning\n  - eval: planning \n  - goal_model: horizon\n  - model: simple\n  - mineclip: attn\n\n# Core simulator settings\nsimulator:\n  resolution: [640, 480]\n  rgb_only: false\n  max_steps: 2000  # Increased for comprehensive evaluation\n\n# Evaluation settings with benchmarking\neval:\n  env_name: \"Plains\"\n  max_steps: 2000\n  single_task: false  # Run full benchmark suite\n  task_name: \"obtain_wooden_slab\"  # Used only if single_task: true\n  output_dir: \"./evaluation_results\"\n\n# Comprehensive benchmarking settings\nbenchmark:\n  enabled: true\n  output_dir: \"./benchmark_results\"\n  save_frequency: 10  # Save intermediate results every 10 tasks\n  max_history_files: 20  # Keep last 20 benchmark files\n  include_media: true  # Save screenshots and videos\n  media_frequency: 50  # Log media every 50 steps\n  \n  # Task selection for focused evaluation\n  task_categories:\n    - \"survival\"\n    - \"harvest\" \n    - \"mining\"\n    - \"tech_tree\"\n    - \"combat\"\n    - \"creative\"\n  \n  # Difficulty levels to include\n  difficulties:\n    - \"easy\"\n    - \"medium\"\n    - \"hard\"\n  \n  # Specific tasks to prioritize (empty means all tasks)\n  priority_tasks: []\n\n# WandB logging configuration\nwandb:\n  enabled: true\n  project: \"diffu-moe-vlm-minecraft-benchmark\"\n  entity: null  # Set to your WandB entity if needed\n  tags:\n    - \"minecraft\"\n    - \"planning\"\n    - \"vlm\"\n    - \"benchmark\"\n    - \"minedojo\"\n  notes: \"Comprehensive MineDojo-style benchmarking for Diffu_MoE_VLM\"\n  \n  # Logging settings\n  log_frequency: 10  # Log metrics every 10 steps\n  save_code: true\n  monitor_gpu: true\n  log_gradients: false\n  log_parameters: false\n  \n  # Media logging\n  log_images: true\n  image_frequency: 100  # Log images every 100 steps\n  log_videos: false  # Disable video logging by default (large files)\n  \n  # Artifact settings\n  save_artifacts: true\n  artifact_types:\n    - \"benchmark_results\"\n    - \"task_configs\"\n    - \"model_checkpoints\"\n\n# Goal model settings for planning\ngoal_model:\n  freq: 20  # Update goals every 20 steps\n  queue_size: 8  # Maintain up to 8 goals\n  use_ranking_goal: true\n  horizon_length: 100  # Planning horizon\n\n# Model settings\nmodel:\n  backbone_name: \"simple\"\n  use_horizon: true\n  load_ckpt_path: \"\"\n  \n  # Model evaluation settings\n  temperature: 0.1  # Low temperature for more deterministic behavior\n  top_k: 5\n  max_tokens: 512\n\n# Recording settings\nrecord:\n  frames: true\n  video_dir: \"./benchmark_videos\"\n  frame_frequency: 20  # Record every 20 frames\n  compress_videos: true\n\n# Resource management\nresources:\n  gpu_memory_limit: 0.8  # Use max 80% of GPU memory\n  cpu_workers: 4\n  max_parallel_tasks: 1  # Sequential task execution for consistent benchmarking\n  \n  # Timeout settings\n  task_timeout: 300  # 5 minutes per task maximum\n  episode_timeout: 120  # 2 minutes per episode maximum\n  planning_timeout: 30  # 30 seconds per planning cycle\n\n# Output and storage\noutput:\n  base_dir: \"./outputs\"\n  experiment_name: \"benchmark_suite\"\n  timestamp_format: \"%Y%m%d_%H%M%S\"\n  \n  # Result formats\n  save_json: true\n  save_csv: true\n  save_plots: true\n  \n  # Cleanup settings\n  auto_cleanup: true\n  keep_last_n_experiments: 10\n\n# Debugging and development\ndebug:\n  verbose: true\n  log_level: \"INFO\"\n  save_intermediate: false\n  debug_planning: false\n  profile_performance: false\n\n# Task-specific overrides\ntask_overrides:\n  # Override settings for specific tasks\n  \"defeat_ender_dragon\":\n    max_steps: 50000  # Much longer for ultimate challenge\n    task_timeout: 3600  # 1 hour timeout\n  \n  \"survive_3_days\":\n    max_steps: 72000  # 3 full Minecraft days\n    task_timeout: 1800  # 30 minutes\n  \n  # Creative tasks get more steps\n  \"build_castle\":\n    max_steps: 10000\n    task_timeout: 600  # 10 minutes\n  \n  \"build_house\":\n    max_steps: 5000\n    task_timeout: 300  # 5 minutes\n\n# Advanced benchmarking features\nadvanced:\n  # Statistical analysis\n  statistical_tests: true\n  confidence_interval: 0.95\n  min_samples_per_task: 3  # Run each task at least 3 times\n  \n  # Comparative analysis\n  baseline_comparison: false\n  baseline_results_path: \"\"\n  \n  # Performance profiling\n  profile_memory: false\n  profile_time: true\n  \n  # Error analysis\n  detailed_error_logging: true\n  save_failed_episodes: true\n  \n  # Reproducibility\n  random_seed: 42\n  deterministic_mode: true\n\n# LLM settings for planning\nllm:\n  api_base: \"http://localhost:9999/v1\"\n  model: \"meta-llama/Llama-3.2-1B\"\n  api_key: \"DUMMY\"\n  timeout: 30\n  max_retries: 3\n  \n  # Planning-specific settings\n  planning_temperature: 0.1\n  planning_max_tokens: 256\n  use_system_prompt: true\n"},{"path":"configs/data/planning.yaml","text":"# Planning-specific data configuration\n\n# Task configuration\ntasks:\n  enabled:\n    - \"obtain_wooden_slab\"\n    - \"obtain_stone_stairs\" \n    - \"obtain_painting\"\n    - \"mine_cobblestone\"\n    - \"mine_iron_ore\"\n    - \"mine_diamond\"\n\n# Data paths (packaged under diffu_moe_vlm/data)\ndata_dir: \"diffu_moe_vlm/data\"\ngoal_lib_file: \"goal_lib.json\"\ntask_info_file: \"task_info.json\"\ngoal_mapping_file: \"goal_mapping.json\"\n\n# Prompt files\nprompts:\n  task_prompt: \"task_prompt.txt\"\n  replan_prompt: \"deps_prompt.txt\"\n  parse_prompt: \"parse_prompt.txt\"\n\n# Embedding settings\nembeddings:\n  cache_dir: \"./embeddings\"\n  dimension: 512\n"},{"path":"configs/defaults.yaml","text":"# Default configuration for MC-Planner Migration\n\ndefaults:\n  - data: planning\n  - eval: planning \n  - goal_model: horizon\n  - model: simple\n  - mineclip: attn\n  - _self_\n\n# Simulator settings\nsimulator:\n  resolution: [640, 480]\n  rgb_only: false\n  max_steps: 1000\n\n# Evaluation settings  \neval:\n  env_name: \"Plains\"\n  max_steps: 1000\n  single_task: false\n  task_name: \"obtain_wooden_slab\"\n  output_dir: \"./results\"\n  max_replans: 5             # replanning budget per episode\n  replan_after_failures: 3   # consecutive failed actions before replanning\n  max_goal_steps: 50         # steps allowed on one sub-goal before replanning\n\n# Symbolic tech-tree environment\nenv:\n  seed: 0\n  action_failure_prob: 0.0   # >0 makes valid actions fail randomly (imperfect control)\n\n# Goal-conditioned controller\ncontroller:\n  auto_prerequisites: true   # false: only execute the selected goal (tests plan quality)\n\n# Goal model settings\ngoal_model:\n  freq: 10\n  queue_size: 5\n  use_ranking_goal: true\n\n# Model settings\nmodel:\n  backbone_name: \"simple\"\n  use_horizon: true\n  load_ckpt_path: \"\"\n\n# Recording settings\nrecord:\n  frames: false\n  video_dir: \"./videos\"\n\n# Pre-trained models\npretrains:\n  clip_path: \"\"\n  model_path: \"\"\n\n# Output settings\noutput_dir: \"./outputs\"\nexperiment_name: \"mc_planner_migration\"\n\n# Local LLM settings (falls back to the rule-based planner when disabled or unreachable)\nllm:\n  enabled: true\n  api_base: \"http://localhost:8000/v1\"\n  model: \"local-llama3\"\n  api_key: \"DUMMY\"\n  timeout: 30\n\n# WandB settings\nwandb:\n  enabled: true\n  project: \"diffu-moe-vlm-minecraft\"\n  experiment_name: null\n  tags:\n    - \"minecraft\"\n    - \"vlm\"\n    - \"planning\"\n    - \"moe\"\n    - \"diffusion\"\n  notes: \"MC-Planner with Diffusion MoE VLM integration\"\n  log_images: true\n  log_videos: false\n  log_frequency: 10\n  track_inventory: true\n  track_planning: true\n  track_exploration: true\n  track_efficiency: true\n  save_code: true\n  anonymous: null\n  mode: \"online\"\n"},{"path":"configs/eval/planning.yaml","text":"# Evaluation configuration for planning tasks\n\n# Environment settings\nenv_name: \"Plains\"\nmax_steps: 1000\ntimeout: 300  # seconds\n\n# Task selection\nrun_all_tasks: true\nspecific_tasks:\n  - \"obtain_wooden_slab\"\n  - \"obtain_stone_stairs\"\n  - \"obtain_painting\"\n\n# Evaluation metrics\nmetrics:\n  success_rate: true\n  completion_time: true\n  action_efficiency: true\n  \n# Output settings\nsave_trajectories: true\nsave_videos: false\nlog_level: \"INFO\"\n"},{"path":"configs/eval_policy.yaml","text":"# Policy evaluation on Crafter (python evaluate_policy.py policy=<checkpoint|random>)\nseed: 100\ndevice: auto              # auto | cpu | cuda\ntorch_threads: null       # e.g. 2 on small CPUs to leave cores for env workers\npolicy: random\nepisodes: 20\nnum_envs: 4\ndeterministic: false\nexecute_steps: 4\nsample_steps: 10\noutput_dir: ./runs/eval\n\nenv:\n  size: 64\n  length: 10000\n  num_workers: null\n"},{"path":"configs/fp8_model.yaml","text":"# FP8 Model Configuration for NVIDIA Llama-3.3-70B-Instruct-FP8\n# Optimized settings for TensorRT-LLM with FP8 precision\n\n# Model identification\nmodel_name: \"nvidia/Llama-3.3-70B-Instruct-FP8\"\nmodel_type: \"llama\"\nmodel_version: \"3.3\"\n\n# FP8 Quantization Settings\nquantization:\n  # Primary FP8 settings\n  enabled: true\n  precision: \"fp8\"\n  data_type: \"float8_e4m3fn\"  # FP8 E4M3 format\n  \n  # Weights and activations\n  quantize_weights: true\n  quantize_activations: true\n  quantize_kv_cache: true\n  \n  # Calibration settings (from model card)\n  calibration_dataset: \"cnn_dailymail\"\n  calibration_method: \"max\"\n  \n  # Advanced FP8 settings\n  fp8_qdq: false  # Quantize-Dequantize\n  smooth_quant: false\n  int8_kv_cache: false  # Use FP8 instead\n  \n# TensorRT-LLM Engine Settings\nengine:\n  # Engine configuration\n  max_batch_size: 8\n  max_input_len: 4096\n  max_output_len: 2048\n  max_beam_width: 1\n  \n  # Context and sequence settings\n  max_seq_len: 8192  # Effective context for planning\n  max_context_length: 128000  # Full 128K context capability\n  \n  # Memory optimization\n  enable_context_fmha: true\n  enable_chunked_context: true\n  chunk_size: 8192\n  \n  # Attention optimization\n  multi_block_mode: true\n  use_custom_all_reduce: true\n  \n# Performance Optimization\nperformance:\n  # GPU utilization\n  gpu_memory_utilization: 0.85\n  tensor_parallel_size: 2  # For 70B model on multi-GPU\n  pipeline_parallel_size: 1\n  \n  # CUDA settings\n  use_tensor_cores: true\n  enable_cuda_graph: true\n  cuda_graph_cache_size: 1024\n  \n  # Batching optimization\n  enable_chunked_prefill: true\n  max_num_batched_tokens: 8192\n  max_num_seqs: 256\n  \n  # KV cache optimization\n  block_size: 16\n  swap_space: 4  # GB\n  \n# Sampling Parameters for Planning\nsampling:\n  # Temperature settings\n  temperature: 0.1  # Low for deterministic planning\n  temperature_range: [0.05, 0.3]\n  \n  # Top-p/Top-k settings\n  top_p: 0.95\n  top_k: 50\n  \n  # Repetition control\n  repetition_penalty: 1.1\n  presence_penalty: 0.0\n  frequency_penalty: 0.0\n  \n  # Length control\n  max_tokens: 512\n  min_tokens: 10\n  \n  # Stop sequences\n  stop_sequences: [\"\\n\\n\", \"Human:\", \"Assistant:\"]\n\n# API Configuration\napi:\n  # Server settings\n  host: \"localhost\"\n  port: 9999\n  timeout: 120  # Increased for FP8 model\n  \n  # Request settings\n  max_retries: 3\n  retry_delay: 2.0\n  \n  # Response format\n  stream: false\n  return_full_text: false\n  \n# Hardware Requirements\nhardware:\n  # Minimum requirements for FP8 model\n  min_gpu_memory: 40  # GB (reduced from ~80GB due to FP8)\n  recommended_gpu_memory: 80  # GB\n  \n  # Supported architectures (from model card)\n  supported_architectures:\n    - \"NVIDIA Blackwell\"\n    - \"NVIDIA Hopper\"  # H100, H200\n    - \"NVIDIA Lovelace\"  # RTX 4090, etc.\n  \n  # CUDA compute capability\n  min_compute_capability: 8.9  # H100/H200\n  \n# Monitoring and Logging\nmonitoring:\n  # Performance metrics\n  log_performance: true\n  log_memory_usage: true\n  log_throughput: true\n  \n  # FP8-specific metrics\n  log_fp8_stats: true\n  log_quantization_errors: false\n  \n  # Timing metrics\n  log_latency: true\n  log_ttft: true  # Time to first token\n  \n# Optimization Profiles\nprofiles:\n  # Planning profile (optimized for reasoning)\n  planning:\n    temperature: 0.1\n    max_tokens: 512\n    top_p: 0.95\n    repetition_penalty: 1.1\n    \n  # Creative profile (for creative tasks)\n  creative:\n    temperature: 0.7\n    max_tokens: 1024\n    top_p: 0.9\n    repetition_penalty: 1.05\n    \n  # Fast profile (for quick responses)\n  fast:\n    temperature: 0.2\n    max_tokens: 256\n    top_p: 0.8\n    repetition_penalty: 1.15\n\n# Error Handling\nerror_handling:\n  # Fallback settings\n  enable_fallback: true\n  fallback_model: \"meta-llama/Llama-3.2-8B-Instruct\"\n  fallback_precision: \"bf16\"\n  \n  # Retry logic\n  max_retries: 3\n  exponential_backoff: true\n  base_delay: 1.0\n  max_delay: 30.0\n  \n  # Error logging\n  log_errors: true\n  detailed_error_logs: true\n\n# Validation Settings\nvalidation:\n  # Model validation\n  validate_on_startup: true\n  run_benchmark: false\n  \n  # Output validation\n  validate_outputs: true\n  check_for_repetition: true\n  max_repetition_ratio: 0.3\n  \n  # Performance validation\n  min_throughput: 10.0  # tokens/second\n  max_latency: 5000  # milliseconds\n\n# Environment Variables Mapping\nenv_mapping:\n  LLM_API_BASE: \"api.host:api.port\"\n  LLM_MODEL: \"model_name\"\n  USE_FP8: \"quantization.enabled\"\n  FP8_PRECISION: \"quantization.precision\"\n  TENSOR_PARALLEL_SIZE: \"performance.tensor_parallel_size\"\n  GPU_MEMORY_UTILIZATION: \"performance.gpu_memory_utilization\"\n"},{"path":"configs/goal_model/horizon.yaml","text":"# Horizon-based goal model configuration\n\n# Goal selection strategy\nstrategy: \"plan_order\"  # plan_order, priority, random, round_robin, dependency\n\n# Horizon planning\nhorizon: 3\nuse_horizon_planning: true\n\n# Goal prioritization\npriorities:\n  mine_wood: 1.0\n  mine_stone: 0.9\n  mine_cobblestone: 0.9\n  obtain_wooden_pickaxe: 0.8\n  obtain_stone_pickaxe: 0.7\n  obtain_iron_pickaxe: 0.6\n  mine_iron_ore: 0.5\n  obtain_iron_ingot: 0.5\n  mine_coal: 0.4\n  obtain_wooden_slab: 0.3\n  obtain_stone_stairs: 0.3\n  obtain_painting: 0.2\n  mine_diamond: 0.1\n\n# Selection settings\nfreq: 10\nqueue_size: 5\nuse_ranking_goal: true\nmax_candidates: 5\n"},{"path":"configs/mineclip/attn.yaml","text":"# Attention-based MineCLIP configuration\n\n# Model architecture\narch: \"vit_base_p16_fz.v2.t2\"\nhidden_dim: 512\nimage_feature_dim: 512\nmlp_adapter_spec: \"v0-2.t0\"\npool_type: \"attn.d2.nh8.glusw\"\nresolution: [160, 256]\n\n# Attention settings\nnum_heads: 8\nattention_dropout: 0.1\nlayer_dropout: 0.1\n"},{"path":"configs/model/simple.yaml","text":"# Simple model configuration\n\n# Model architecture\nbackbone_name: \"simple\"\nhidden_dim: 256\noutput_dim: 128\n\n# Training settings\nlearning_rate: 0.001\nbatch_size: 32\nepochs: 100\n\n# Model loading\nuse_horizon: true\nload_ckpt_path: \"\"\n\n# Device settings\ndevice: \"auto\"  # auto, cuda, cpu\n"},{"path":"configs/train_craftax.yaml","text":"# Craftax PPO / PPO-RNN in JAX (python train_craftax.py). Defaults follow the\n# Craftax PPO baselines; check them against the run you want to reproduce.\nseed: 0\nname: null                 # default: <env>-[PPO_RNN-][MoE-][ICM-]<steps>M, like the reference W&B runs\noutput_dir: ./runs/craftax\nlog_every: 10              # updates between metric lines\ncheckpoint_every: 50       # updates between checkpoints (also the jit chunk size)\nresume: true               # continue from output_dir/checkpoint.npz if present\nmax_updates_per_run: null  # stop after this many updates in one process (time-limited jobs)\n\nalgo:\n  env_name: Craftax-Symbolic-v1    # or Craftax-Classic-Symbolic-v1\n  total_timesteps: 1000000000\n  num_envs: 1024\n  num_steps: 64\n  update_epochs: 4\n  num_minibatches: 8\n  lr: 2.0e-4\n  anneal_lr: true\n  gamma: 0.99\n  gae_lambda: 0.8\n  clip_eps: 0.2\n  ent_coef: 0.01\n  vf_coef: 0.5\n  max_grad_norm: 1.0\n  layer_size: 512\n  num_layers: 3\n  activation: tanh                 # the RNN variant uses relu\n  rnn: false\n  moe: false\n  num_experts: 4\n  top_k: 2\n  moe_aux_coef: 0.01\n  optimistic_resets: true\n  reset_ratio: 16\n  icm: false\n  icm_reward_coef: 0.01            # scale applied after normalization (mean/ema: typical bonus size, not a bound)\n  icm_lr: 3.0e-4\n  icm_forward_coef: 1.0\n  icm_inverse_coef: 1.0\n  icm_normalize: mean              # mean | ema | std | none (run_icm_ablation.py compares them)\n  icm_ema_decay: 0.99              # per update, for icm_normalize=ema\n\nwandb:\n  enabled: false\n  project: Craftax_Baselines\n"},{"path":"configs/train_diffusion.yaml","text":"# Diffusion policy behavior cloning on Crafter (python train_diffusion.py)\nseed: 0\ndevice: auto              # auto | cpu | cuda\ntorch_threads: null       # e.g. 2 on small CPUs to leave cores for env workers\noutput_dir: ./runs/diffusion\n\nenv:\n  size: 64\n  length: 10000\n  num_workers: null\n\ndemos:\n  path: null                # existing demos.npz (obs, actions, episode); skips collection\n  policy_checkpoint: null   # PPO checkpoint used as the teacher; random policy if null\n  num_steps: 50000\n  num_envs: 8\n\nmodel:\n  encoder:\n    name: cnn\n    feature_dim: 256\n  horizon: 8                # actions per diffusion sample\n  num_diffusion_steps: 50\n  hidden_dim: 512\n  depth: 4\n\ntrain:\n  steps: 10000\n  batch_size: 128\n  lr: 3.0e-4\n\neval:\n  episodes: 20\n  num_envs: 4\n  execute_steps: 4          # receding horizon: execute this many sampled actions, then resample\n  sample_steps: 10          # strided DDIM steps (null = full DDPM)\n\nwandb:\n  enabled: false\n  project: diffu-moe-vlm-crafter\n  tags: [crafter, diffusion, bc]\n"},{"path":"configs/train_ppo.yaml","text":"# PPO with an MoE actor-critic on Crafter (python train_ppo.py)\nseed: 0\ndevice: auto              # auto | cpu | cuda\ntorch_threads: null       # e.g. 2 on small CPUs to leave cores for env workers\noutput_dir: ./runs/ppo\n\nenv:\n  size: 64\n  length: 10000\n  num_workers: null       # null: one process per env; 0: run envs in-process\n\nmodel:\n  encoder:\n    name: cnn             # cnn | vit | pretrained\n    feature_dim: 256\n    # pretrained_model: openai/clip-vit-base-patch32   # for name=pretrained (or a SigLIP model)\n    # freeze: true\n  trunk: moe              # moe | mlp (dense ablation)\n  hidden_dim: 512\n  num_layers: 2\n  num_experts: 4\n  top_k: 2\n  trajectory: null        # e.g. {num_joints: 3, out_dim: 128} to condition on 3D trajectory / IMU input\n\nppo:\n  total_steps: 1000000\n  num_envs: 8\n  rollout_length: 128\n  epochs: 4\n  minibatches: 8\n  lr: 3.0e-4\n  gamma: 0.95\n  gae_lambda: 0.65\n  clip: 0.2\n  value_coef: 0.5\n  entropy_coef: 0.01\n  moe_aux_coef: 0.01\n  max_grad_norm: 0.5\n  anneal_lr: true\n  log_window: 100\n\ncheckpoint_every: 50      # updates\neval_episodes: 20\neval_num_envs: 4\n\nwandb:\n  enabled: false\n  project: diffu-moe-vlm-crafter\n  tags: [crafter, ppo, moe]\n"},{"path":"configs/wandb.yaml","text":"# WandB Configuration for Diffu_MoE_VLM\nwandb:\n  enabled: true\n  project: \"diffu-moe-vlm-minecraft\"\n  experiment_name: null  # Auto-generated if null\n  tags:\n    - \"minecraft\"\n    - \"vlm\"\n    - \"planning\"\n    - \"moe\"\n    - \"diffusion\"\n  notes: \"MC-Planner with Diffusion MoE VLM integration\"\n  \n  # Logging settings\n  log_images: true  # Log RGB observations\n  log_videos: false  # Log episode videos (requires video recording)\n  log_frequency: 10  # Log images every N steps\n  \n  # Metrics to track\n  track_inventory: true\n  track_planning: true\n  track_exploration: true\n  track_efficiency: true\n  \n  # WandB specific settings\n  save_code: true\n  anonymous: null  # Set to \"allow\" for anonymous logging\n  mode: \"online\"  # \"online\", \"offline\", or \"disabled\"\n"},{"path":"diffu_moe_vlm/__init__.py","text":"\"\"\"\nDiffu_MoE_VLM: planning agent in the Describe, Explain, Plan and Select style on a symbolic Minecraft tech tree.\n\nSubmodules are imported lazily so that light-weight components (env, core,\ncontroller) do not pull in optional heavy dependencies such as torch or wandb.\n\"\"\"\n\n__version__ = \"0.2.0\"\n"},{"path":"diffu_moe_vlm/benchmark_metrics.py","text":"\"\"\"\nMineDojo-style Benchmarking Metrics for Diffu_MoE_VLM\nImplements comprehensive evaluation metrics based on MineDojo's benchmarking suite\n\"\"\"\n\nimport json\nimport time\nimport numpy as np\nfrom typing import Dict, List, Any, Optional, Tuple\nfrom pathlib import Path\nfrom dataclasses import dataclass, asdict\nfrom collections import defaultdict\n\n\n@dataclass\nclass TaskResult:\n    \"\"\"Single task evaluation result\"\"\"\n    task_id: str\n    task_type: str  # \"programmatic\", \"creative\", \"playthrough\"\n    success: bool\n    completion_time: float\n    total_steps: int\n    reward: float\n    final_inventory: Dict[str, int]\n    trajectory_length: int\n    completion_percentage: float  # 0-100\n    efficiency_score: float  # reward per step\n    planning_iterations: int\n    goal_changes: int\n    error_message: Optional[str] = None\n\n\n@dataclass\nclass EpisodeMetrics:\n    \"\"\"Metrics for a single episode\"\"\"\n    episode_id: str\n    start_time: float\n    end_time: float\n    total_steps: int\n    total_reward: float\n    success: bool\n    \n    # MineDojo-style metrics\n    inventory_diversity: int  # Number of unique items obtained\n    crafting_events: int  # Number of crafting actions\n    mining_events: int  # Number of mining actions\n    exploration_area: float  # Area explored (in blocks²)\n    \n    # Planning metrics\n    planning_time: float\n    replanning_count: int\n    goal_completion_rate: float\n    \n    # Efficiency metrics\n    actions_per_second: float\n    reward_per_step: float\n    time_to_first_success: Optional[float]\n\n\n@dataclass\nclass BenchmarkSuite:\n    \"\"\"Complete benchmark suite results\"\"\"\n    suite_name: str\n    start_time: float\n    end_time: float\n    total_tasks: int\n    completed_tasks: int\n    successful_tasks: int\n    \n    # Task category breakdown\n    programmatic_results: List[TaskResult]\n    creative_results: List[TaskResult]\n    playthrough_results: List[TaskResult]\n    \n    # Aggregate metrics\n    overall_success_rate: float\n    average_completion_time: float\n    average_steps_per_task: float\n    average_reward: float\n    \n    # MineDojo-specific metrics\n    tech_tree_progression: Dict[str, bool]  # Which tools/items were successfully crafted\n    survival_metrics: Dict[str, float]  # Health, hunger, survival time\n    combat_metrics: Dict[str, int]  # Monsters defeated, damage taken/dealt\n\n\nclass MinecraftTaskCategories:\n    \"\"\"Task categorization based on MineDojo benchmark suite\"\"\"\n    \n    SURVIVAL_TASKS = [\n        \"survive_1_day\", \"survive_3_days\", \"survive_7_days\",\n        \"survive_with_food\", \"survive_with_sword\"\n    ]\n    \n    HARVEST_TASKS = [\n        \"harvest_milk\", \"harvest_wool\", \"obtain_cobblestone\",\n        \"obtain_iron_ore\", \"obtain_diamond\", \"obtain_wooden_planks\"\n    ]\n    \n    TECH_TREE_TASKS = [\n        \"craft_wooden_pickaxe\", \"craft_stone_pickaxe\", \"craft_iron_pickaxe\",\n        \"craft_diamond_pickaxe\", \"craft_wooden_sword\", \"craft_iron_sword\"\n    ]\n    \n    COMBAT_TASKS = [\n        \"combat_zombie\", \"combat_skeleton\", \"combat_spider\",\n        \"hunt_pig\", \"hunt_cow\", \"hunt_chicken\"\n    ]\n    \n    CREATIVE_TASKS = [\n        \"build_house\", \"build_castle\", \"build_bridge\",\n        \"create_art\", \"build_farm\", \"build_tower\"\n    ]\n    \n    @classmethod\n    def get_task_category(cls, task_id: str) -> str:\n        \"\"\"Determine task category from task ID\"\"\"\n        if any(task in task_id for task in cls.SURVIVAL_TASKS):\n            return \"survival\"\n        elif any(task in task_id for task in cls.HARVEST_TASKS):\n            return \"harvest\"\n        elif any(task in task_id for task in cls.TECH_TREE_TASKS):\n            return \"tech_tree\"\n        elif any(task in task_id for task in cls.COMBAT_TASKS):\n            return \"combat\"\n        elif any(task in task_id for task in cls.CREATIVE_TASKS):\n            return \"creative\"\n        elif \"creative:\" in task_id:\n            return \"creative\"\n        elif \"playthrough\" in task_id:\n            return \"playthrough\"\n        else:\n            return \"programmatic\"\n\n\nclass BenchmarkMetrics:\n    \"\"\"\n    Comprehensive benchmarking metrics system following MineDojo's evaluation framework\n    \"\"\"\n    \n    def __init__(self, output_dir: str = \"./benchmark_results\"):\n        self.output_dir = Path(output_dir)\n        self.output_dir.mkdir(parents=True, exist_ok=True)\n        \n        # Initialize metric tracking\n        self.current_episode_metrics = None\n        self.task_results = []\n        self.episode_history = []\n        \n        # MineDojo-style tracking\n        self.tech_tree_items = {\n            \"wooden_pickaxe\": False, \"stone_pickaxe\": False, \"iron_pickaxe\": False,\n            \"diamond_pickaxe\": False, \"wooden_sword\": False, \"iron_sword\": False,\n            \"diamond_sword\": False, \"bow\": False, \"crossbow\": False\n        }\n        \n        self.survival_stats = {\n            \"max_health\": 20.0,\n            \"current_health\": 20.0,\n            \"hunger_level\": 20.0,\n            \"days_survived\": 0.0\n        }\n        \n        self.combat_stats = {\n            \"monsters_defeated\": 0,\n            \"damage_dealt\": 0.0,\n            \"damage_taken\": 0.0,\n            \"deaths\": 0\n        }\n        \n    def start_episode(self, episode_id: str, task_id: str) -> None:\n        \"\"\"Start tracking a new episode\"\"\"\n        self.current_episode_metrics = EpisodeMetrics(\n            episode_id=episode_id,\n            start_time=time.time(),\n            end_time=0.0,\n            total_steps=0,\n            total_reward=0.0,\n            success=False,\n            inventory_diversity=0,\n            crafting_events=0,\n            mining_events=0,\n            exploration_area=0.0,\n            planning_time=0.0,\n            replanning_count=0,\n            goal_completion_rate=0.0,\n            actions_per_second=0.0,\n            reward_per_step=0.0,\n            time_to_first_success=None\n        )\n        \n        print(f\"[Benchmark] Started episode {episode_id} for task {task_id}\")\n    \n    def update_step_metrics(self, \n                          obs: Dict,\n                          action: Dict,\n                          reward: float,\n                          info: Dict) -> None:\n        \"\"\"Update metrics for each step\"\"\"\n        if not self.current_episode_metrics:\n            return\n            \n        self.current_episode_metrics.total_steps += 1\n        self.current_episode_metrics.total_reward += reward\n        \n        # Update inventory metrics\n        inventory = info.get('inventory', {})\n        self.current_episode_metrics.inventory_diversity = len(inventory)\n        \n        # Track crafting and mining events\n        # Symbolic macro actions ({'type': 'craft', ...}) only count when they succeeded\n        action_type = action.get('type')\n        action_ok = info.get('action_success', True)\n        if action.get('craft', 0) > 0 or (action_type in ('craft', 'smelt') and action_ok):\n            self.current_episode_metrics.crafting_events += 1\n            \n        if action.get('attack', 0) > 0 or (action_type == 'mine' and action_ok):\n            self.current_episode_metrics.mining_events += 1\n        \n        # Update tech tree progression\n        for item in inventory:\n            if item in self.tech_tree_items:\n                self.tech_tree_items[item] = True\n        \n        # Update survival stats\n        self.survival_stats.update({\n            \"current_health\": info.get('life_stats', {}).get('health', 20.0),\n            \"hunger_level\": info.get('life_stats', {}).get('food', 20.0)\n        })\n        \n        # Update exploration area (simplified)\n        pos = info.get('location_stats', {}).get('pos', [0, 0, 0])\n        if len(pos) >= 2:\n            # Simple area calculation based on max distance from origin\n            area = max(abs(pos[0]), abs(pos[2])) ** 2\n            self.current_episode_metrics.exploration_area = max(\n                self.current_episode_metrics.exploration_area, area\n            )\n    \n    def update_planning_metrics(self, \n                              planning_time: float,\n                              is_replanning: bool = False) -> None:\n        \"\"\"Update planning-related metrics\"\"\"\n        if not self.current_episode_metrics:\n            return\n            \n        self.current_episode_metrics.planning_time += planning_time\n        \n        if is_replanning:\n            self.current_episode_metrics.replanning_count += 1\n    \n    def end_episode(self, success: bool, final_inventory: Dict) -> EpisodeMetrics:\n        \"\"\"End episode tracking and compute final metrics\"\"\"\n        if not self.current_episode_metrics:\n            raise ValueError(\"No active episode to end\")\n        \n        self.current_episode_metrics.end_time = time.time()\n        self.current_episode_metrics.success = success\n        \n        # Compute derived metrics\n        episode_duration = (self.current_episode_metrics.end_time - \n                          self.current_episode_metrics.start_time)\n        \n        if episode_duration > 0:\n            self.current_episode_metrics.actions_per_second = (\n                self.current_episode_metrics.total_steps / episode_duration\n            )\n        \n        if self.current_episode_metrics.total_steps > 0:\n            self.current_episode_metrics.reward_per_step = (\n                self.current_episode_metrics.total_reward / \n                self.current_episode_metrics.total_steps\n            )\n        \n        # Store episode\n        episode_metrics = self.current_episode_metrics\n        self.episode_history.append(episode_metrics)\n        self.current_episode_metrics = None\n        \n        return episode_metrics\n    \n    def evaluate_task(self, \n                     task_id: str,\n                     success: bool,\n                     completion_time: float,\n                     total_steps: int,\n                     total_reward: float,\n                     final_inventory: Dict,\n                     planning_iterations: int = 0,\n                     goal_changes: int = 0,\n                     error_message: Optional[str] = None) -> TaskResult:\n        \"\"\"Evaluate a complete task\"\"\"\n        \n        task_category = MinecraftTaskCategories.get_task_category(task_id)\n        task_type = \"programmatic\" if task_category != \"creative\" else \"creative\"\n        if \"playthrough\" in task_id:\n            task_type = \"playthrough\"\n        \n        # Calculate completion percentage\n        completion_percentage = 100.0 if success else 0.0\n        \n        # Calculate efficiency score\n        efficiency_score = total_reward / max(total_steps, 1)\n        \n        result = TaskResult(\n            task_id=task_id,\n            task_type=task_type,\n            success=success,\n            completion_time=completion_time,\n            total_steps=total_steps,\n            reward=total_reward,\n            final_inventory=final_inventory,\n            trajectory_length=total_steps,\n            completion_percentage=completion_percentage,\n            efficiency_score=efficiency_score,\n            planning_iterations=planning_iterations,\n            goal_changes=goal_changes,\n            error_message=error_message\n        )\n        \n        self.task_results.append(result)\n        return result\n    \n    def compute_benchmark_summary(self) -> BenchmarkSuite:\n        \"\"\"Compute comprehensive benchmark summary\"\"\"\n        if not self.task_results:\n            raise ValueError(\"No task results to summarize\")\n        \n        # Categorize results\n        programmatic_results = [r for r in self.task_results if r.task_type == \"programmatic\"]\n        creative_results = [r for r in self.task_results if r.task_type == \"creative\"]\n        playthrough_results = [r for r in self.task_results if r.task_type == \"playthrough\"]\n        \n        # Compute aggregate metrics\n        successful_tasks = sum(1 for r in self.task_results if r.success)\n        total_tasks = len(self.task_results)\n        \n        overall_success_rate = successful_tasks / max(total_tasks, 1) * 100\n        average_completion_time = np.mean([r.completion_time for r in self.task_results])\n        average_steps_per_task = np.mean([r.total_steps for r in self.task_results])\n        average_reward = np.mean([r.reward for r in self.task_results])\n        \n        return BenchmarkSuite(\n            suite_name=\"MineDojo_Benchmark\",\n            start_time=min(episode.start_time for episode in self.episode_history) if self.episode_history else time.time(),\n            end_time=max(episode.end_time for episode in self.episode_history) if self.episode_history else time.time(),\n            total_tasks=total_tasks,\n            completed_tasks=total_tasks,\n            successful_tasks=successful_tasks,\n            programmatic_results=programmatic_results,\n            creative_results=creative_results,\n            playthrough_results=playthrough_results,\n            overall_success_rate=overall_success_rate,\n            average_completion_time=average_completion_time,\n            average_steps_per_task=average_steps_per_task,\n            average_reward=average_reward,\n            tech_tree_progression=self.tech_tree_items.copy(),\n            survival_metrics=self.survival_stats.copy(),\n            combat_metrics=self.combat_stats.copy()\n        )\n    \n    def save_results(self, filename: Optional[str] = None) -> Path:\n        \"\"\"Save benchmark results to file\"\"\"\n        if filename is None:\n            timestamp = time.strftime(\"%Y%m%d_%H%M%S\")\n            filename = f\"benchmark_results_{timestamp}.json\"\n        \n        filepath = self.output_dir / filename\n        \n        # Prepare data for serialization\n        data = {\n            \"benchmark_summary\": asdict(self.compute_benchmark_summary()),\n            \"task_results\": [asdict(result) for result in self.task_results],\n            \"episode_history\": [asdict(episode) for episode in self.episode_history],\n            \"tech_tree_progression\": self.tech_tree_items,\n            \"survival_metrics\": self.survival_stats,\n            \"combat_metrics\": self.combat_stats\n        }\n        \n        with open(filepath, 'w') as f:\n            json.dump(data, f, indent=2, default=str)\n        \n        print(f\"[Benchmark] Results saved to {filepath}\")\n        return filepath\n    \n    def print_summary(self) -> None:\n        \"\"\"Print benchmark summary to console\"\"\"\n        summary = self.compute_benchmark_summary()\n        \n        print(\"\\n\" + \"=\"*60)\n        print(\"MINEDOJO-STYLE BENCHMARK RESULTS\")\n        print(\"=\"*60)\n        print(f\"Suite: {summary.suite_name}\")\n        print(f\"Total Tasks: {summary.total_tasks}\")\n        print(f\"Successful Tasks: {summary.successful_tasks}\")\n        print(f\"Overall Success Rate: {summary.overall_success_rate:.2f}%\")\n        print(f\"Average Completion Time: {summary.average_completion_time:.2f}s\")\n        print(f\"Average Steps per Task: {summary.average_steps_per_task:.1f}\")\n        print(f\"Average Reward: {summary.average_reward:.3f}\")\n        \n        print(\"\\nTask Category Breakdown:\")\n        print(f\"  Programmatic: {len(summary.programmatic_results)} tasks\")\n        print(f\"  Creative: {len(summary.creative_results)} tasks\")\n        print(f\"  Playthrough: {len(summary.playthrough_results)} tasks\")\n        \n        print(\"\\nTech Tree Progression:\")\n        for item, obtained in summary.tech_tree_progression.items():\n            status = \"✓\" if obtained else \"✗\"\n            print(f\"  {status} {item}\")\n        \n        print(\"\\nSurvival Metrics:\")\n        for metric, value in summary.survival_metrics.items():\n            print(f\"  {metric}: {value}\")\n        \n        print(\"\\nCombat Metrics:\")\n        for metric, value in summary.combat_metrics.items():\n            print(f\"  {metric}: {value}\")\n        \n        print(\"=\"*60)\n"},{"path":"diffu_moe_vlm/controller.py","text":"\"\"\"\nGoal-conditioned controller.\n\nTurns a sub-goal chosen by the selector (e.g. \"obtain_stone_pickaxe\") into\nthe next environment action. With `auto_prerequisites` enabled the controller\nresolves missing tools and ingredients through the tech tree, like a scripted\nskill library; disabled, it only attempts the goal itself and relies on the\nplanner to order sub-goals correctly (useful to measure planning quality).\n\"\"\"\n\nfrom typing import Dict, Optional\n\nfrom .core import action_requirements, goal_item, obtain_method\n\nInventory = Dict[str, int]\n\n\nclass GoalController:\n    \"\"\"Scripted controller producing (verb, item) macro actions\"\"\"\n\n    def __init__(self, auto_prerequisites: bool = True, max_depth: int = 16):\n        self.auto_prerequisites = auto_prerequisites\n        self.max_depth = max_depth\n\n    def next_action(self, goal: str, inventory: Inventory) -> Optional[Dict[str, str]]:\n        \"\"\"\n        Next action towards `goal`, or None when the goal item is unknown.\n\n        Returns an action dict {'type': verb, 'item': item} accepted by the env.\n        \"\"\"\n        item = goal_item(goal)\n        verb = obtain_method(item)\n        if verb is None:\n            return None\n        if not self.auto_prerequisites:\n            return {'type': verb, 'item': item}\n        return self._resolve(item, inventory, depth=0) or {'type': verb, 'item': item}\n\n    def _resolve(self, item: str, inventory: Inventory, depth: int) -> Optional[Dict[str, str]]:\n        \"\"\"First executable action on the dependency path of one `item` action\"\"\"\n        verb = obtain_method(item)\n        if verb is None or depth > self.max_depth:\n            return None\n        tools, consumed = action_requirements(verb, item)\n        for req, amount in {**tools, **consumed}.items():\n            if inventory.get(req, 0) < amount:\n                return self._resolve(req, inventory, depth + 1)\n        return {'type': verb, 'item': item}\n"},{"path":"diffu_moe_vlm/core.py","text":"\"\"\"\nSymbolic Minecraft core: items, tech tree, tasks and data loading.\n\nThis module is the single source of truth for recipes and task definitions.\nThe environment, controller, planner fallback and selector all use it, so a\nchange to the tech tree here is reflected everywhere.\n\"\"\"\n\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import Dict, List, Optional, Tuple\n\nDATA_DIR = Path(__file__).parent / \"data\"\n\nInventory = Dict[str, int]\nAction = Tuple[str, str]  # (verb, item), verb in {\"mine\", \"craft\", \"smelt\"}\n\n\nclass MinecraftConstants:\n    \"\"\"Minecraft tech tree (simplified but consistent)\"\"\"\n\n    # Raw resources gathered from the world: item -> required tool (None = bare hand)\n    MINING = {\n        'wood': None,\n        'wool': None,\n        'cobblestone': 'wooden_pickaxe',\n        'coal': 'wooden_pickaxe',\n        'iron_ore': 'stone_pickaxe',\n        'diamond': 'iron_pickaxe',\n    }\n\n    # Crafting recipes: item -> ingredients (consumed), output quantity, crafting table required\n    RECIPES = {\n        'wooden_planks': {'ingredients': {'wood': 1}, 'output': 4, 'table': False},\n        'stick': {'ingredients': {'wooden_planks': 2}, 'output': 4, 'table': False},\n        'crafting_table': {'ingredients': {'wooden_planks': 4}, 'output': 1, 'table': False},\n        'wooden_slab': {'ingredients': {'wooden_planks': 3}, 'output': 6, 'table': False},\n        'wooden_pickaxe': {'ingredients': {'wooden_planks': 3, 'stick': 2}, 'output': 1, 'table': True},\n        'stone_pickaxe': {'ingredients': {'cobblestone': 3, 'stick': 2}, 'output': 1, 'table': True},\n        'iron_pickaxe': {'ingredients': {'iron_ingot': 3, 'stick': 2}, 'output': 1, 'table': True},\n        'diamond_pickaxe': {'ingredients': {'diamond': 3, 'stick': 2}, 'output': 1, 'table': True},\n        'furnace': {'ingredients': {'cobblestone': 8}, 'output': 1, 'table': True},\n        'stone_stairs': {'ingredients': {'cobblestone': 6}, 'output': 4, 'table': True},\n        'painting': {'ingredients': {'stick': 8, 'wool': 1}, 'output': 1, 'table': True},\n    }\n\n    # Smelting recipes: item -> ingredients (consumed). Requires a furnace and consumes FUEL.\n    SMELTING = {\n        'iron_ingot': {'ingredients': {'iron_ore': 1}, 'output': 1},\n        'stone': {'ingredients': {'cobblestone': 1}, 'output': 1},\n    }\n    FUEL = {'coal': 1}\n\n    ALL_ITEMS = sorted(set(MINING) | set(RECIPES) | set(SMELTING))\n    ALL_CRAFT_SMELT_ITEMS = sorted(set(RECIPES) | set(SMELTING))\n\n    BIOMES = ['Plains', 'Forest', 'Mountain', 'Desert', 'Swamp']\n\n\nmc = MinecraftConstants()\n\n\n# ---------------------------------------------------------------------------\n# Tech tree helpers\n# ---------------------------------------------------------------------------\n\ndef obtain_method(item: str) -> Optional[str]:\n    \"\"\"How an item is obtained: 'mine', 'craft', 'smelt' or None if unknown\"\"\"\n    if item in mc.MINING:\n        return 'mine'\n    if item in mc.RECIPES:\n        return 'craft'\n    if item in mc.SMELTING:\n        return 'smelt'\n    return None\n\n\ndef action_requirements(verb: str, item: str) -> Tuple[Inventory, Inventory]:\n    \"\"\"\n    Requirements for performing one (verb, item) action.\n\n    Returns (tools, consumed): `tools` must be present but are not consumed\n    (pickaxes, crafting table, furnace); `consumed` items are used up.\n    \"\"\"\n    tools: Inventory = {}\n    consumed: Inventory = {}\n    if verb == 'mine':\n        tool = mc.MINING.get(item)\n        if tool:\n            tools[tool] = 1\n    elif verb == 'craft':\n        recipe = mc.RECIPES[item]\n        consumed.update(recipe['ingredients'])\n        if recipe['table']:\n            tools['crafting_table'] = 1\n    elif verb == 'smelt':\n        consumed.update(mc.SMELTING[item]['ingredients'])\n        for fuel, amount in mc.FUEL.items():\n            consumed[fuel] = consumed.get(fuel, 0) + amount\n        tools['furnace'] = 1\n    return tools, consumed\n\n\ndef output_quantity(verb: str, item: str) -> int:\n    if verb == 'craft':\n        return mc.RECIPES[item]['output']\n    if verb == 'smelt':\n        return mc.SMELTING[item]['output']\n    return 1\n\n\ndef apply_action(inventory: Inventory, verb: str, item: str) -> Tuple[Inventory, bool, str]:\n    \"\"\"\n    Apply a (verb, item) action to an inventory without mutating it.\n\n    Returns (new_inventory, success, error_message).\n    \"\"\"\n    if obtain_method(item) != verb:\n        return dict(inventory), False, f\"cannot {verb} {item}\"\n\n    tools, consumed = action_requirements(verb, item)\n    missing = {\n        req: amount - inventory.get(req, 0)\n        for req, amount in {**tools, **consumed}.items()\n        if inventory.get(req, 0) < amount\n    }\n    if missing:\n        desc = \", \".join(f\"{n} {k}\" for k, n in missing.items())\n        return dict(inventory), False, f\"cannot {verb} {item}: missing {desc}\"\n\n    new_inv = dict(inventory)\n    for req, amount in consumed.items():\n        new_inv[req] -= amount\n        if new_inv[req] == 0:\n            del new_inv[req]\n    new_inv[item] = new_inv.get(item, 0) + output_quantity(verb, item)\n    return new_inv, True, \"\"\n\n\ndef plan_steps(target: str, inventory: Optional[Inventory] = None, quantity: int = 1,\n               max_actions: int = 500) -> List[Action]:\n    \"\"\"\n    Rule-based decomposition of a target into the ordered list of (verb, item)\n    actions that obtains `quantity` of it from `inventory`, including repeated\n    actions when more material is needed (e.g. six \"mine cobblestone\").\n    Returns the actions found so far if the target is unreachable.\n    \"\"\"\n    inv: Inventory = dict(inventory or {})\n    steps: List[Action] = []\n\n    def ensure(item: str, qty: int, depth: int) -> bool:\n        verb = obtain_method(item)\n        if verb is None or depth > 32:\n            return inv.get(item, 0) >= qty\n        while inv.get(item, 0) < qty:\n            if len(steps) >= max_actions:\n                return False\n            tools, consumed = action_requirements(verb, item)\n            requirements = {**tools, **consumed}\n            # Gathering one requirement can consume another, so loop until all hold at once\n            for _ in range(len(requirements) * 4 + 1):\n                unmet = [(r, n) for r, n in requirements.items() if inv.get(r, 0) < n]\n                if not unmet:\n                    break\n                if not ensure(unmet[0][0], unmet[0][1], depth + 1):\n                    return False\n            new_inv, ok, _ = apply_action(inv, verb, item)\n            if not ok:\n                return False\n            inv.clear()\n            inv.update(new_inv)\n            steps.append((verb, item))\n        return True\n\n    ensure(target, quantity, 0)\n    return steps\n\n\n# ---------------------------------------------------------------------------\n# Goal naming and natural-language parsing\n# ---------------------------------------------------------------------------\n\ndef goal_name(item: str) -> str:\n    \"\"\"Canonical goal name for an item: mine_<raw item> or obtain_<crafted/smelted item>\"\"\"\n    return f\"mine_{item}\" if obtain_method(item) == 'mine' else f\"obtain_{item}\"\n\n\ndef goal_item(goal: str) -> str:\n    \"\"\"Target item of a goal name (inverse of goal_name, tolerant of other prefixes)\"\"\"\n    for prefix in (\"mine_\", \"obtain_\", \"craft_\", \"smelt_\"):\n        if goal.startswith(prefix):\n            return goal[len(prefix):]\n    return goal\n\n\n# Surface forms (lowercase, space separated) -> canonical item\nITEM_ALIASES: Dict[str, str] = {\n    'log': 'wood', 'logs': 'wood', 'wood log': 'wood', 'wood logs': 'wood',\n    'tree': 'wood', 'trees': 'wood', 'wood': 'wood', 'oak log': 'wood',\n    'plank': 'wooden_planks', 'planks': 'wooden_planks',\n    'sticks': 'stick', 'table': 'crafting_table', 'workbench': 'crafting_table',\n    'sheep': 'wool', 'cobble': 'cobblestone', 'iron ingots': 'iron_ingot',\n    'iron': 'iron_ore', 'coal ore': 'coal', 'diamonds': 'diamond',\n    'slab': 'wooden_slab', 'slabs': 'wooden_slab', 'stairs': 'stone_stairs',\n}\nfor _item in mc.ALL_ITEMS:\n    _words = _item.replace('_', ' ')\n    ITEM_ALIASES.setdefault(_words, _item)\n    ITEM_ALIASES.setdefault(_words + 's', _item)\n\n_ALIAS_PATTERN = re.compile(\n    r\"\\b(\" + \"|\".join(re.escape(a) for a in sorted(ITEM_ALIASES, key=len, reverse=True)) + r\")\\b\"\n)\n_MINE_VERBS = ('mine', 'dig', 'chop', 'collect', 'gather', 'find', 'get', 'harvest', 'kill', 'shear')\n\n\n_COUNT_PATTERN = re.compile(r\"(?:\\(\\s*)?[x\\u00d7]\\s*(\\d+)\\s*\\)?\\s*$\")\n\n\ndef parse_plan_to_goals(text: str) -> List[str]:\n    \"\"\"\n    Convert a free-form plan (one step per line) into canonical goal names.\n\n    Each line contributes the first item it mentions, e.g.\n    \"Craft wooden planks from wood\" -> obtain_wooden_planks. A trailing\n    repeat count (\"Mine cobblestone x6\") repeats the goal. Plain \"stone\"\n    with a gathering verb maps to cobblestone, as in Minecraft. Consecutive\n    lines naming the same goal once (\"Find trees\", \"Chop wood\") are merged.\n    \"\"\"\n    goals: List[str] = []\n    for raw_line in text.splitlines():\n        line = raw_line.strip().lower().replace('-', ' ')\n        line = re.sub(r\"^[\\s\\d\\.\\)\\*]+\", \"\", line)\n        if not line:\n            continue\n        count = 1\n        count_match = _COUNT_PATTERN.search(line)\n        if count_match:\n            count = max(1, int(count_match.group(1)))\n            line = line[:count_match.start()]\n        line_items = line.split(' from ')[0]  # \"craft X from Y\" -> X\n        matches = _ALIAS_PATTERN.findall(line_items)\n        if not matches:\n            continue\n        item = ITEM_ALIASES[matches[0]]\n        if item == 'stone' and any(v in line_items for v in _MINE_VERBS):\n            item = 'cobblestone'\n        goal = goal_name(item)\n        if count == 1 and goals and goals[-1] == goal:\n            continue\n        goals.extend([goal] * count)\n    return goals\n\n\n# ---------------------------------------------------------------------------\n# Tasks and data\n# ---------------------------------------------------------------------------\n\nclass TaskRegistry:\n    \"\"\"Benchmark task definitions\"\"\"\n\n    def __init__(self):\n        self.tasks = {\n            'obtain_wooden_slab': {'target': 'wooden_slab', 'group': 'crafting', 'difficulty': 'easy'},\n            'obtain_stone_stairs': {'target': 'stone_stairs', 'group': 'crafting', 'difficulty': 'medium'},\n            'obtain_painting': {'target': 'painting', 'group': 'crafting', 'difficulty': 'medium'},\n            'mine_cobblestone': {'target': 'cobblestone', 'group': 'mining', 'difficulty': 'easy'},\n            'mine_iron_ore': {'target': 'iron_ore', 'group': 'mining', 'difficulty': 'medium'},\n            'mine_diamond': {'target': 'diamond', 'group': 'mining', 'difficulty': 'hard'},\n            'obtain_wooden_pickaxe': {'target': 'wooden_pickaxe', 'group': 'crafting', 'difficulty': 'easy'},\n            'obtain_stone_pickaxe': {'target': 'stone_pickaxe', 'group': 'crafting', 'difficulty': 'medium'},\n            'obtain_iron_pickaxe': {'target': 'iron_pickaxe', 'group': 'crafting', 'difficulty': 'hard'},\n        }\n        self.default_tasks = [\n            'obtain_wooden_slab', 'obtain_stone_stairs', 'obtain_painting',\n            'mine_cobblestone', 'mine_iron_ore', 'mine_diamond',\n        ]\n\n    def get_task(self, task_name: str) -> Optional[Dict]:\n        \"\"\"Get task definition (unknown obtain_/mine_ names resolve to their item)\"\"\"\n        if task_name in self.tasks:\n            return self.tasks[task_name]\n        item = goal_item(task_name)\n        if obtain_method(item):\n            return {'target': item, 'group': 'crafting', 'difficulty': 'unknown'}\n        return None\n\n    def list_tasks(self) -> List[str]:\n        \"\"\"Default benchmark task list\"\"\"\n        return list(self.default_tasks)\n\n\nclass DataManager:\n    \"\"\"Loads packaged data files (goal library, mappings, task info, prompts)\"\"\"\n\n    def __init__(self, data_dir: Optional[str] = None):\n        self.data_dir = Path(data_dir) if data_dir else DATA_DIR\n\n    def _load_json(self, filename: str) -> Dict:\n        path = self.data_dir / filename\n        if not path.exists():\n            return {}\n        with open(path, 'r') as f:\n            return json.load(f)\n\n    def load_goal_mapping(self) -> Dict:\n        return self._load_json(\"goal_mapping.json\")\n\n    def load_task_info(self) -> Dict:\n        return self._load_json(\"task_info.json\")\n\n    def load_text(self, filename: str) -> Optional[str]:\n        path = self.data_dir / filename\n        return path.read_text() if path.exists() else None\n\n    def save_data(self, filename: str, data: Dict):\n        filepath = self.data_dir / filename\n        with open(filepath, 'w') as f:\n            json.dump(data, f, indent=2)\n\n\nclass SimulationState:\n    \"\"\"Inventory-only simulation state backed by the tech tree\"\"\"\n\n    def __init__(self, inventory: Optional[Inventory] = None):\n        self.inventory: Inventory = dict(inventory or {})\n\n    def get_inventory(self) -> Inventory:\n        return dict(self.inventory)\n\n    def can_perform(self, verb: str, item: str) -> bool:\n        return apply_action(self.inventory, verb, item)[1]\n\n    def perform(self, verb: str, item: str) -> Tuple[bool, str]:\n        self.inventory, success, error = apply_action(self.inventory, verb, item)\n        return success, error\n\n\n# Global instances\ntask_registry = TaskRegistry()\ndata_manager = DataManager()\n"},{"path":"diffu_moe_vlm/crafter_env.py","text":"\"\"\"\nCrafter environment (Gymnasium API) and achievement metrics.\n\nCrafter (Hafner, 2021) is a 2D open-world survival game with 64x64 pixel\nobservations, 17 discrete actions and 22 achievements such as EAT_PLANT,\nMAKE_IRON_PICKAXE and COLLECT_DIAMOND. It is the environment family used in\n\"An Efficient Open World Environment for Multi-Agent Social Learning\".\n\"\"\"\n\nfrom typing import Dict, Iterable, List, Optional\n\nimport gymnasium as gym\nimport numpy as np\nfrom gymnasium import spaces\n\nCRAFTER_ACTIONS: List[str] = [\n    'noop', 'move_left', 'move_right', 'move_up', 'move_down', 'do', 'sleep',\n    'place_stone', 'place_table', 'place_furnace', 'place_plant',\n    'make_wood_pickaxe', 'make_stone_pickaxe', 'make_iron_pickaxe',\n    'make_wood_sword', 'make_stone_sword', 'make_iron_sword',\n]\n\nCRAFTER_ACHIEVEMENTS: List[str] = [\n    'collect_coal', 'collect_diamond', 'collect_drink', 'collect_iron', 'collect_sapling',\n    'collect_stone', 'collect_wood', 'defeat_skeleton', 'defeat_zombie', 'eat_cow',\n    'eat_plant', 'make_iron_pickaxe', 'make_iron_sword', 'make_stone_pickaxe',\n    'make_stone_sword', 'make_wood_pickaxe', 'make_wood_sword', 'place_furnace',\n    'place_plant', 'place_stone', 'place_table', 'wake_up',\n]\n\n\nclass CrafterEnv(gym.Env):\n    \"\"\"Gymnasium wrapper around `crafter.Env`\"\"\"\n\n    metadata = {\"render_modes\": [\"rgb_array\"]}\n\n    def __init__(self, size: int = 64, length: int = 10000, seed: Optional[int] = None, reward: bool = True):\n        import crafter  # optional dependency: pip install -e \".[rl]\"\n\n        self._crafter = crafter\n        self._kwargs = dict(size=(size, size), length=length, reward=reward)\n        self._env = crafter.Env(seed=seed, **self._kwargs)\n        self.observation_space = spaces.Box(0, 255, (size, size, 3), dtype=np.uint8)\n        self.action_space = spaces.Discrete(len(CRAFTER_ACTIONS))\n        self._last_obs = None\n\n    def reset(self, seed: Optional[int] = None, options: Optional[Dict] = None):\n        super().reset(seed=seed)\n        if seed is not None:\n            # Crafter seeds world generation at construction time\n            self._env = self._crafter.Env(seed=seed, **self._kwargs)\n        self._last_obs = self._env.reset()\n        return self._last_obs, {'achievements': {name: 0 for name in CRAFTER_ACHIEVEMENTS}}\n\n    def step(self, action):\n        obs, reward, done, info = self._env.step(int(action))\n        self._last_obs = obs\n        terminated = bool(done and info.get('discount', 1.0) == 0.0)  # the player died\n        truncated = bool(done and not terminated)                     # episode length reached\n        return obs, float(reward), terminated, truncated, info\n\n    def render(self):\n        return self._last_obs\n\n\ndef crafter_score(success_rates: Dict[str, float]) -> float:\n    \"\"\"Crafter score: geometric mean of achievement success rates (in %), offset by 1\"\"\"\n    rates = np.array([success_rates.get(name, 0.0) for name in CRAFTER_ACHIEVEMENTS])\n    return float(np.exp(np.mean(np.log(1.0 + rates))) - 1.0)\n\n\nclass AchievementTracker:\n    \"\"\"Accumulates per-episode achievements, returns and lengths\"\"\"\n\n    def __init__(self):\n        self.episodes: List[Dict[str, int]] = []\n        self.returns: List[float] = []\n        self.lengths: List[int] = []\n\n    def add_episode(self, achievements: Dict[str, int], episode_return: float = 0.0, length: int = 0):\n        self.episodes.append({name: int(achievements.get(name, 0)) for name in CRAFTER_ACHIEVEMENTS})\n        self.returns.append(float(episode_return))\n        self.lengths.append(int(length))\n\n    def extend(self, other: \"AchievementTracker\"):\n        self.episodes += other.episodes\n        self.returns += other.returns\n        self.lengths += other.lengths\n\n    def success_rates(self, last: Optional[int] = None) -> Dict[str, float]:\n        \"\"\"Percentage of episodes in which each achievement was unlocked at least once\"\"\"\n        episodes = self.episodes[-last:] if last else self.episodes\n        if not episodes:\n            return {name: 0.0 for name in CRAFTER_ACHIEVEMENTS}\n        return {\n            name: 100.0 * sum(1 for ep in episodes if ep[name] > 0) / len(episodes)\n            for name in CRAFTER_ACHIEVEMENTS\n        }\n\n    def summary(self, last: Optional[int] = None) -> Dict[str, float]:\n        returns = self.returns[-last:] if last else self.returns\n        lengths = self.lengths[-last:] if last else self.lengths\n        rates = self.success_rates(last)\n        out = {\n            'episodes': len(returns),\n            'return_mean': float(np.mean(returns)) if returns else 0.0,\n            'length_mean': float(np.mean(lengths)) if lengths else 0.0,\n            'score': crafter_score(rates),\n        }\n        out.update({f'achievements/{name}': rate for name, rate in rates.items()})\n        return out\n\n\ndef format_achievements(rates: Dict[str, float], names: Optional[Iterable[str]] = None) -> str:\n    names = list(names or CRAFTER_ACHIEVEMENTS)\n    return \", \".join(f\"{name.upper()}={rates[name]:.1f}%\" for name in names)\n"},{"path":"diffu_moe_vlm/env.py","text":"\"\"\"\nSymbolic Minecraft tech-tree environment (Gymnasium API).\n\nActions are high-level (verb, item) macros such as (\"mine\", \"wood\") or\n(\"craft\", \"stick\"). Their effect on the inventory follows the tech tree in\n`core`, so a task succeeds only when the agent actually gathers and crafts\nthe required items. There is no 3D world: the RGB observation is a blank\nframe kept for interface compatibility with pixel-based policies.\n\"\"\"\n\nfrom typing import Any, Dict, Optional, Tuple, Union\n\nimport gymnasium as gym\nimport numpy as np\nfrom gymnasium import spaces\n\nfrom .core import apply_action, mc, obtain_method, task_registry\n\nActionLike = Union[int, np.integer, Tuple[str, str], Dict[str, Any]]\n\n\nclass MinecraftGymnasiumEnv(gym.Env):\n    \"\"\"Tech-tree crafting environment with a Gymnasium interface\"\"\"\n\n    metadata = {\"render_modes\": [\"rgb_array\"]}\n\n    def __init__(self,\n                 name: str = \"Plains\",\n                 img_size: Tuple[int, int] = (640, 480),\n                 rgb_only: bool = False,\n                 max_steps: int = 1000,\n                 action_failure_prob: float = 0.0,\n                 **kwargs):\n        \"\"\"\n        Args:\n            name: biome name (informational only)\n            img_size: (width, height) of the RGB observation\n            rgb_only: omit the depth observation\n            max_steps: episode length before truncation\n            action_failure_prob: probability that a valid action randomly fails\n                (models imperfect low-level control; 0 = deterministic)\n        \"\"\"\n        super().__init__()\n\n        self.name = name\n        self.img_size = tuple(img_size)\n        self.rgb_only = rgb_only\n        self._max_steps = max_steps\n        self.action_failure_prob = action_failure_prob\n\n        self.items = list(mc.ALL_ITEMS)\n        self.item_index = {item: i for i, item in enumerate(self.items)}\n        self.macro_actions = [(\"noop\", \"\")] + [(obtain_method(item), item) for item in self.items]\n        self.macro_index = {a: i for i, a in enumerate(self.macro_actions)}\n\n        self.action_space = spaces.Discrete(len(self.macro_actions))\n        self.observation_space = self._create_observation_space()\n\n        self._current_step = 0\n        self._inventory: Dict[str, int] = {}\n        self._target: Optional[str] = None\n        self._target_quantity = 1\n\n    def _create_observation_space(self):\n        width, height = self.img_size\n        obs_space = {\n            'rgb': spaces.Box(low=0, high=255, shape=(height, width, 3), dtype=np.uint8),\n            'inventory': spaces.Box(low=0, high=np.iinfo(np.int32).max,\n                                    shape=(len(self.items),), dtype=np.int32),\n        }\n        if not self.rgb_only:\n            obs_space['depth'] = spaces.Box(low=0, high=255, shape=(height, width), dtype=np.uint8)\n        return spaces.Dict(obs_space)\n\n    # ------------------------------------------------------------------\n    # Gymnasium API\n    # ------------------------------------------------------------------\n\n    def reset(self, seed: Optional[int] = None, options: Optional[Dict] = None):\n        \"\"\"\n        Options:\n            task: task name from the registry (e.g. \"obtain_wooden_slab\")\n            target / target_quantity: explicit target item instead of a task\n            initial_inventory: starting inventory (default empty)\n        \"\"\"\n        super().reset(seed=seed)\n        options = options or {}\n\n        self._current_step = 0\n        self._inventory = {k: v for k, v in options.get('initial_inventory', {}).items() if v > 0}\n        self._target = options.get('target')\n        if self._target is None and options.get('task'):\n            task = task_registry.get_task(options['task'])\n            if task is None:\n                raise ValueError(f\"Unknown task: {options['task']}\")\n            self._target = task['target']\n        self._target_quantity = options.get('target_quantity', 1)\n\n        return self._get_observation(), self._get_info(action_success=True, action_error=\"\")\n\n    def step(self, action: ActionLike):\n        self._current_step += 1\n        verb, item = self.decode_action(action)\n\n        success, error = True, \"\"\n        if verb != \"noop\":\n            new_inventory, success, error = apply_action(self._inventory, verb, item)\n            if success and self.action_failure_prob > 0 and self.np_random.random() < self.action_failure_prob:\n                success, error = False, f\"{verb} {item} failed (control failure)\"\n            if success:\n                self._inventory = new_inventory\n\n        task_success = self._task_success()\n        reward = 1.0 if task_success else 0.0\n        terminated = task_success\n        truncated = not terminated and self._current_step >= self._max_steps\n\n        info = self._get_info(action_success=success, action_error=error)\n        return self._get_observation(), reward, terminated, truncated, info\n\n    def render(self):\n        return self._get_observation()['rgb']\n\n    def close(self):\n        pass\n\n    # ------------------------------------------------------------------\n    # Helpers\n    # ------------------------------------------------------------------\n\n    def decode_action(self, action: ActionLike) -> Tuple[str, str]:\n        \"\"\"Accept a macro index, a (verb, item) tuple or a {'type', 'item'} dict\"\"\"\n        if isinstance(action, (int, np.integer)):\n            return self.macro_actions[int(action)]\n        if isinstance(action, tuple):\n            return action\n        if isinstance(action, dict) and 'type' in action:\n            return action['type'], action.get('item', \"\")\n        # Legacy low-level actions (movement/camera/attack) have no symbolic effect\n        return \"noop\", \"\"\n\n    def encode_action(self, verb: str, item: str) -> int:\n        return self.macro_index[(verb, item)]\n\n    def _task_success(self) -> bool:\n        return self._target is not None and self._inventory.get(self._target, 0) >= self._target_quantity\n\n    def _get_observation(self):\n        width, height = self.img_size\n        inventory = np.zeros(len(self.items), dtype=np.int32)\n        for item, count in self._inventory.items():\n            if item in self.item_index:\n                inventory[self.item_index[item]] = count\n        obs = {'rgb': np.zeros((height, width, 3), dtype=np.uint8), 'inventory': inventory}\n        if not self.rgb_only:\n            obs['depth'] = np.zeros((height, width), dtype=np.uint8)\n        return obs\n\n    def _get_info(self, action_success: bool, action_error: str) -> Dict[str, Any]:\n        return {\n            'step': self._current_step,\n            'inventory': dict(self._inventory),\n            'target': self._target,\n            'action_success': action_success,\n            'action_error': action_error,\n            'task_success': self._task_success(),\n        }\n\n\nclass MinecraftEnvRegistry:\n    \"\"\"Registry for different Minecraft environments\"\"\"\n\n    _environments = {\n        'Plains': MinecraftGymnasiumEnv,\n        'Forest': MinecraftGymnasiumEnv,\n        'Mountain': MinecraftGymnasiumEnv,\n    }\n\n    @classmethod\n    def make(cls, name: str, **kwargs):\n        if name not in cls._environments:\n            raise ValueError(f\"Environment {name} not found\")\n        return cls._environments[name](name=name, **kwargs)\n\n    @classmethod\n    def register(cls, name: str, env_class):\n        cls._environments[name] = env_class\n\n\ndef MineDojoEnv(name: str = \"Plains\", **kwargs):\n    \"\"\"Compatibility function to replace the MineDojo environment\"\"\"\n    return MinecraftEnvRegistry.make(name, **kwargs)\n"},{"path":"diffu_moe_vlm/evaluator.py","text":"\"\"\"\nEvaluation loop in the Describe, Explain, Plan and Select style.\n\nFor each task the planner proposes a plan, which is parsed into sub-goals.\nThe selector picks the next sub-goal, the controller acts on it until it is\nreached, and failures (invalid actions or a goal that takes too long) trigger\na replan with a description of the current inventory and the failure.\n\"\"\"\n\nimport time\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom omegaconf import DictConfig, OmegaConf\n\nfrom .benchmark_metrics import BenchmarkMetrics\nfrom .controller import GoalController\nfrom .core import data_manager, goal_item, task_registry\nfrom .env import MineDojoEnv\nfrom .planner import Planner\nfrom .selector import HorizonSelector, Selector\nfrom .wandb_integration import WandBIntegratedBenchmark, WandBLogger\n\n\nclass Evaluator:\n    \"\"\"Main evaluator class for MC-Planner experiments\"\"\"\n\n    def __init__(self, cfg: DictConfig):\n        self.cfg = cfg\n        eval_cfg = cfg.get('eval', {})\n        wandb_cfg = cfg.get('wandb', {})\n\n        self.wandb_logger = WandBLogger(\n            project_name=wandb_cfg.get('project', 'diffu-moe-vlm-minecraft'),\n            experiment_name=wandb_cfg.get('experiment_name', None),\n            config=OmegaConf.to_container(cfg, resolve=True),\n            tags=wandb_cfg.get('tags', ['minecraft', 'vlm', 'planning']),\n            notes=wandb_cfg.get('notes', None),\n            enabled=wandb_cfg.get('enabled', True)\n        )\n        self.benchmark_metrics = BenchmarkMetrics(\n            output_dir=str(Path(cfg.get('output_dir', '.')) / 'benchmark_results')\n        )\n        self.integrated_benchmark = WandBIntegratedBenchmark(self.benchmark_metrics, self.wandb_logger)\n\n        # Environment\n        env_cfg = cfg.get('env', {})\n        self.max_steps = eval_cfg.get('max_steps', 1000)\n        self.env = MineDojoEnv(\n            name=eval_cfg.get('env_name', 'Plains'),\n            img_size=tuple(cfg.simulator.resolution),\n            rgb_only=cfg.simulator.get('rgb_only', False),\n            max_steps=self.max_steps,\n            action_failure_prob=env_cfg.get('action_failure_prob', 0.0),\n        )\n        self.seed = env_cfg.get('seed', None)\n        self._seeded = False\n\n        # Tasks\n        data_cfg = cfg.get('data', {})\n        enabled_tasks = data_cfg.get('tasks', {}).get('enabled') if data_cfg else None\n        self.task_list = list(enabled_tasks) if enabled_tasks else task_registry.list_tasks()\n        self.task_info = data_manager.load_task_info()\n\n        # Planner / selector / controller\n        llm_cfg = cfg.get('llm', {})\n        self.planner = Planner(\n            api_base=llm_cfg.get('api_base'),\n            model=llm_cfg.get('model'),\n            api_key=llm_cfg.get('api_key'),\n            enabled=llm_cfg.get('enabled', True),\n            timeout=llm_cfg.get('timeout', 30),\n        )\n        self.selector = self._build_selector(cfg.get('goal_model', {}))\n        controller_cfg = cfg.get('controller', {})\n        self.controller = GoalController(auto_prerequisites=controller_cfg.get('auto_prerequisites', True))\n\n        # Replanning budget\n        self.max_replans = eval_cfg.get('max_replans', 5)\n        self.replan_after_failures = eval_cfg.get('replan_after_failures', 3)\n        self.max_goal_steps = eval_cfg.get('max_goal_steps', 50)\n        self.max_candidates = cfg.get('goal_model', {}).get('max_candidates', 5)\n\n        self.log_images = wandb_cfg.get('log_images', False)\n        self.log_frequency = wandb_cfg.get('log_frequency', 10)\n\n        print(f\"[Progress] Tasks: {self.task_list}\")\n        print(f\"[Progress] Selector: {type(self.selector).__name__}({self.selector.strategy}), \"\n              f\"auto_prerequisites={self.controller.auto_prerequisites}\")\n        print(f\"[Progress] WandB logging enabled: {self.wandb_logger.enabled}\")\n\n    @staticmethod\n    def _build_selector(goal_cfg) -> Selector:\n        strategy = goal_cfg.get('strategy', 'plan_order')\n        priorities = goal_cfg.get('priorities', None)\n        priorities = dict(priorities) if priorities else None\n        if goal_cfg.get('use_horizon_planning', False):\n            return HorizonSelector(horizon=goal_cfg.get('horizon', 3), strategy=strategy, priorities=priorities)\n        return Selector(strategy=strategy, priorities=priorities)\n\n    # ------------------------------------------------------------------\n\n    def reset(self, task: str):\n        \"\"\"Reset environment and agent modules for a new task\"\"\"\n        seed = None\n        if not self._seeded:\n            seed, self._seeded = self.seed, True\n        obs, info = self.env.reset(seed=seed, options={'task': task})\n        self.planner.reset()\n        self.selector.reset()\n        print(f\"[Reset] Starting task: {task}\")\n        return obs, info\n\n    def _replan(self, question: str, inventory: Dict[str, int], failure_desc: str) -> Tuple[str, List[str]]:\n        start = time.time()\n        plan = self.planner.replan(\n            question,\n            self.planner.generate_inventory_description(inventory),\n            inventory=inventory,\n            failure_desc=failure_desc,\n        )\n        goal_list = self.planner.generate_goal_list(plan)\n        self.integrated_benchmark.log_planning(\n            plan=plan, goal_list=goal_list, planning_time=time.time() - start, is_replanning=True\n        )\n        print(f\"[Replan] {failure_desc} -> {goal_list}\")\n        return plan, goal_list\n\n    def single_task_evaluate(self, task: Optional[str] = None) -> Dict[str, Any]:\n        \"\"\"Run one episode of the Describe, Explain, Plan and Select loop on a task\"\"\"\n        task = task or self.task_list[0]\n        task_def = task_registry.get_task(task)\n        if task_def is None:\n            raise ValueError(f\"Unknown task: {task}\")\n        target = task_def['target']\n\n        obs, info = self.reset(task)\n        inventory = info['inventory']\n        group = self.task_info.get(task, {}).get('group', task_def['group'])\n        question = f\"How to obtain {target.replace('_', ' ')}?\"\n\n        episode_id = f\"{task}_{int(time.time())}\"\n        self.integrated_benchmark.start_episode(episode_id, task)\n\n        # Plan\n        start = time.time()\n        plan = self.planner.initial_planning(group=group, task_question=question, target=target)\n        goal_list = self.planner.generate_goal_list(plan)\n        self.integrated_benchmark.log_planning(\n            plan=plan, goal_list=goal_list, planning_time=time.time() - start, is_replanning=False\n        )\n        print(f\"[Planning] Goal list: {goal_list}\")\n        initial_goals = list(goal_list)\n\n        success = bool(info.get('task_success'))\n        total_reward = 0.0\n        steps = 0\n        replans = 0\n        goal_changes = 0\n        # Goal instances complete when their item is obtained (event-based), so a plan\n        # can require e.g. \"mine cobblestone\" six times and old stock never counts\n        goal_done = [False] * len(goal_list)\n        current_goal: Optional[str] = None\n        goal_steps = 0\n        consecutive_failures = 0\n        episode_start = time.time()\n\n        while not success and steps < self.max_steps:\n            pending = list(dict.fromkeys(g for g, done in zip(goal_list, goal_done) if not done))\n            if current_goal not in pending:\n                current_goal = None\n\n            # Select\n            if current_goal is None:\n                if not pending:\n                    if replans >= self.max_replans:\n                        break\n                    plan, goal_list = self._replan(question, inventory, \"plan finished but the target is missing\")\n                    goal_done = [False] * len(goal_list)\n                    replans += 1\n                    continue\n                candidates = self.selector.generate_candidate_goal_list(pending, inventory, self.max_candidates)\n                current_goal = self.selector.horizon_select(candidates, inventory)\n                goal_steps = 0\n                goal_changes += 1\n                self.wandb_logger.log_planning_metrics(\n                    plan=plan, goal_list=goal_list, selected_goal=current_goal,\n                    planning_time=0.0, is_replanning=False\n                )\n\n            # Act\n            action = self.controller.next_action(current_goal, inventory)\n            if action is None:\n                print(f\"[Controller] Unknown goal {current_goal!r}, skipping\")\n                goal_done = [done or g == current_goal for g, done in zip(goal_list, goal_done)]\n                current_goal = None\n                continue\n\n            previous_inventory = inventory\n            obs, reward, terminated, truncated, info = self.env.step(action)\n            steps += 1\n            goal_steps += 1\n            total_reward += reward\n            inventory = info['inventory']\n            self.integrated_benchmark.log_step(obs=obs, action=action, reward=reward, info=info, planning_time=0.0)\n            if self.log_images and steps % self.log_frequency == 0 and 'rgb' in obs:\n                self.wandb_logger.log_media(step=steps, rgb_obs=obs['rgb'],\n                                            caption=f\"Step {steps} - Goal: {current_goal}\")\n\n            # Mark the earliest pending instance of every item obtained this step\n            for item, count in inventory.items():\n                if count > previous_inventory.get(item, 0):\n                    for i, g in enumerate(goal_list):\n                        if not goal_done[i] and goal_item(g) == item:\n                            goal_done[i] = True\n                            if g == current_goal:\n                                current_goal = None\n                            break\n\n            if info['task_success']:\n                success = True\n                break\n            if truncated:\n                break\n\n            # Explain & replan on repeated failures or a stuck goal\n            consecutive_failures = 0 if info['action_success'] else consecutive_failures + 1\n            stuck = current_goal is not None and goal_steps >= self.max_goal_steps\n            if consecutive_failures >= self.replan_after_failures or stuck:\n                if replans >= self.max_replans:\n                    break\n                failure_desc = (info['action_error'] if consecutive_failures\n                                else f\"goal {current_goal} not reached after {goal_steps} steps\")\n                plan, goal_list = self._replan(question, inventory, failure_desc)\n                goal_done = [False] * len(goal_list)\n                replans += 1\n                current_goal = None\n                consecutive_failures = 0\n\n        completion_time = time.time() - episode_start\n        print(f\"[Result] {task}: success={success} steps={steps} replans={replans}\")\n\n        episode_metrics = self.integrated_benchmark.end_episode(\n            success=success, final_inventory=inventory, task_id=task\n        )\n        task_result = self.integrated_benchmark.complete_task(\n            task_id=task,\n            success=success,\n            completion_time=completion_time,\n            total_steps=steps,\n            total_reward=total_reward,\n            final_inventory=inventory,\n            planning_iterations=episode_metrics.replanning_count,\n            goal_changes=goal_changes,\n        )\n\n        return {\n            'task': task,\n            'target': target,\n            'success': success,\n            'steps': steps,\n            'replans': replans,\n            'total_reward': total_reward,\n            'completion_time': completion_time,\n            'initial_goals': initial_goals,\n            'final_inventory': inventory,\n            'efficiency_score': task_result.efficiency_score,\n        }\n\n    def run_all_tasks(self) -> List[Dict[str, Any]]:\n        \"\"\"Run evaluation on all configured tasks\"\"\"\n        results = []\n        task_failures = 0\n\n        print(f\"[Benchmark] Starting evaluation of {len(self.task_list)} tasks\")\n        for i, task in enumerate(self.task_list):\n            try:\n                print(f\"[Benchmark] Evaluating task {i + 1}/{len(self.task_list)}: {task}\")\n                results.append(self.single_task_evaluate(task))\n                successful_tasks = sum(1 for r in results if r.get('success', False))\n                self.wandb_logger.log({\n                    \"benchmark/current_task_index\": i + 1,\n                    \"benchmark/current_success_rate\": (successful_tasks / len(results)) * 100,\n                    \"benchmark/tasks_completed\": len(results),\n                    \"benchmark/tasks_remaining\": len(self.task_list) - len(results)\n                })\n            except Exception as e:\n                print(f\"[Error] Failed to evaluate task {task}: {e}\")\n                results.append({\n                    'task': task, 'success': False, 'error': str(e), 'steps': 0,\n                    'total_reward': 0.0, 'completion_time': 0.0, 'final_inventory': {}\n                })\n                task_failures += 1\n                self.wandb_logger.log({\"errors/task_failures\": task_failures, \"errors/latest_error\": str(e)})\n\n        self.integrated_benchmark.finish_benchmark()\n\n        if results:\n            successful_tasks = sum(1 for r in results if r.get('success', False))\n            total_steps = sum(r.get('steps', 0) for r in results)\n            print(\"\\n[Summary] Benchmark completed!\")\n            print(f\"[Summary] Tasks completed: {successful_tasks}/{len(results)}\")\n            print(f\"[Summary] Overall success rate: {successful_tasks / len(results) * 100:.2f}%\")\n            print(f\"[Summary] Average steps per task: {total_steps / len(results):.2f}\")\n            for r in results:\n                print(f\"[Summary]   {r['task']:<22} success={r.get('success')} \"\n                      f\"steps={r.get('steps')} replans={r.get('replans', 0)}\")\n        return results\n"},{"path":"diffu_moe_vlm/fp8_utils.py","text":"\"\"\"\nFP8 Model Utilities for NVIDIA Llama-3.3-70B-Instruct-FP8\nHandles FP8 data type conversions and TensorRT-LLM integration\n\"\"\"\n\nimport os\nimport logging\nimport torch\nfrom typing import Dict, Any, Optional, Union, List\nfrom pathlib import Path\nimport numpy as np\n\ntry:\n    import tensorrt_llm\n    from tensorrt_llm import LLM, SamplingParams\n    TENSORRT_AVAILABLE = True\nexcept ImportError:\n    TENSORRT_AVAILABLE = False\n    print(\"[Warning] TensorRT-LLM not available. Install with: pip install tensorrt-llm\")\n\n\nclass FP8ModelManager:\n    \"\"\"\n    Manager for FP8 model operations and data type handling\n    \"\"\"\n    \n    def __init__(self, model_config: Dict[str, Any]):\n        self.model_config = model_config\n        self.model_name = model_config.get(\"model_name\", \"nvidia/Llama-3.3-70B-Instruct-FP8\")\n        self.use_fp8 = model_config.get(\"quantization\", {}).get(\"enabled\", True)\n        self.precision = model_config.get(\"quantization\", {}).get(\"precision\", \"fp8\")\n        \n        # Initialize logger\n        self.logger = logging.getLogger(__name__)\n        \n        # Model instance\n        self.llm_instance = None\n        self.sampling_params = None\n        \n        # Performance metrics\n        self.metrics = {\n            \"total_requests\": 0,\n            \"total_tokens\": 0,\n            \"total_time\": 0.0,\n            \"fp8_memory_saved\": 0.0\n        }\n    \n    def initialize_model(self) -> bool:\n        \"\"\"Initialize the FP8 model with TensorRT-LLM\"\"\"\n        if not TENSORRT_AVAILABLE:\n            self.logger.error(\"TensorRT-LLM not available\")\n            return False\n        \n        try:\n            # Extract configuration\n            perf_config = self.model_config.get(\"performance\", {})\n            quant_config = self.model_config.get(\"quantization\", {})\n            \n            # Initialize LLM with FP8 settings\n            self.llm_instance = LLM(\n                model=self.model_name,\n                tensor_parallel_size=perf_config.get(\"tensor_parallel_size\", 2),\n                dtype=quant_config.get(\"data_type\", \"float8_e4m3fn\"),\n                quantization=\"fp8\" if self.use_fp8 else None,\n                gpu_memory_utilization=perf_config.get(\"gpu_memory_utilization\", 0.85),\n                max_model_len=self.model_config.get(\"engine\", {}).get(\"max_context_length\", 8192),\n                enforce_eager=not perf_config.get(\"enable_cuda_graph\", True),\n                enable_chunked_prefill=perf_config.get(\"enable_chunked_prefill\", True),\n                max_num_batched_tokens=perf_config.get(\"max_num_batched_tokens\", 8192)\n            )\n            \n            # Initialize sampling parameters\n            sampling_config = self.model_config.get(\"sampling\", {})\n            self.sampling_params = SamplingParams(\n                temperature=sampling_config.get(\"temperature\", 0.1),\n                top_p=sampling_config.get(\"top_p\", 0.95),\n                top_k=sampling_config.get(\"top_k\", 50),\n                max_tokens=sampling_config.get(\"max_tokens\", 512),\n                repetition_penalty=sampling_config.get(\"repetition_penalty\", 1.1),\n                stop=sampling_config.get(\"stop_sequences\", [])\n            )\n            \n            self.logger.info(f\"FP8 model initialized: {self.model_name}\")\n            return True\n            \n        except Exception as e:\n            self.logger.error(f\"Failed to initialize FP8 model: {e}\")\n            return False\n    \n    def convert_to_fp8(self, data: Union[torch.Tensor, np.ndarray, List, str]) -> Any:\n        \"\"\"Convert input data to FP8 format if applicable\"\"\"\n        if not self.use_fp8:\n            return data\n        \n        if isinstance(data, str):\n            # Text data - no conversion needed\n            return data\n        elif isinstance(data, torch.Tensor):\n            # Convert tensor to FP8\n            if data.dtype in [torch.float32, torch.float16, torch.bfloat16]:\n                # Convert to FP8 E4M3 format (simulated with float16 clamping)\n                return self._simulate_fp8_conversion(data)\n            return data\n        elif isinstance(data, np.ndarray):\n            # Convert numpy array\n            tensor = torch.from_numpy(data)\n            converted = self._simulate_fp8_conversion(tensor)\n            return converted.numpy()\n        elif isinstance(data, list):\n            # Recursively convert list elements\n            return [self.convert_to_fp8(item) for item in data]\n        else:\n            return data\n    \n    def _simulate_fp8_conversion(self, tensor: torch.Tensor) -> torch.Tensor:\n        \"\"\"Simulate FP8 E4M3 conversion by clamping values\"\"\"\n        if not self.use_fp8:\n            return tensor\n        \n        # FP8 E4M3 range: approximately [-448, 448]\n        # This is a simulation - actual FP8 would be handled by TensorRT-LLM\n        fp8_max = 448.0\n        fp8_min = -448.0\n        \n        # Clamp to FP8 range and reduce precision\n        clamped = torch.clamp(tensor, fp8_min, fp8_max)\n        \n        # Simulate reduced precision by quantizing\n        scale = fp8_max / torch.max(torch.abs(clamped))\n        quantized = torch.round(clamped * scale * 127) / (scale * 127)\n        \n        return quantized.to(torch.float16)  # Use float16 as proxy for FP8\n    \n    def generate_response(self, prompt: str, **kwargs) -> str:\n        \"\"\"Generate response using FP8 model\"\"\"\n        if not self.llm_instance:\n            raise RuntimeError(\"Model not initialized. Call initialize_model() first.\")\n        \n        import time\n        start_time = time.time()\n        \n        try:\n            # Override sampling params if provided\n            sampling_params = self.sampling_params\n            if kwargs:\n                sampling_config = self.model_config.get(\"sampling\", {})\n                sampling_config.update(kwargs)\n                \n                sampling_params = SamplingParams(\n                    temperature=sampling_config.get(\"temperature\", 0.1),\n                    top_p=sampling_config.get(\"top_p\", 0.95),\n                    top_k=sampling_config.get(\"top_k\", 50),\n                    max_tokens=sampling_config.get(\"max_tokens\", 512),\n                    repetition_penalty=sampling_config.get(\"repetition_penalty\", 1.1),\n                    stop=sampling_config.get(\"stop_sequences\", [])\n                )\n            \n            # Generate response\n            outputs = self.llm_instance.generate([prompt], sampling_params)\n            \n            # Extract generated text\n            generated_text = outputs[0].outputs[0].text\n            \n            # Update metrics\n            end_time = time.time()\n            self.metrics[\"total_requests\"] += 1\n            self.metrics[\"total_time\"] += (end_time - start_time)\n            \n            if hasattr(outputs[0], 'usage'):\n                self.metrics[\"total_tokens\"] += outputs[0].usage.total_tokens\n            \n            return generated_text\n            \n        except Exception as e:\n            self.logger.error(f\"Error generating response: {e}\")\n            raise\n    \n    def get_model_info(self) -> Dict[str, Any]:\n        \"\"\"Get model information and configuration\"\"\"\n        return {\n            \"model_name\": self.model_name,\n            \"precision\": self.precision,\n            \"use_fp8\": self.use_fp8,\n            \"tensorrt_available\": TENSORRT_AVAILABLE,\n            \"initialized\": self.llm_instance is not None,\n            \"config\": self.model_config,\n            \"metrics\": self.metrics\n        }\n    \n    def estimate_memory_savings(self) -> Dict[str, float]:\n        \"\"\"Estimate memory savings from FP8 quantization\"\"\"\n        if not self.use_fp8:\n            return {\"memory_savings_gb\": 0.0, \"savings_percentage\": 0.0}\n        \n        # Estimate for 70B model\n        # FP16: ~140GB, FP8: ~70GB (approximately 50% reduction)\n        fp16_memory = 140.0  # GB\n        fp8_memory = 70.0    # GB\n        savings = fp16_memory - fp8_memory\n        percentage = (savings / fp16_memory) * 100\n        \n        return {\n            \"fp16_memory_gb\": fp16_memory,\n            \"fp8_memory_gb\": fp8_memory,\n            \"memory_savings_gb\": savings,\n            \"savings_percentage\": percentage\n        }\n    \n    def validate_fp8_setup(self) -> Dict[str, bool]:\n        \"\"\"Validate FP8 setup and capabilities\"\"\"\n        validation = {\n            \"tensorrt_available\": TENSORRT_AVAILABLE,\n            \"cuda_available\": torch.cuda.is_available(),\n            \"fp8_hardware_support\": False,\n            \"model_accessible\": False,\n            \"config_valid\": True\n        }\n        \n        # Check for FP8-capable hardware\n        if torch.cuda.is_available():\n            gpu_name = torch.cuda.get_device_name(0)\n            fp8_gpus = [\"H100\", \"H200\", \"RTX 4090\", \"RTX 4080\"]\n            validation[\"fp8_hardware_support\"] = any(gpu in gpu_name for gpu in fp8_gpus)\n        \n        # Check model accessibility\n        try:\n            # This would need actual model access\n            validation[\"model_accessible\"] = True\n        except:\n            validation[\"model_accessible\"] = False\n        \n        # Validate configuration\n        required_keys = [\"model_name\", \"quantization\", \"performance\"]\n        validation[\"config_valid\"] = all(key in self.model_config for key in required_keys)\n        \n        return validation\n    \n    def get_performance_stats(self) -> Dict[str, float]:\n        \"\"\"Get performance statistics\"\"\"\n        if self.metrics[\"total_requests\"] == 0:\n            return {\"avg_latency\": 0.0, \"throughput\": 0.0, \"total_requests\": 0}\n        \n        avg_latency = self.metrics[\"total_time\"] / self.metrics[\"total_requests\"]\n        throughput = self.metrics[\"total_tokens\"] / self.metrics[\"total_time\"] if self.metrics[\"total_time\"] > 0 else 0.0\n        \n        return {\n            \"avg_latency_seconds\": avg_latency,\n            \"throughput_tokens_per_second\": throughput,\n            \"total_requests\": self.metrics[\"total_requests\"],\n            \"total_tokens\": self.metrics[\"total_tokens\"],\n            \"total_time\": self.metrics[\"total_time\"]\n        }\n    \n    def cleanup(self):\n        \"\"\"Cleanup model resources\"\"\"\n        if self.llm_instance:\n            # TensorRT-LLM cleanup would go here\n            self.llm_instance = None\n            self.logger.info(\"FP8 model resources cleaned up\")\n\n\ndef create_fp8_manager(config_path: Optional[str] = None) -> FP8ModelManager:\n    \"\"\"Create FP8 model manager from configuration\"\"\"\n    if config_path is None:\n        config_path = Path(__file__).resolve().parent.parent / \"configs\" / \"fp8_model.yaml\"\n    \n    import yaml\n    \n    try:\n        with open(config_path, 'r') as f:\n            config = yaml.safe_load(f)\n        return FP8ModelManager(config)\n    except Exception as e:\n        logging.error(f\"Failed to load FP8 config from {config_path}: {e}\")\n        # Return with default config\n        default_config = {\n            \"model_name\": \"nvidia/Llama-3.3-70B-Instruct-FP8\",\n            \"quantization\": {\"enabled\": True, \"precision\": \"fp8\"},\n            \"performance\": {\"tensor_parallel_size\": 2},\n            \"sampling\": {\"temperature\": 0.1, \"max_tokens\": 512}\n        }\n        return FP8ModelManager(default_config)\n\n\ndef validate_fp8_environment() -> Dict[str, Any]:\n    \"\"\"Validate the environment for FP8 model execution\"\"\"\n    validation = {\n        \"status\": \"unknown\",\n        \"checks\": {},\n        \"recommendations\": []\n    }\n    \n    # Check TensorRT-LLM\n    validation[\"checks\"][\"tensorrt_llm\"] = TENSORRT_AVAILABLE\n    if not TENSORRT_AVAILABLE:\n        validation[\"recommendations\"].append(\"Install TensorRT-LLM: pip install tensorrt-llm\")\n    \n    # Check CUDA\n    validation[\"checks\"][\"cuda\"] = torch.cuda.is_available()\n    if not torch.cuda.is_available():\n        validation[\"recommendations\"].append(\"CUDA not available. Install CUDA toolkit.\")\n    \n    # Check GPU memory\n    if torch.cuda.is_available():\n        gpu_memory = torch.cuda.get_device_properties(0).total_memory / (1024**3)  # GB\n        validation[\"checks\"][\"gpu_memory_gb\"] = gpu_memory\n        validation[\"checks\"][\"sufficient_memory\"] = gpu_memory >= 40  # Minimum for FP8\n        \n        if gpu_memory < 40:\n            validation[\"recommendations\"].append(f\"Insufficient GPU memory: {gpu_memory:.1f}GB. Need at least 40GB for FP8 model.\")\n    \n    # Determine overall status\n    critical_checks = [\"tensorrt_llm\", \"cuda\", \"sufficient_memory\"]\n    if all(validation[\"checks\"].get(check, False) for check in critical_checks):\n        validation[\"status\"] = \"ready\"\n    elif validation[\"checks\"].get(\"tensorrt_llm\", False) and validation[\"checks\"].get(\"cuda\", False):\n        validation[\"status\"] = \"partial\"\n    else:\n        validation[\"status\"] = \"not_ready\"\n    \n    return validation\n\n\nif __name__ == \"__main__\":\n    # Test FP8 utilities\n    print(\"FP8 Model Utilities Test\")\n    print(\"=\" * 40)\n    \n    # Validate environment\n    env_status = validate_fp8_environment()\n    print(f\"Environment Status: {env_status['status']}\")\n    print(f\"Checks: {env_status['checks']}\")\n    if env_status['recommendations']:\n        print(\"Recommendations:\")\n        for rec in env_status['recommendations']:\n            print(f\"  - {rec}\")\n    \n    # Test model manager creation\n    try:\n        manager = create_fp8_manager()\n        print(f\"\\nModel Manager Created:\")\n        print(f\"Model: {manager.model_name}\")\n        print(f\"FP8 Enabled: {manager.use_fp8}\")\n        print(f\"Memory Savings: {manager.estimate_memory_savings()}\")\n        \n        # Test data conversion\n        test_tensor = torch.randn(4, 4)\n        converted = manager.convert_to_fp8(test_tensor)\n        print(f\"\\nData Conversion Test:\")\n        print(f\"Original shape: {test_tensor.shape}, dtype: {test_tensor.dtype}\")\n        print(f\"Converted shape: {converted.shape}, dtype: {converted.dtype}\")\n        \n    except Exception as e:\n        print(f\"Error testing model manager: {e}\")\n"},{"path":"diffu_moe_vlm/imu.py","text":"\"\"\"\n3D trajectory / IMU data utilities.\n\nTrajectory files are .npz archives with:\n    positions  (N, T, J, 3) float  joint positions (e.g. left hand, right hand, head)\n    timestamps (N, T) float        sample times in seconds (may be irregular)\n    mask       (N, T) bool         optional, True for valid samples\n    labels     (N,) int            optional, e.g. activity class\n`make_synthetic_trajectories` produces data in this format for testing.\n\"\"\"\n\nfrom pathlib import Path\nfrom typing import Dict, Optional\n\nimport numpy as np\n\nJOINTS = ('left_hand', 'right_hand', 'head')\nMOTIONS = ('idle', 'wave', 'chop', 'reach')\n\n\ndef make_synthetic_trajectories(num: int = 256, length: int = 64, rate_hz: float = 60.0,\n                                jitter: float = 0.3, seed: int = 0) -> Dict[str, np.ndarray]:\n    \"\"\"Synthetic hand/head motions (idle, wave, chop, reach) with irregular sampling\"\"\"\n    rng = np.random.default_rng(seed)\n    base = np.array([[-0.25, 1.1, 0.3], [0.25, 1.1, 0.3], [0.0, 1.65, 0.0]])  # left hand, right hand, head\n    positions = np.zeros((num, length, len(JOINTS), 3), dtype=np.float32)\n    timestamps = np.zeros((num, length), dtype=np.float32)\n    labels = rng.integers(len(MOTIONS), size=num)\n    for n in range(num):\n        dt = (1.0 / rate_hz) * (1 + jitter * rng.uniform(-1, 1, size=length))\n        t = np.cumsum(dt) - dt[0]\n        freq = rng.uniform(1.0, 2.0)\n        phase = rng.uniform(0, 2 * np.pi)\n        osc = np.sin(2 * np.pi * freq * t + phase)\n        pos = np.repeat(base[None], length, axis=0).copy()\n        motion = MOTIONS[labels[n]]\n        if motion == 'wave':        # right hand oscillates sideways, raised\n            pos[:, 1, 0] += 0.15 * osc\n            pos[:, 1, 1] += 0.4\n        elif motion == 'chop':      # both hands move up and down together\n            pos[:, :2, 1] += 0.25 * osc[:, None]\n        elif motion == 'reach':     # right hand extends forward and back\n            pos[:, 1, 2] += 0.3 * (osc + 1) / 2\n        pos += rng.normal(0, 0.01, size=pos.shape)                      # sensor noise\n        pos[:, 2] += rng.normal(0, 0.005, size=(length, 3)).cumsum(0)   # head drift\n        positions[n], timestamps[n] = pos, t\n    return {'positions': positions, 'timestamps': timestamps,\n            'mask': np.ones((num, length), dtype=bool), 'labels': labels.astype(np.int64)}\n\n\ndef save_trajectories(path, data: Dict[str, np.ndarray]):\n    Path(path).parent.mkdir(parents=True, exist_ok=True)\n    np.savez_compressed(path, **data)\n\n\ndef load_trajectories(path) -> Dict[str, np.ndarray]:\n    with np.load(path) as f:\n        data = {k: f[k] for k in f.files}\n    if 'positions' not in data or 'timestamps' not in data:\n        raise ValueError(\"trajectory file needs 'positions' (N,T,J,3) and 'timestamps' (N,T)\")\n    data.setdefault('mask', np.ones(data['timestamps'].shape, dtype=bool))\n    return data\n\n\ndef to_torch_batch(data: Dict[str, np.ndarray], index: Optional[np.ndarray] = None, device: str = 'cpu'):\n    \"\"\"Slice a trajectory dict into TrajectoryEncoder keyword arguments\"\"\"\n    import torch\n\n    index = slice(None) if index is None else index\n    return {\n        'positions': torch.as_tensor(data['positions'][index], dtype=torch.float32, device=device),\n        'timestamps': torch.as_tensor(data['timestamps'][index], dtype=torch.float32, device=device),\n        'mask': torch.as_tensor(data['mask'][index], dtype=torch.bool, device=device),\n    }\n"},{"path":"diffu_moe_vlm/jax_rl/__init__.py","text":"\"\"\"\nCraftax training in JAX (PureJaxRL style): environment, network and PPO run\nend-to-end under jit on one accelerator. Requires `pip install -e \".[jax]\"`\n(jax, flax, optax, craftax); use a CUDA build of jax for full-scale runs.\n\"\"\"\n"},{"path":"diffu_moe_vlm/jax_rl/networks.py","text":"\"\"\"Flax actor-critic networks: feed-forward, GRU (PPO-RNN) and an MoE layer\"\"\"\n\nimport functools\nfrom typing import Tuple\n\nimport distrax\nimport flax.linen as nn\nimport jax\nimport jax.numpy as jnp\nimport numpy as np\nfrom flax.linen.initializers import constant, orthogonal\n\n\ndef _act(name: str):\n    return {\"tanh\": nn.tanh, \"relu\": nn.relu, \"gelu\": nn.gelu}[name]\n\n\nclass MoEDense(nn.Module):\n    \"\"\"Top-k gated mixture of MLP experts; returns (output, load-balancing loss)\"\"\"\n    features: int\n    num_experts: int = 4\n    top_k: int = 2\n    activation: str = \"tanh\"\n\n    @nn.compact\n    def __call__(self, x):\n        logits = nn.Dense(self.num_experts, kernel_init=orthogonal(0.01), bias_init=constant(0.0))(x)\n        probs = jax.nn.softmax(logits, axis=-1)\n        top_vals, top_idx = jax.lax.top_k(probs, self.top_k)\n        weights = top_vals / top_vals.sum(-1, keepdims=True)\n        experts = [nn.Dense(self.features, kernel_init=orthogonal(np.sqrt(2)), bias_init=constant(0.0))\n                   for _ in range(self.num_experts)]\n        outs = jnp.stack([_act(self.activation)(e(x)) for e in experts], axis=-2)   # (..., E, F)\n        chosen = jnp.take_along_axis(outs, top_idx[..., None], axis=-2)              # (..., k, F)\n        y = (weights[..., None] * chosen).sum(-2)\n        flat_probs = probs.reshape(-1, self.num_experts)\n        load = jax.nn.one_hot(top_idx[..., 0].reshape(-1), self.num_experts).mean(0)\n        aux = self.num_experts * jnp.sum(load * flat_probs.mean(0))\n        return y, aux\n\n\nclass MLPTrunk(nn.Module):\n    \"\"\"`num_layers` hidden layers of width `width`; dense or MoE\"\"\"\n    width: int = 512\n    num_layers: int = 3\n    activation: str = \"tanh\"\n    moe: bool = False\n    num_experts: int = 4\n    top_k: int = 2\n\n    @nn.compact\n    def __call__(self, x):\n        aux = jnp.zeros(())\n        for _ in range(self.num_layers):\n            if self.moe:\n                x, a = MoEDense(self.width, self.num_experts, self.top_k, self.activation)(x)\n                aux = aux + a\n            else:\n                x = _act(self.activation)(nn.Dense(self.width, kernel_init=orthogonal(np.sqrt(2)),\n                                                   bias_init=constant(0.0))(x))\n        return x, aux\n\n\nclass ActorCritic(nn.Module):\n    \"\"\"Craftax-baseline style feed-forward actor-critic (separate actor and critic trunks)\"\"\"\n    action_dim: int\n    width: int = 512\n    num_layers: int = 3\n    activation: str = \"tanh\"\n    moe: bool = False\n    num_experts: int = 4\n    top_k: int = 2\n\n    @nn.compact\n    def __call__(self, x):\n        trunk = functools.partial(MLPTrunk, self.width, self.num_layers, self.activation,\n                                  self.moe, self.num_experts, self.top_k)\n        a, aux_a = trunk()(x)\n        logits = nn.Dense(self.action_dim, kernel_init=orthogonal(0.01), bias_init=constant(0.0))(a)\n        c, aux_c = trunk()(x)\n        value = nn.Dense(1, kernel_init=orthogonal(1.0), bias_init=constant(0.0))(c)\n        return distrax.Categorical(logits=logits), jnp.squeeze(value, -1), aux_a + aux_c\n\n\nclass ScannedGRU(nn.Module):\n    \"\"\"GRU scanned over time; the hidden state is reset where `resets` is true\"\"\"\n\n    @functools.partial(\n        nn.scan, variable_broadcast=\"params\", in_axes=0, out_axes=0, split_rngs={\"params\": False})\n    @nn.compact\n    def __call__(self, carry, x):\n        ins, resets = x\n        carry = jnp.where(resets[:, None], self.initialize_carry(ins.shape[0], ins.shape[-1]), carry)\n        new_carry, y = nn.GRUCell(features=ins.shape[-1])(carry, ins)\n        return new_carry, y\n\n    @staticmethod\n    def initialize_carry(batch_size: int, hidden_size: int):\n        return jnp.zeros((batch_size, hidden_size))\n\n\nclass ActorCriticRNN(nn.Module):\n    \"\"\"PPO-RNN: embedding -> GRU -> actor / critic heads. Inputs are (T, B, ...)\"\"\"\n    action_dim: int\n    width: int = 512\n    activation: str = \"relu\"\n    moe: bool = False\n    num_experts: int = 4\n    top_k: int = 2\n\n    @nn.compact\n    def __call__(self, hidden, x):\n        obs, dones = x\n        emb = _act(self.activation)(nn.Dense(self.width, kernel_init=orthogonal(np.sqrt(2)),\n                                             bias_init=constant(0.0))(obs))\n        hidden, emb = ScannedGRU()(hidden, (emb, dones))\n        a, aux_a = MLPTrunk(self.width, 1, self.activation, self.moe, self.num_experts, self.top_k)(emb)\n        logits = nn.Dense(self.action_dim, kernel_init=orthogonal(0.01), bias_init=constant(0.0))(a)\n        c, aux_c = MLPTrunk(self.width, 1, self.activation, self.moe, self.num_experts, self.top_k)(emb)\n        value = nn.Dense(1, kernel_init=orthogonal(1.0), bias_init=constant(0.0))(c)\n        return hidden, distrax.Categorical(logits=logits), jnp.squeeze(value, -1), aux_a + aux_c\n\n\nclass ICM(nn.Module):\n    \"\"\"Intrinsic Curiosity Module (Pathak et al., 2017): encoder, inverse and forward models\"\"\"\n    action_dim: int\n    feature_dim: int = 256\n    width: int = 256\n\n    def setup(self):\n        self.encoder = nn.Sequential([nn.Dense(self.width), nn.relu, nn.Dense(self.feature_dim)])\n        self.inverse = nn.Sequential([nn.Dense(self.width), nn.relu, nn.Dense(self.action_dim)])\n        self.forward_model = nn.Sequential([nn.Dense(self.width), nn.relu, nn.Dense(self.feature_dim)])\n\n    def __call__(self, obs, next_obs, action) -> Tuple[jax.Array, jax.Array, jax.Array]:\n        \"\"\"Returns (inverse_logits, predicted next features, next features)\"\"\"\n        phi, phi_next = self.encoder(obs), self.encoder(next_obs)\n        inverse_logits = self.inverse(jnp.concatenate([phi, phi_next], -1))\n        pred_next = self.forward_model(\n            jnp.concatenate([jax.lax.stop_gradient(phi), jax.nn.one_hot(action, self.action_dim)], -1))\n        return inverse_logits, pred_next, phi_next\n\n\ndef num_params(params) -> int:\n    return int(sum(np.prod(p.shape) for p in jax.tree_util.tree_leaves(params)))\n\n"},{"path":"diffu_moe_vlm/jax_rl/ppo.py","text":"\"\"\"\nPPO / PPO-RNN for Craftax in pure JAX (after PureJaxRL and the Craftax baselines).\n\n`make_train(config)` returns a function `train(rng)` that runs the whole\ntraining loop under `jax.lax.scan`, so it can be jitted end to end. Options:\n    rnn   GRU memory (PPO-RNN); otherwise the feed-forward baseline network\n    moe   top-k mixture-of-experts hidden layers (+ load-balancing loss)\n    icm   Intrinsic Curiosity Module bonus: icm_reward_coef * error / scale, where\n          `icm_normalize` picks the scale (see ICM_NORMALIZERS):\n            mean  running mean of all forward-model errors so far (default).\n                  The first batch averages exactly 1; later batches average\n                  (current mean error / all-time mean error), and single steps\n                  are unbounded. It sets the typical scale, not a hard limit\n            ema   exponential moving mean (`icm_ema_decay` per update), which\n                  follows the error as the forward model improves\n            std   running standard deviation. Not enough on its own: the\n                  error's mean is much larger than its spread, so the bonus\n                  stays ~10x too large\n            none  raw error; the unscaled bonus is what made the reference ICM\n                  run collapse to ~0 extrinsic reward\n          The icm/* metrics track the raw error, the bonus and its share of the\n          total reward, to detect a runaway bonus (run_icm_ablation.py).\n\nPer update, metrics (episode return/length and achievement success rates of\nepisodes that finished in that update, losses) are returned stacked and, if\n`log_fn` is given, streamed to Python with `jax.debug.callback`.\n\"\"\"\n\nimport os\nfrom typing import Any, Callable, Dict, NamedTuple, Optional\n\nimport flax.linen as nn\nimport jax\nimport jax.numpy as jnp\nimport numpy as np\nimport optax\nfrom flax.training.train_state import TrainState\n\nfrom .networks import ICM, ActorCritic, ActorCriticRNN, ScannedGRU\nfrom .wrappers import make_vec_env\n\nDEFAULT_CONFIG: Dict[str, Any] = {\n    # Values follow the Craftax PPO baselines; check them against the run you want to reproduce\n    \"env_name\": \"Craftax-Symbolic-v1\",\n    \"total_timesteps\": 1_000_000_000,\n    \"num_envs\": 1024,\n    \"num_steps\": 64,\n    \"update_epochs\": 4,\n    \"num_minibatches\": 8,\n    \"lr\": 2e-4,\n    \"anneal_lr\": True,\n    \"gamma\": 0.99,\n    \"gae_lambda\": 0.8,\n    \"clip_eps\": 0.2,\n    \"ent_coef\": 0.01,\n    \"vf_coef\": 0.5,\n    \"max_grad_norm\": 1.0,\n    \"layer_size\": 512,\n    \"num_layers\": 3,\n    \"activation\": \"tanh\",\n    \"rnn\": False,\n    \"moe\": False,\n    \"num_experts\": 4,\n    \"top_k\": 2,\n    \"moe_aux_coef\": 0.01,\n    \"optimistic_resets\": True,\n    \"reset_ratio\": 16,\n    \"icm\": False,\n    \"icm_reward_coef\": 0.01,\n    \"icm_lr\": 3e-4,\n    \"icm_forward_coef\": 1.0,\n    \"icm_inverse_coef\": 1.0,\n    \"icm_normalize\": \"mean\",\n    \"icm_ema_decay\": 0.99,\n}\n\nICM_NORMALIZERS = (\"none\", \"std\", \"mean\", \"ema\")\n\n\nclass Transition(NamedTuple):\n    reset: jax.Array      # episode ended before this observation (resets the RNN state)\n    done: jax.Array       # episode ended after this step\n    action: jax.Array\n    value: jax.Array\n    reward: jax.Array\n    log_prob: jax.Array\n    obs: jax.Array\n    info: Dict[str, jax.Array]\n\n\nclass RunningMoments(NamedTuple):\n    mean: jax.Array\n    var: jax.Array\n    count: jax.Array\n\n\ndef update_moments(m: RunningMoments, x: jax.Array) -> RunningMoments:\n    \"\"\"Parallel (Chan et al.) update of running mean/variance with a batch\"\"\"\n    b_mean, b_var, b_count = x.mean(), x.var(), x.size\n    delta = b_mean - m.mean\n    total = m.count + b_count\n    mean = m.mean + delta * b_count / total\n    m2 = m.var * m.count + b_var * b_count + delta ** 2 * m.count * b_count / total\n    return RunningMoments(mean, m2 / total, total)\n\n\ndef update_ema(m: RunningMoments, x: jax.Array, decay: float) -> RunningMoments:\n    \"\"\"Exponential moving mean of batch means (`count` = number of batches; the first batch initializes it)\"\"\"\n    b_mean = x.mean()\n    mean = jnp.where(m.count < 1, b_mean, decay * m.mean + (1.0 - decay) * b_mean)\n    return RunningMoments(mean, m.var, jnp.floor(m.count) + 1)\n\n\ndef icm_normalizer(config) -> str:\n    \"\"\"`icm_normalize` as a mode name; booleans from older configs map to mean / none\"\"\"\n    mode = config[\"icm_normalize\"]\n    if isinstance(mode, bool):\n        mode = \"mean\" if mode else \"none\"\n    if mode not in ICM_NORMALIZERS:\n        raise ValueError(f\"icm_normalize must be one of {ICM_NORMALIZERS}, got {mode!r}\")\n    return mode\n\n\ndef craftax_score(rates: jax.Array) -> jax.Array:\n    \"\"\"Crafter/Craftax score: geometric mean of success rates in %, exp(mean(ln(1 + s))) - 1\"\"\"\n    return jnp.exp(jnp.log1p(rates).mean()) - 1.0\n\n\ndef compute_gae(rewards, values, dones, last_value, gamma: float, gae_lambda: float):\n    \"\"\"Generalized advantage estimation over (T, B) arrays; `dones[t]` ends the episode after step t\"\"\"\n    def step(carry, x):\n        gae, next_value = carry\n        reward, value, done = x\n        not_done = 1.0 - done.astype(jnp.float32)\n        delta = reward + gamma * next_value * not_done - value\n        gae = delta + gamma * gae_lambda * not_done * gae\n        return (gae, value), gae\n\n    _, advantages = jax.lax.scan(step, (jnp.zeros_like(last_value), last_value), (rewards, values, dones),\n                                 reverse=True)\n    return advantages, advantages + values\n\n\ndef build_network(config, action_dim: int) -> nn.Module:\n    common = dict(action_dim=action_dim, width=config[\"layer_size\"], moe=config[\"moe\"],\n                  num_experts=config[\"num_experts\"], top_k=config[\"top_k\"])\n    if config[\"rnn\"]:\n        return ActorCriticRNN(activation=\"relu\" if config[\"activation\"] == \"tanh\" else config[\"activation\"], **common)\n    return ActorCritic(num_layers=config[\"num_layers\"], activation=config[\"activation\"], **common)\n\n\ndef make_train(config: Dict[str, Any], log_fn: Optional[Callable[[Dict, int], None]] = None):\n    config = {**DEFAULT_CONFIG, **config}\n    env, env_params = make_vec_env(config[\"env_name\"], config[\"num_envs\"],\n                                   config[\"optimistic_resets\"], config[\"reset_ratio\"])\n    num_envs, num_steps = config[\"num_envs\"], config[\"num_steps\"]\n    num_updates = config[\"total_timesteps\"] // num_steps // num_envs\n    assert num_updates > 0, \"total_timesteps must be at least num_envs * num_steps\"\n    assert num_envs % config[\"num_minibatches\"] == 0\n    action_dim = env.action_space(env_params).n\n    obs_dim = env.observation_space(env_params).shape[0]\n    network = build_network(config, action_dim)\n    rnn = config[\"rnn\"]\n    icm_net = ICM(action_dim) if config[\"icm\"] else None\n    icm_mode = icm_normalizer(config)\n\n    def lr_schedule(count):\n        frac = 1.0 - (count // (config[\"num_minibatches\"] * config[\"update_epochs\"])) / num_updates\n        return config[\"lr\"] * frac\n\n    def apply_net(params, hstate, obs, reset):\n        \"\"\"obs/reset are (T, B, ...) for the RNN and (..., obs_dim) for the feed-forward net\"\"\"\n        if rnn:\n            return network.apply(params, hstate, (obs, reset))\n        pi, value, aux = network.apply(params, obs)\n        return hstate, pi, value, aux\n\n    def init_runner(rng):\n        rng, k_net, k_icm, k_env = jax.random.split(rng, 4)\n        init_h = ScannedGRU.initialize_carry(num_envs, config[\"layer_size\"])\n        if rnn:\n            params = network.init(k_net, init_h, (jnp.zeros((1, num_envs, obs_dim)), jnp.zeros((1, num_envs), bool)))\n        else:\n            params = network.init(k_net, jnp.zeros((1, obs_dim)))\n        lr = lr_schedule if config[\"anneal_lr\"] else config[\"lr\"]\n        tx = optax.chain(optax.clip_by_global_norm(config[\"max_grad_norm\"]), optax.adam(lr, eps=1e-5))\n        train_state = TrainState.create(apply_fn=network.apply, params=params, tx=tx)\n\n        if icm_net is not None:\n            icm_params = icm_net.init(k_icm, jnp.zeros((1, obs_dim)), jnp.zeros((1, obs_dim)), jnp.zeros((1,), jnp.int32))\n            icm_state = TrainState.create(apply_fn=icm_net.apply, params=icm_params,\n                                          tx=optax.adam(config[\"icm_lr\"]))\n        else:\n            icm_state = None\n        moments = RunningMoments(jnp.zeros(()), jnp.ones(()), jnp.asarray(1e-4))\n\n        obs, env_state = env.reset(k_env, env_params)\n        return (train_state, icm_state, moments, env_state, obs, jnp.zeros(num_envs, bool), init_h, rng)\n\n    def update_step(runner, update_idx):\n        train_state, icm_state, moments, env_state, last_obs, last_done, hstate, rng = runner\n        init_hstate = hstate\n\n        # ---- rollout ----\n        def env_step(carry, _):\n            train_state, env_state, last_obs, last_done, hstate, rng = carry\n            rng, k_act, k_env = jax.random.split(rng, 3)\n            if rnn:\n                hstate, pi, value, _ = apply_net(train_state.params, hstate, last_obs[None], last_done[None])\n                pi_logits, value = pi.logits[0], value[0]\n                pi = type(pi)(logits=pi_logits)\n            else:\n                _, pi, value, _ = apply_net(train_state.params, None, last_obs, None)\n            action = pi.sample(seed=k_act)\n            log_prob = pi.log_prob(action)\n            obs, env_state, reward, done, info = env.step(k_env, env_state, action, env_params)\n            t = Transition(last_done, done, action, value, reward, log_prob, last_obs, info)\n            return (train_state, env_state, obs, done, hstate, rng), t\n\n        (train_state, env_state, last_obs, last_done, hstate, rng), traj = jax.lax.scan(\n            env_step, (train_state, env_state, last_obs, last_done, hstate, rng), None, num_steps)\n\n        # ---- intrinsic reward (ICM) ----\n        ext_reward = traj.reward\n        icm_metrics = {}\n        if icm_net is not None:\n            next_obs = jnp.concatenate([traj.obs[1:], last_obs[None]], 0)\n            flat = lambda x: x.reshape((-1,) + x.shape[2:])\n\n            def icm_loss(p):\n                inv_logits, pred, phi_next = icm_net.apply(p, flat(traj.obs), flat(next_obs), flat(traj.action))\n                valid = 1.0 - flat(traj.done).astype(jnp.float32)\n                fwd_err = 0.5 * jnp.sum((pred - jax.lax.stop_gradient(phi_next)) ** 2, -1)\n                inv_loss = optax.softmax_cross_entropy_with_integer_labels(inv_logits, flat(traj.action))\n                denom = jnp.maximum(valid.sum(), 1.0)\n                loss = (config[\"icm_forward_coef\"] * (fwd_err * valid).sum() / denom\n                        + config[\"icm_inverse_coef\"] * (inv_loss * valid).sum() / denom)\n                return loss, (fwd_err * valid, (fwd_err * valid).sum() / denom, (inv_loss * valid).sum() / denom)\n\n            (_, (intrinsic, fwd_loss, inv_loss)), grads = jax.value_and_grad(icm_loss, has_aux=True)(icm_state.params)\n            icm_state = icm_state.apply_gradients(grads=grads)\n            raw = jax.lax.stop_gradient(intrinsic).reshape(ext_reward.shape)\n            if icm_mode == \"mean\":\n                moments = update_moments(moments, raw)\n                scale = moments.mean\n            elif icm_mode == \"std\":\n                moments = update_moments(moments, raw)\n                scale = jnp.sqrt(moments.var)\n            elif icm_mode == \"ema\":\n                moments = update_ema(moments, raw, config[\"icm_ema_decay\"])\n                scale = moments.mean\n            else:\n                scale = jnp.ones(())\n            intrinsic = raw / (scale + 1e-8)\n            bonus = config[\"icm_reward_coef\"] * intrinsic\n            traj = traj._replace(reward=ext_reward + bonus)\n            bonus_sum, ext_sum = jnp.abs(bonus).sum(), jnp.abs(ext_reward).sum()\n            icm_metrics = {\"icm/forward_loss\": fwd_loss, \"icm/inverse_loss\": inv_loss,\n                           \"icm/intrinsic_reward\": intrinsic.mean(), \"icm/extrinsic_reward\": ext_reward.mean(),\n                           \"icm/raw_error_mean\": raw.mean(), \"icm/raw_error_max\": raw.max(), \"icm/scale\": scale,\n                           \"icm/bonus_mean\": bonus.mean(), \"icm/bonus_max\": bonus.max(),\n                           # share of |reward| that is curiosity bonus; near 1 means the bonus has taken over\n                           \"icm/bonus_share\": bonus_sum / jnp.maximum(bonus_sum + ext_sum, 1e-8)}\n\n        # ---- GAE ----\n        _, _, last_val, _ = apply_net(train_state.params, hstate,\n                                      last_obs[None] if rnn else last_obs, last_done[None] if rnn else None)\n        last_val = last_val[0] if rnn else last_val\n\n        advantages, targets = compute_gae(traj.reward, traj.value, traj.done, last_val,\n                                          config[\"gamma\"], config[\"gae_lambda\"])\n\n        # ---- PPO update ----\n        def loss_fn(params, h0, batch, adv, tgt):\n            if rnn:\n                _, pi, value, aux = apply_net(params, h0, batch.obs, batch.reset)\n            else:\n                _, pi, value, aux = apply_net(params, None, batch.obs, None)\n            log_prob = pi.log_prob(batch.action)\n            v_clipped = batch.value + jnp.clip(value - batch.value, -config[\"clip_eps\"], config[\"clip_eps\"])\n            value_loss = 0.5 * jnp.maximum((value - tgt) ** 2, (v_clipped - tgt) ** 2).mean()\n            ratio = jnp.exp(log_prob - batch.log_prob)\n            adv = (adv - adv.mean()) / (adv.std() + 1e-8)\n            actor_loss = -jnp.minimum(ratio * adv, jnp.clip(ratio, 1 - config[\"clip_eps\"],\n                                                             1 + config[\"clip_eps\"]) * adv).mean()\n            entropy = pi.entropy().mean()\n            total = actor_loss + config[\"vf_coef\"] * value_loss - config[\"ent_coef\"] * entropy \\\n                + config[\"moe_aux_coef\"] * aux\n            return total, (value_loss, actor_loss, entropy, aux)\n\n        def epoch(carry, _):\n            train_state, rng = carry\n            rng, k = jax.random.split(rng)\n            nmb = config[\"num_minibatches\"]\n            batch = traj._replace(info={})  # info is only needed for logging\n            if rnn:\n                # Keep sequences intact: shuffle environments and minibatch along the env axis\n                perm = jax.random.permutation(k, num_envs)\n                h = jnp.take(init_hstate, perm, axis=0)\n                b, a, tg = jax.tree.map(lambda x: jnp.take(x, perm, axis=1), (batch, advantages, targets))\n\n                def split_envs(x):  # (T, B, ...) -> (nmb, T, B // nmb, ...)\n                    return jnp.swapaxes(x.reshape((x.shape[0], nmb, -1) + x.shape[2:]), 0, 1)\n\n                mbs = (h.reshape((nmb, -1) + h.shape[1:]),) + tuple(jax.tree.map(split_envs, (b, a, tg)))\n            else:\n                batch_size = num_steps * num_envs\n                perm = jax.random.permutation(k, batch_size)\n                flat = jax.tree.map(lambda x: x.reshape((batch_size,) + x.shape[2:]), (batch, advantages, targets))\n                flat = jax.tree.map(lambda x: jnp.take(x, perm, axis=0), flat)\n                b, a, tg = jax.tree.map(lambda x: x.reshape((nmb, -1) + x.shape[1:]), flat)\n                mbs = (jnp.zeros((nmb,)), b, a, tg)\n\n            def minibatch(train_state, mb):\n                h0, b, a, tg = mb\n                (loss, aux), grads = jax.value_and_grad(loss_fn, has_aux=True)(train_state.params, h0, b, a, tg)\n                return train_state.apply_gradients(grads=grads), (loss, *aux)\n\n            train_state, losses = jax.lax.scan(minibatch, train_state, mbs)\n            return (train_state, rng), losses\n\n        (train_state, rng), losses = jax.lax.scan(epoch, (train_state, rng), None, config[\"update_epochs\"])\n\n        # ---- metrics ----\n        info = traj.info\n        done = info[\"returned_episode\"].astype(jnp.float32)\n        n_eps = done.sum()\n        denom = jnp.maximum(n_eps, 1.0)\n        metrics = {\n            \"episodes\": n_eps,\n            \"episode_return\": (info[\"returned_episode_returns\"] * done).sum() / denom,\n            \"episode_length\": (info[\"returned_episode_lengths\"] * done).sum() / denom,\n            \"loss/total\": losses[0].mean(), \"loss/value\": losses[1].mean(), \"loss/actor\": losses[2].mean(),\n            \"loss/entropy\": losses[3].mean(), \"loss/moe_aux\": losses[4].mean(),\n            \"update\": update_idx + 1,\n            \"env_steps\": (update_idx + 1) * num_steps * num_envs,\n        }\n        rates = []\n        for key, value in info.items():\n            if key.startswith(\"Achievements/\"):\n                metrics[key] = value.sum() / denom  # success rate in %, info is already scaled by done * 100\n                rates.append(metrics[key])\n        if rates:\n            rates = jnp.stack(rates)\n            metrics[\"achievements\"] = (rates / 100.0).sum()  # mean distinct achievements per finished episode\n            # exploration: how many achievement types were reached at all in this update, and the score\n            metrics[\"achievement_coverage\"] = (rates > 0).sum().astype(jnp.float32)\n            metrics[\"craftax_score\"] = craftax_score(rates)\n        metrics.update(icm_metrics)\n        if log_fn is not None:\n            jax.debug.callback(log_fn, metrics, update_idx)\n        runner = (train_state, icm_state, moments, env_state, last_obs, last_done, hstate, rng)\n        return runner, metrics\n\n    def train(rng):\n        runner, metrics = jax.lax.scan(update_step, init_runner(rng), jnp.arange(num_updates))\n        return {\"runner_state\": runner, \"metrics\": metrics}\n\n    def run_updates(runner, start, num):\n        \"\"\"Run `num` updates starting at update index `start` (for chunked / resumable training)\"\"\"\n        return jax.lax.scan(update_step, runner, start + jnp.arange(num))\n\n    train.config = config\n    train.num_updates = num_updates\n    train.init = init_runner\n    train.run_updates = jax.jit(run_updates, static_argnums=(2,))\n    return train\n\n\ndef save_runner(path, runner, next_update: int):\n    \"\"\"Save the full training state (params, optimizer, env states, RNG) to an .npz file\"\"\"\n    leaves = jax.tree_util.tree_leaves(jax.device_get(runner))\n    tmp = str(path) + \".tmp.npz\"\n    np.savez(tmp, next_update=np.asarray(next_update), **{f\"leaf_{i}\": np.asarray(x) for i, x in enumerate(leaves)})\n    os.replace(tmp, path)\n\n\ndef load_runner(path, template):\n    \"\"\"Restore a runner saved by `save_runner` using `template` (e.g. `train.init(rng)`) for the structure\"\"\"\n    treedef = jax.tree_util.tree_structure(template)\n    with np.load(path) as f:\n        leaves = [jnp.asarray(f[f\"leaf_{i}\"]) for i in range(treedef.num_leaves)]\n        next_update = int(f[\"next_update\"])\n    return jax.tree_util.tree_unflatten(treedef, leaves), next_update\n"},{"path":"diffu_moe_vlm/jax_rl/wrappers.py","text":"\"\"\"Vectorized Craftax wrappers: batching, optimistic resets and episode logging\"\"\"\n\nfrom functools import partial\n\nimport chex\nimport jax\nimport jax.numpy as jnp\nfrom flax import struct\n\n\nclass BatchEnv:\n    \"\"\"vmap reset/step over `num_envs` environments (env must auto-reset)\"\"\"\n\n    def __init__(self, env, num_envs: int):\n        self._env = env\n        self.num_envs = num_envs\n\n    def __getattr__(self, name):\n        return getattr(self._env, name)\n\n    @partial(jax.jit, static_argnums=(0,))\n    def reset(self, key, params=None):\n        return jax.vmap(self._env.reset, in_axes=(0, None))(jax.random.split(key, self.num_envs), params)\n\n    @partial(jax.jit, static_argnums=(0,))\n    def step(self, key, state, action, params=None):\n        keys = jax.random.split(key, self.num_envs)\n        return jax.vmap(self._env.step, in_axes=(0, 0, 0, None))(keys, state, action, params)\n\n\nclass OptimisticResetBatchEnv:\n    \"\"\"\n    Batched env where only `num_envs // reset_ratio` fresh worlds are generated\n    per step and finished environments draw from that pool. World generation\n    is the most expensive part of a Craftax step, so this is much faster than\n    resetting every env every step. Wrap an env created with `auto_reset=False`.\n    \"\"\"\n\n    def __init__(self, env, num_envs: int, reset_ratio: int = 16):\n        assert num_envs % reset_ratio == 0, \"num_envs must be divisible by reset_ratio\"\n        self._env = env\n        self.num_envs = num_envs\n        self.num_resets = num_envs // reset_ratio\n\n    def __getattr__(self, name):\n        return getattr(self._env, name)\n\n    @partial(jax.jit, static_argnums=(0,))\n    def reset(self, key, params=None):\n        return jax.vmap(self._env.reset, in_axes=(0, None))(jax.random.split(key, self.num_envs), params)\n\n    @partial(jax.jit, static_argnums=(0,))\n    def step(self, key, state, action, params=None):\n        key_step, key_reset, key_pick = jax.random.split(key, 3)\n        obs_st, state_st, reward, done, info = jax.vmap(self._env.step_env, in_axes=(0, 0, 0, None))(\n            jax.random.split(key_step, self.num_envs), state, action, params)\n        obs_re, state_re = jax.vmap(self._env.reset_env, in_axes=(0, None))(\n            jax.random.split(key_reset, self.num_resets), params)\n        # Each done env takes a fresh world; distinct done envs take distinct worlds when possible\n        rank = jnp.cumsum(done) - 1\n        pick = jnp.where(rank < self.num_resets, rank,\n                         jax.random.randint(key_pick, (self.num_envs,), 0, self.num_resets))\n        pick = jnp.clip(pick, 0, self.num_resets - 1)\n\n        def select(fresh, stepped):\n            fresh = fresh[pick]\n            mask = done.reshape((-1,) + (1,) * (stepped.ndim - 1))\n            return jnp.where(mask, fresh, stepped)\n\n        state = jax.tree.map(select, state_re, state_st)\n        obs = select(obs_re, obs_st)\n        return obs, state, reward, done, info\n\n\n@struct.dataclass\nclass LogEnvState:\n    env_state: chex.ArrayTree\n    episode_returns: jax.Array\n    episode_lengths: jax.Array\n    returned_episode_returns: jax.Array\n    returned_episode_lengths: jax.Array\n    timestep: jax.Array\n\n\nclass LogWrapper:\n    \"\"\"Tracks per-env episode return/length; adds them to `info` at episode end\"\"\"\n\n    def __init__(self, env):\n        self._env = env\n\n    def __getattr__(self, name):\n        return getattr(self._env, name)\n\n    @partial(jax.jit, static_argnums=(0,))\n    def reset(self, key, params=None):\n        obs, env_state = self._env.reset(key, params)\n        n = obs.shape[0]\n        zeros_f, zeros_i = jnp.zeros(n, jnp.float32), jnp.zeros(n, jnp.int32)\n        return obs, LogEnvState(env_state, zeros_f, zeros_i, zeros_f, zeros_i, zeros_i)\n\n    @partial(jax.jit, static_argnums=(0,))\n    def step(self, key, state: LogEnvState, action, params=None):\n        obs, env_state, reward, done, info = self._env.step(key, state.env_state, action, params)\n        new_returns = state.episode_returns + reward\n        new_lengths = state.episode_lengths + 1\n        state = LogEnvState(\n            env_state=env_state,\n            episode_returns=new_returns * (1 - done),\n            episode_lengths=new_lengths * (1 - done),\n            returned_episode_returns=jnp.where(done, new_returns, state.returned_episode_returns),\n            returned_episode_lengths=jnp.where(done, new_lengths, state.returned_episode_lengths),\n            timestep=state.timestep + 1,\n        )\n        info = dict(info)\n        info[\"returned_episode\"] = done\n        info[\"returned_episode_returns\"] = state.returned_episode_returns\n        info[\"returned_episode_lengths\"] = state.returned_episode_lengths\n        return obs, state, reward, done, info\n\n\ndef make_vec_env(env_name: str, num_envs: int, optimistic_resets: bool = True, reset_ratio: int = 16):\n    from craftax.craftax_env import make_craftax_env_from_name\n\n    if optimistic_resets:\n        env = make_craftax_env_from_name(env_name, auto_reset=False)\n        vec = OptimisticResetBatchEnv(env, num_envs, min(reset_ratio, num_envs))\n    else:\n        env = make_craftax_env_from_name(env_name, auto_reset=True)\n        vec = BatchEnv(env, num_envs)\n    return LogWrapper(vec), env.default_params\n"},{"path":"diffu_moe_vlm/minedojo_tasks.py","text":"\"\"\"\nMineDojo Task Configuration for Diffu_MoE_VLM\nMaps MineDojo benchmark tasks to the current project structure\n\"\"\"\n\nfrom typing import Dict, List, Any, Optional\nimport json\nfrom pathlib import Path\n\n\nclass TaskRegistry:\n    \"\"\"Registry for MineDojo-style tasks adapted for Diffu_MoE_VLM\"\"\"\n    \n    # Programmatic tasks from MineDojo benchmark suite\n    PROGRAMMATIC_TASKS = {\n        # Survival tasks\n        \"survive_1_day\": {\n            \"type\": \"survival\",\n            \"description\": \"Survive for 1 Minecraft day (20 minutes)\",\n            \"success_criteria\": {\"days_survived\": 1},\n            \"max_steps\": 24000,  # 20 minutes at 20 TPS\n            \"difficulty\": \"easy\"\n        },\n        \"survive_3_days\": {\n            \"type\": \"survival\", \n            \"description\": \"Survive for 3 Minecraft days\",\n            \"success_criteria\": {\"days_survived\": 3},\n            \"max_steps\": 72000,\n            \"difficulty\": \"medium\"\n        },\n        \n        # Harvest tasks\n        \"obtain_wooden_slab\": {\n            \"type\": \"harvest\",\n            \"description\": \"Obtain wooden slab from wooden planks\",\n            \"success_criteria\": {\"wooden_slab\": 1},\n            \"max_steps\": 1000,\n            \"difficulty\": \"easy\",\n            \"required_items\": [\"wooden_planks\"]\n        },\n        \"obtain_stone_stairs\": {\n            \"type\": \"harvest\",\n            \"description\": \"Craft stone stairs from cobblestone\", \n            \"success_criteria\": {\"stone_stairs\": 1},\n            \"max_steps\": 2000,\n            \"difficulty\": \"medium\",\n            \"required_items\": [\"cobblestone\"]\n        },\n        \"obtain_painting\": {\n            \"type\": \"harvest\",\n            \"description\": \"Craft painting from sticks and wool\",\n            \"success_criteria\": {\"painting\": 1},\n            \"max_steps\": 3000,\n            \"difficulty\": \"medium\",\n            \"required_items\": [\"stick\", \"wool\"]\n        },\n        \"harvest_milk\": {\n            \"type\": \"harvest\",\n            \"description\": \"Obtain milk from a cow\",\n            \"success_criteria\": {\"milk_bucket\": 1},\n            \"max_steps\": 2000,\n            \"difficulty\": \"easy\",\n            \"required_items\": [\"bucket\"]\n        },\n        \"harvest_wool\": {\n            \"type\": \"harvest\",\n            \"description\": \"Shear wool from a sheep\",\n            \"success_criteria\": {\"wool\": 1},\n            \"max_steps\": 1500,\n            \"difficulty\": \"easy\",\n            \"required_items\": [\"shears\"]\n        },\n        \n        # Mining tasks\n        \"mine_cobblestone\": {\n            \"type\": \"mining\",\n            \"description\": \"Mine cobblestone with pickaxe\",\n            \"success_criteria\": {\"cobblestone\": 8},\n            \"max_steps\": 1500,\n            \"difficulty\": \"easy\",\n            \"required_items\": [\"wooden_pickaxe\"]\n        },\n        \"mine_iron_ore\": {\n            \"type\": \"mining\",\n            \"description\": \"Mine iron ore with stone pickaxe\",\n            \"success_criteria\": {\"iron_ore\": 3},\n            \"max_steps\": 3000,\n            \"difficulty\": \"medium\",\n            \"required_items\": [\"stone_pickaxe\"]\n        },\n        \"mine_diamond\": {\n            \"type\": \"mining\",\n            \"description\": \"Mine diamond with iron pickaxe\",\n            \"success_criteria\": {\"diamond\": 1},\n            \"max_steps\": 5000,\n            \"difficulty\": \"hard\",\n            \"required_items\": [\"iron_pickaxe\"]\n        },\n        \n        # Tech tree tasks\n        \"craft_wooden_pickaxe\": {\n            \"type\": \"tech_tree\",\n            \"description\": \"Craft wooden pickaxe from planks and sticks\",\n            \"success_criteria\": {\"wooden_pickaxe\": 1},\n            \"max_steps\": 1000,\n            \"difficulty\": \"easy\",\n            \"required_items\": [\"wooden_planks\", \"stick\"]\n        },\n        \"craft_stone_pickaxe\": {\n            \"type\": \"tech_tree\",\n            \"description\": \"Craft stone pickaxe from cobblestone and sticks\",\n            \"success_criteria\": {\"stone_pickaxe\": 1},\n            \"max_steps\": 2000,\n            \"difficulty\": \"medium\",\n            \"required_items\": [\"cobblestone\", \"stick\"]\n        },\n        \"craft_iron_pickaxe\": {\n            \"type\": \"tech_tree\",\n            \"description\": \"Craft iron pickaxe from iron ingots and sticks\",\n            \"success_criteria\": {\"iron_pickaxe\": 1},\n            \"max_steps\": 4000,\n            \"difficulty\": \"hard\",\n            \"required_items\": [\"iron_ingot\", \"stick\"]\n        },\n        \"craft_diamond_pickaxe\": {\n            \"type\": \"tech_tree\",\n            \"description\": \"Craft diamond pickaxe from diamonds and sticks\",\n            \"success_criteria\": {\"diamond_pickaxe\": 1},\n            \"max_steps\": 6000,\n            \"difficulty\": \"very_hard\",\n            \"required_items\": [\"diamond\", \"stick\"]\n        },\n        \n        # Combat tasks\n        \"combat_zombie\": {\n            \"type\": \"combat\",\n            \"description\": \"Defeat a zombie with sword\",\n            \"success_criteria\": {\"zombies_defeated\": 1},\n            \"max_steps\": 2000,\n            \"difficulty\": \"medium\",\n            \"required_items\": [\"wooden_sword\"]\n        },\n        \"combat_skeleton\": {\n            \"type\": \"combat\", \n            \"description\": \"Defeat a skeleton with sword and shield\",\n            \"success_criteria\": {\"skeletons_defeated\": 1},\n            \"max_steps\": 2500,\n            \"difficulty\": \"hard\",\n            \"required_items\": [\"iron_sword\", \"shield\"]\n        },\n        \"hunt_pig\": {\n            \"type\": \"combat\",\n            \"description\": \"Hunt a pig for food\",\n            \"success_criteria\": {\"porkchop\": 1},\n            \"max_steps\": 1000,\n            \"difficulty\": \"easy\",\n            \"required_items\": [\"wooden_sword\"]\n        }\n    }\n    \n    # Creative tasks (procedurally generated or manually specified)\n    CREATIVE_TASKS = {\n        \"build_house\": {\n            \"type\": \"creative\",\n            \"description\": \"Build a simple house with walls, roof, and door\",\n            \"success_criteria\": {\"structure_complexity\": 50},\n            \"max_steps\": 5000,\n            \"difficulty\": \"medium\"\n        },\n        \"build_castle\": {\n            \"type\": \"creative\",\n            \"description\": \"Build a castle with towers and walls\",\n            \"success_criteria\": {\"structure_complexity\": 200},\n            \"max_steps\": 10000,\n            \"difficulty\": \"hard\"\n        },\n        \"build_bridge\": {\n            \"type\": \"creative\",\n            \"description\": \"Build a bridge across water or ravine\",\n            \"success_criteria\": {\"bridge_length\": 20},\n            \"max_steps\": 3000,\n            \"difficulty\": \"medium\"\n        },\n        \"create_art\": {\n            \"type\": \"creative\",\n            \"description\": \"Create pixel art using colored blocks\",\n            \"success_criteria\": {\"art_complexity\": 30},\n            \"max_steps\": 2000,\n            \"difficulty\": \"easy\"\n        },\n        \"build_farm\": {\n            \"type\": \"creative\",\n            \"description\": \"Build a functioning farm with crops\",\n            \"success_criteria\": {\"farm_size\": 9},  # 3x3 minimum\n            \"max_steps\": 4000,\n            \"difficulty\": \"medium\"\n        }\n    }\n    \n    # Playthrough task (ultimate challenge)\n    PLAYTHROUGH_TASK = {\n        \"defeat_ender_dragon\": {\n            \"type\": \"playthrough\",\n            \"description\": \"Defeat the Ender Dragon and obtain the dragon egg\",\n            \"success_criteria\": {\"dragon_egg\": 1},\n            \"max_steps\": 100000,  # Very long task\n            \"difficulty\": \"extreme\"\n        }\n    }\n    \n    @classmethod\n    def get_all_tasks(cls) -> Dict[str, Dict]:\n        \"\"\"Get all tasks combined\"\"\"\n        all_tasks = {}\n        all_tasks.update(cls.PROGRAMMATIC_TASKS)\n        all_tasks.update(cls.CREATIVE_TASKS)\n        all_tasks.update(cls.PLAYTHROUGH_TASK)\n        return all_tasks\n    \n    @classmethod\n    def get_tasks_by_type(cls, task_type: str) -> Dict[str, Dict]:\n        \"\"\"Get tasks filtered by type\"\"\"\n        all_tasks = cls.get_all_tasks()\n        return {k: v for k, v in all_tasks.items() if v[\"type\"] == task_type}\n    \n    @classmethod\n    def get_tasks_by_difficulty(cls, difficulty: str) -> Dict[str, Dict]:\n        \"\"\"Get tasks filtered by difficulty\"\"\"\n        all_tasks = cls.get_all_tasks()\n        return {k: v for k, v in all_tasks.items() if v[\"difficulty\"] == difficulty}\n    \n    @classmethod\n    def get_task_info(cls, task_id: str) -> Optional[Dict]:\n        \"\"\"Get information for a specific task\"\"\"\n        all_tasks = cls.get_all_tasks()\n        return all_tasks.get(task_id)\n    \n    @classmethod\n    def list_task_ids(cls) -> List[str]:\n        \"\"\"List all available task IDs\"\"\"\n        return list(cls.get_all_tasks().keys())\n    \n    @classmethod\n    def save_task_registry(cls, filepath: str):\n        \"\"\"Save task registry to JSON file\"\"\"\n        all_tasks = cls.get_all_tasks()\n        with open(filepath, 'w') as f:\n            json.dump(all_tasks, f, indent=2)\n        print(f\"Task registry saved to {filepath}\")\n    \n    @classmethod\n    def create_task_mapping(cls) -> Dict[str, str]:\n        \"\"\"Create mapping from MineDojo task IDs to goal descriptions\"\"\"\n        all_tasks = cls.get_all_tasks()\n        return {task_id: info[\"description\"] for task_id, info in all_tasks.items()}\n\n\nclass MinedojoTaskAdapter:\n    \"\"\"Adapter to integrate MineDojo tasks with the current evaluation system\"\"\"\n    \n    def __init__(self):\n        self.task_registry = TaskRegistry()\n        self.current_task = None\n        self.task_progress = {}\n    \n    def start_task(self, task_id: str) -> Dict:\n        \"\"\"Start a new task and return its configuration\"\"\"\n        task_info = self.task_registry.get_task_info(task_id)\n        if not task_info:\n            raise ValueError(f\"Unknown task: {task_id}\")\n        \n        self.current_task = task_id\n        self.task_progress = {\n            \"start_time\": 0,\n            \"steps_taken\": 0,\n            \"items_obtained\": {},\n            \"goals_completed\": [],\n            \"success\": False\n        }\n        \n        return task_info\n    \n    def check_task_completion(self, inventory: Dict[str, int], info: Dict) -> bool:\n        \"\"\"Check if current task is completed based on success criteria\"\"\"\n        if not self.current_task:\n            return False\n        \n        task_info = self.task_registry.get_task_info(self.current_task)\n        if not task_info:\n            return False\n        \n        success_criteria = task_info.get(\"success_criteria\", {})\n        \n        # Check inventory-based criteria\n        for item, required_count in success_criteria.items():\n            if item in [\"days_survived\", \"structure_complexity\", \"bridge_length\", \"art_complexity\", \"farm_size\"]:\n                # These require special handling from environment info\n                if info.get(item, 0) < required_count:\n                    return False\n            elif item.endswith(\"_defeated\"):\n                # Combat criteria\n                if info.get(\"combat_stats\", {}).get(item, 0) < required_count:\n                    return False\n            else:\n                # Standard inventory check\n                if inventory.get(item, 0) < required_count:\n                    return False\n        \n        return True\n    \n    def get_task_reward(self, inventory: Dict[str, int], info: Dict, step: int) -> float:\n        \"\"\"Calculate reward for current task progress\"\"\"\n        if not self.current_task:\n            return 0.0\n        \n        task_info = self.task_registry.get_task_info(self.current_task)\n        if not task_info:\n            return 0.0\n        \n        # Base reward calculation\n        base_reward = 0.0\n        success_criteria = task_info.get(\"success_criteria\", {})\n        \n        # Progress-based reward\n        for item, required_count in success_criteria.items():\n            if item in inventory:\n                progress = min(inventory[item] / required_count, 1.0)\n                base_reward += progress * 10.0  # 10 points per criterion\n        \n        # Completion bonus\n        if self.check_task_completion(inventory, info):\n            difficulty_multiplier = {\n                \"easy\": 1.0,\n                \"medium\": 1.5,\n                \"hard\": 2.0,\n                \"very_hard\": 3.0,\n                \"extreme\": 5.0\n            }.get(task_info.get(\"difficulty\", \"medium\"), 1.0)\n            \n            base_reward += 100.0 * difficulty_multiplier\n        \n        # Efficiency bonus (fewer steps = higher reward)\n        max_steps = task_info.get(\"max_steps\", 1000)\n        efficiency = max(0, (max_steps - step) / max_steps)\n        base_reward += efficiency * 20.0\n        \n        return base_reward\n    \n    def get_task_guidance(self, task_id: str) -> List[str]:\n        \"\"\"Get step-by-step guidance for a task\"\"\"\n        guidance_map = {\n            \"obtain_wooden_slab\": [\n                \"1. Find trees and mine wood\",\n                \"2. Craft wooden planks from wood\", \n                \"3. Craft wooden slab from planks\"\n            ],\n            \"obtain_stone_stairs\": [\n                \"1. Find stone or mine cobblestone\",\n                \"2. Craft stone stairs from cobblestone\"\n            ],\n            \"obtain_painting\": [\n                \"1. Find trees and mine wood\",\n                \"2. Craft wooden planks and then sticks\",\n                \"3. Find sheep and shear wool\",\n                \"4. Craft painting from sticks and wool\"\n            ],\n            \"mine_cobblestone\": [\n                \"1. Craft or find a wooden pickaxe\",\n                \"2. Find stone blocks underground\",\n                \"3. Mine stone to get cobblestone\"\n            ],\n            \"craft_wooden_pickaxe\": [\n                \"1. Find trees and mine wood\",\n                \"2. Craft wooden planks from wood\",\n                \"3. Craft sticks from planks\",\n                \"4. Craft pickaxe from planks and sticks\"\n            ]\n        }\n        \n        return guidance_map.get(task_id, [\"Complete the task objective\"])\n\n\n# Initialize the task adapter for use in main evaluation\ndef create_task_adapter() -> MinedojoTaskAdapter:\n    \"\"\"Create and return a configured task adapter\"\"\"\n    return MinedojoTaskAdapter()\n\n\n# Export task information for external use\ndef export_task_info(output_dir: str = \"./data\"):\n    \"\"\"Export task information to JSON files\"\"\"\n    output_path = Path(output_dir)\n    output_path.mkdir(exist_ok=True)\n    \n    # Save complete registry\n    TaskRegistry.save_task_registry(str(output_path / \"task_registry.json\"))\n    \n    # Save task mapping\n    task_mapping = TaskRegistry.create_task_mapping()\n    with open(output_path / \"task_mapping.json\", 'w') as f:\n        json.dump(task_mapping, f, indent=2)\n    \n    # Save task lists by category\n    categories = [\"survival\", \"harvest\", \"mining\", \"tech_tree\", \"combat\", \"creative\", \"playthrough\"]\n    for category in categories:\n        tasks = TaskRegistry.get_tasks_by_type(category)\n        with open(output_path / f\"tasks_{category}.json\", 'w') as f:\n            json.dump(tasks, f, indent=2)\n    \n    print(f\"Task information exported to {output_path}\")\n\n\nif __name__ == \"__main__\":\n    # Export task information when run directly\n    export_task_info()\n"},{"path":"diffu_moe_vlm/models.py","text":"\"\"\"\nSimple model implementations for MC-Planner migration\n\"\"\"\n\nimport hashlib\nimport numpy as np\nfrom typing import Dict, List, Any, Optional, Tuple\n\n\nclass SimpleNetwork:\n    \"\"\"\n    Simple network implementation without heavy dependencies\n    \"\"\"\n    \n    def __init__(self, input_dim: int = 256, hidden_dim: int = 128, output_dim: int = 64):\n        self.input_dim = input_dim\n        self.hidden_dim = hidden_dim\n        self.output_dim = output_dim\n        \n        # Initialize simple weights (normally distributed)\n        self.weights_1 = np.random.normal(0, 0.1, (input_dim, hidden_dim))\n        self.bias_1 = np.zeros(hidden_dim)\n        self.weights_2 = np.random.normal(0, 0.1, (hidden_dim, output_dim))\n        self.bias_2 = np.zeros(output_dim)\n        \n    def forward(self, x: np.ndarray) -> np.ndarray:\n        \"\"\"Forward pass through network\"\"\"\n        # First layer\n        hidden = np.dot(x, self.weights_1) + self.bias_1\n        hidden = np.maximum(0, hidden)  # ReLU activation\n        \n        # Second layer\n        output = np.dot(hidden, self.weights_2) + self.bias_2\n        \n        return output\n    \n    def predict(self, x: np.ndarray) -> np.ndarray:\n        \"\"\"Make prediction\"\"\"\n        return self.forward(x)\n\n\nclass GoalEmbedding:\n    \"\"\"\n    Simple goal embedding without heavy ML dependencies\n    \"\"\"\n    \n    def __init__(self, embedding_dim: int = 512):\n        self.embedding_dim = embedding_dim\n        self.goal_embeddings = {}\n        \n    def encode_goal(self, goal: str) -> np.ndarray:\n        \"\"\"Encode goal as embedding vector\"\"\"\n        if goal in self.goal_embeddings:\n            return self.goal_embeddings[goal]\n        \n        # Simple hash-based embedding\n        embedding = self._hash_to_embedding(goal)\n        self.goal_embeddings[goal] = embedding\n        \n        return embedding\n    \n    def _hash_to_embedding(self, text: str) -> np.ndarray:\n        \"\"\"Convert text to embedding using simple hashing\"\"\"\n        # Use a stable hash (built-in hash() is salted per process) to generate a consistent embedding\n        seed = int.from_bytes(hashlib.sha256(text.encode(\"utf-8\")).digest()[:8], \"little\")\n        \n        # Convert to vector using a local RNG so the global numpy RNG state is untouched\n        rng = np.random.default_rng(seed)\n        embedding = rng.normal(0, 1, self.embedding_dim)\n        \n        # Normalize\n        norm = np.linalg.norm(embedding)\n        if norm > 0:\n            embedding = embedding / norm\n        \n        return embedding\n    \n    def similarity(self, goal1: str, goal2: str) -> float:\n        \"\"\"Calculate similarity between two goals\"\"\"\n        emb1 = self.encode_goal(goal1)\n        emb2 = self.encode_goal(goal2)\n        \n        # Cosine similarity\n        return np.dot(emb1, emb2)\n\n\nclass SimpleController:\n    \"\"\"\n    Simple controller for action selection\n    \"\"\"\n    \n    def __init__(self):\n        self.action_history = []\n        self.goal_progress = {}\n        \n    def select_action(self, observation: Dict[str, Any], goal: str) -> Dict[str, Any]:\n        \"\"\"Select action based on observation and goal\"\"\"\n        # Simple rule-based action selection\n        \n        if \"mine\" in goal.lower():\n            return self._mining_action()\n        elif \"craft\" in goal.lower() or \"obtain\" in goal.lower():\n            return self._crafting_action()\n        else:\n            return self._exploration_action()\n    \n    def _mining_action(self) -> Dict[str, Any]:\n        \"\"\"Generate mining action\"\"\"\n        return {\n            'movement': 0,\n            'camera': np.array([0.0, 0.0]),\n            'use': 0,\n            'attack': 1,  # mine\n            'jump': 0\n        }\n    \n    def _crafting_action(self) -> Dict[str, Any]:\n        \"\"\"Generate crafting action\"\"\"\n        return {\n            'movement': 0,\n            'camera': np.array([0.0, 0.0]),\n            'use': 1,  # use/craft\n            'attack': 0,\n            'jump': 0\n        }\n    \n    def _exploration_action(self) -> Dict[str, Any]:\n        \"\"\"Generate exploration action\"\"\"\n        # Random movement for exploration\n        movement = np.random.choice([0, 1, 2, 3])  # forward, back, left, right\n        camera = np.random.normal(0, 0.1, 2)\n        camera = np.clip(camera, -0.5, 0.5)\n        \n        return {\n            'movement': movement,\n            'camera': camera,\n            'use': 0,\n            'attack': 0,\n            'jump': 0\n        }\n    \n    def update_progress(self, goal: str, success: bool):\n        \"\"\"Update goal progress\"\"\"\n        if goal not in self.goal_progress:\n            self.goal_progress[goal] = {'attempts': 0, 'successes': 0}\n        \n        self.goal_progress[goal]['attempts'] += 1\n        if success:\n            self.goal_progress[goal]['successes'] += 1\n    \n    def get_success_rate(self, goal: str) -> float:\n        \"\"\"Get success rate for goal\"\"\"\n        if goal not in self.goal_progress:\n            return 0.0\n        \n        progress = self.goal_progress[goal]\n        if progress['attempts'] == 0:\n            return 0.0\n        \n        return progress['successes'] / progress['attempts']\n\n\nclass ImageProcessor:\n    \"\"\"\n    Simple image processing without heavy dependencies\n    \"\"\"\n    \n    def __init__(self, target_size: Tuple[int, int] = (128, 128)):\n        self.target_size = target_size\n    \n    def process_observation(self, obs: Dict[str, Any]) -> np.ndarray:\n        \"\"\"Process observation image\"\"\"\n        if 'rgb' not in obs:\n            return np.zeros((*self.target_size, 3), dtype=np.uint8)\n        \n        image = obs['rgb']\n        \n        # Resize image if needed\n        if image.shape[:2] != self.target_size:\n            import cv2\n            image = cv2.resize(image, self.target_size, interpolation=cv2.INTER_LINEAR)\n        \n        return image\n    \n    def extract_features(self, image: np.ndarray) -> np.ndarray:\n        \"\"\"Extract simple features from image\"\"\"\n        # Simple color histogram features\n        features = []\n        \n        # Color channel means\n        for channel in range(3):\n            features.append(np.mean(image[:, :, channel]))\n            features.append(np.std(image[:, :, channel]))\n        \n        # Simple edge detection (gradient magnitude)\n        gray = np.mean(image, axis=2)\n        grad_x = np.gradient(gray, axis=1)\n        grad_y = np.gradient(gray, axis=0)\n        edge_magnitude = np.sqrt(grad_x**2 + grad_y**2)\n        features.append(np.mean(edge_magnitude))\n        features.append(np.std(edge_magnitude))\n        \n        return np.array(features)\n\n\ndef create_backbone(backbone_name: str = \"simple\") -> SimpleNetwork:\n    \"\"\"Create model backbone\"\"\"\n    if backbone_name == \"simple\":\n        return SimpleNetwork()\n    else:\n        raise ValueError(f\"Unknown backbone: {backbone_name}\")\n\n\ndef resize_image(image: np.ndarray, target_resolution: Tuple[int, int]) -> np.ndarray:\n    \"\"\"Resize image to target resolution\"\"\"\n    import cv2\n    return cv2.resize(image, target_resolution, interpolation=cv2.INTER_LINEAR)\n"},{"path":"diffu_moe_vlm/nn/__init__.py","text":"\"\"\"Neural network modules (requires torch: pip install -e \".[ml]\")\"\"\"\n"},{"path":"diffu_moe_vlm/nn/diffusion.py","text":"\"\"\"\nDiffusion policy over discrete action sequences (DDPM).\n\nAn action chunk of horizon H is represented as one-hot vectors scaled to\n[-1, 1], shape (H, A). A conditional denoiser sees the noisy chunk, the\ndiffusion step and the observation embedding and predicts either the clean\nchunk (`prediction_type=\"sample\"`, default: much more reliable for one-hot\ntargets, where epsilon-prediction barely constrains x0 at high noise levels)\nor the noise (`\"epsilon\"`). Sampling runs the reverse process (optionally\nstrided, DDIM-style) and decodes with argmax.\n\"\"\"\n\nimport math\nfrom typing import Optional\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nfrom .encoders import build_encoder\nfrom .time_embedding import SinusoidalTimeEmbedding\n\n\ndef cosine_beta_schedule(num_steps: int, s: float = 0.008) -> torch.Tensor:\n    t = torch.linspace(0, num_steps, num_steps + 1) / num_steps\n    alphas_bar = torch.cos((t + s) / (1 + s) * math.pi / 2) ** 2\n    alphas_bar = alphas_bar / alphas_bar[0]\n    betas = 1 - alphas_bar[1:] / alphas_bar[:-1]\n    return betas.clamp(1e-5, 0.999)\n\n\nclass FiLMResBlock(nn.Module):\n    def __init__(self, dim: int, cond_dim: int):\n        super().__init__()\n        self.norm = nn.LayerNorm(dim)\n        self.film = nn.Linear(cond_dim, dim * 2)\n        self.mlp = nn.Sequential(nn.Linear(dim, dim * 2), nn.SiLU(), nn.Linear(dim * 2, dim))\n\n    def forward(self, x, cond):\n        scale, shift = self.film(cond).chunk(2, dim=-1)\n        return x + self.mlp(self.norm(x) * (1 + scale) + shift)\n\n\nclass Denoiser(nn.Module):\n    def __init__(self, horizon: int, num_actions: int, cond_dim: int, hidden_dim: int = 512, depth: int = 4):\n        super().__init__()\n        self.in_proj = nn.Linear(horizon * num_actions, hidden_dim)\n        self.time = nn.Sequential(SinusoidalTimeEmbedding(128), nn.Linear(128, cond_dim), nn.SiLU())\n        self.blocks = nn.ModuleList([FiLMResBlock(hidden_dim, cond_dim) for _ in range(depth)])\n        self.out = nn.Sequential(nn.LayerNorm(hidden_dim), nn.Linear(hidden_dim, horizon * num_actions))\n\n    def forward(self, x_t, t, obs_emb):\n        cond = obs_emb + self.time(t)\n        h = self.in_proj(x_t.flatten(1))\n        for block in self.blocks:\n            h = block(h, cond)\n        return self.out(h).view_as(x_t)\n\n\nclass DiffusionPolicy(nn.Module):\n    \"\"\"Observation-conditioned DDPM over (H, A) one-hot action chunks\"\"\"\n\n    def __init__(self, num_actions: int, encoder: nn.Module, horizon: int = 8, num_diffusion_steps: int = 50,\n                 hidden_dim: int = 512, depth: int = 4, prediction_type: str = \"sample\"):\n        super().__init__()\n        if prediction_type not in (\"sample\", \"epsilon\"):\n            raise ValueError(f\"prediction_type must be 'sample' or 'epsilon', got {prediction_type!r}\")\n        self.prediction_type = prediction_type\n        self.num_actions = num_actions\n        self.horizon = horizon\n        self.num_diffusion_steps = num_diffusion_steps\n        self.encoder = encoder\n        self.denoiser = Denoiser(horizon, num_actions, encoder.feature_dim, hidden_dim, depth)\n        betas = cosine_beta_schedule(num_diffusion_steps)\n        alphas_bar = torch.cumprod(1 - betas, dim=0)\n        self.register_buffer(\"betas\", betas)\n        self.register_buffer(\"alphas_bar\", alphas_bar)\n\n    def encode_actions(self, actions: torch.Tensor) -> torch.Tensor:\n        return F.one_hot(actions, self.num_actions).float() * 2 - 1\n\n    def loss(self, obs: torch.Tensor, actions: torch.Tensor) -> torch.Tensor:\n        \"\"\"obs: (B, H, W, 3) uint8; actions: (B, horizon) long\"\"\"\n        x0 = self.encode_actions(actions)\n        t = torch.randint(0, self.num_diffusion_steps, (x0.shape[0],), device=x0.device)\n        noise = torch.randn_like(x0)\n        ab = self.alphas_bar[t].view(-1, 1, 1)\n        x_t = ab.sqrt() * x0 + (1 - ab).sqrt() * noise\n        pred = self.denoiser(x_t, t.float(), self.encoder(obs))\n        return F.mse_loss(pred, x0 if self.prediction_type == \"sample\" else noise)\n\n    def _predict(self, x, t: int, obs_emb):\n        \"\"\"Return (x0_hat clamped to [-1, 1], eps_hat) at integer step t\"\"\"\n        tt = torch.full((x.shape[0],), float(t), device=x.device)\n        out = self.denoiser(x, tt, obs_emb)\n        ab = self.alphas_bar[t]\n        if self.prediction_type == \"sample\":\n            x0 = out.clamp(-1, 1)\n            eps = (x - ab.sqrt() * x0) / (1 - ab).sqrt()\n        else:\n            eps = out\n            x0 = ((x - (1 - ab).sqrt() * eps) / ab.sqrt()).clamp(-1, 1)\n        return x0, eps\n\n    @torch.no_grad()\n    def sample(self, obs: torch.Tensor, num_steps: Optional[int] = None,\n               generator: Optional[torch.Generator] = None) -> torch.Tensor:\n        \"\"\"Return (B, horizon) actions. `num_steps` < T uses a strided deterministic (DDIM) schedule.\"\"\"\n        obs_emb = self.encoder(obs)\n        shape = (obs.shape[0], self.horizon, self.num_actions)\n        x = torch.randn(shape, device=obs.device, generator=generator)\n        T = self.num_diffusion_steps\n        if num_steps is None or num_steps >= T:\n            for t in reversed(range(T)):\n                x0, _ = self._predict(x, t, obs_emb)\n                if t == 0:\n                    x = x0\n                    break\n                # Posterior q(x_{t-1} | x_t, x0)\n                ab, ab_prev, beta = self.alphas_bar[t], self.alphas_bar[t - 1], self.betas[t]\n                mean = (ab_prev.sqrt() * beta / (1 - ab)) * x0 + ((1 - beta).sqrt() * (1 - ab_prev) / (1 - ab)) * x\n                var = beta * (1 - ab_prev) / (1 - ab)\n                x = mean + var.sqrt() * torch.randn(shape, device=obs.device, generator=generator)\n        else:\n            steps = torch.linspace(T - 1, 0, num_steps).round().long().tolist()\n            for i, t in enumerate(steps):\n                x0, eps = self._predict(x, t, obs_emb)\n                if i + 1 == len(steps):\n                    x = x0\n                    break\n                ab_prev = self.alphas_bar[steps[i + 1]]\n                x = ab_prev.sqrt() * x0 + (1 - ab_prev).sqrt() * eps\n        return x.argmax(dim=-1)\n\n\ndef build_diffusion_policy(model_cfg, num_actions: int, image_size: int = 64) -> DiffusionPolicy:\n    enc_cfg = dict(model_cfg.get(\"encoder\", {}))\n    encoder = build_encoder(enc_cfg.pop(\"name\", \"cnn\"), image_size=image_size, **enc_cfg)\n    return DiffusionPolicy(\n        num_actions, encoder,\n        horizon=model_cfg.get(\"horizon\", 8),\n        num_diffusion_steps=model_cfg.get(\"num_diffusion_steps\", 50),\n        hidden_dim=model_cfg.get(\"hidden_dim\", 512),\n        depth=model_cfg.get(\"depth\", 4),\n        prediction_type=model_cfg.get(\"prediction_type\", \"sample\"),\n    )\n"},{"path":"diffu_moe_vlm/nn/encoders.py","text":"\"\"\"\nVisual encoders for pixel observations.\n\nAll encoders take uint8 images of shape (B, H, W, 3) and return (B, feature_dim).\n`cnn` and `vit` are small models trained from scratch (CPU friendly);\n`pretrained` wraps a HuggingFace CLIP/SigLIP vision tower.\n\"\"\"\n\nfrom typing import Optional\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\ndef _to_float(images: torch.Tensor) -> torch.Tensor:\n    \"\"\"(B, H, W, 3) uint8 -> (B, 3, H, W) float in [0, 1]\"\"\"\n    return images.permute(0, 3, 1, 2).float() / 255.0\n\n\nclass CNNEncoder(nn.Module):\n    \"\"\"Small convolutional encoder (Nature-DQN style) for 64x64 inputs\"\"\"\n\n    def __init__(self, image_size: int = 64, feature_dim: int = 256, channels=(32, 64, 64)):\n        super().__init__()\n        c1, c2, c3 = channels\n        self.conv = nn.Sequential(\n            nn.Conv2d(3, c1, 4, stride=2, padding=1), nn.ReLU(),\n            nn.Conv2d(c1, c2, 4, stride=2, padding=1), nn.ReLU(),\n            nn.Conv2d(c2, c3, 3, stride=2, padding=1), nn.ReLU(),\n            nn.Flatten(),\n        )\n        with torch.no_grad():\n            flat = self.conv(torch.zeros(1, 3, image_size, image_size)).shape[1]\n        self.proj = nn.Sequential(nn.Linear(flat, feature_dim), nn.ReLU())\n        self.feature_dim = feature_dim\n\n    def forward(self, images: torch.Tensor) -> torch.Tensor:\n        return self.proj(self.conv(_to_float(images)))\n\n\nclass ViTEncoder(nn.Module):\n    \"\"\"Tiny Vision Transformer: patch embedding + transformer encoder + CLS pooling\"\"\"\n\n    def __init__(self, image_size: int = 64, patch_size: int = 8, dim: int = 128, depth: int = 2,\n                 heads: int = 4, feature_dim: int = 256):\n        super().__init__()\n        assert image_size % patch_size == 0, \"image_size must be divisible by patch_size\"\n        num_patches = (image_size // patch_size) ** 2\n        self.patch = nn.Conv2d(3, dim, patch_size, stride=patch_size)\n        self.cls = nn.Parameter(torch.zeros(1, 1, dim))\n        self.pos = nn.Parameter(torch.randn(1, num_patches + 1, dim) * 0.02)\n        layer = nn.TransformerEncoderLayer(dim, heads, dim * 4, dropout=0.0, batch_first=True, norm_first=True)\n        self.transformer = nn.TransformerEncoder(layer, depth, enable_nested_tensor=False)\n        self.norm = nn.LayerNorm(dim)\n        self.proj = nn.Sequential(nn.Linear(dim, feature_dim), nn.ReLU())\n        self.feature_dim = feature_dim\n\n    def forward(self, images: torch.Tensor) -> torch.Tensor:\n        x = self.patch(_to_float(images)).flatten(2).transpose(1, 2)  # (B, N, dim)\n        x = torch.cat([self.cls.expand(x.shape[0], -1, -1), x], dim=1) + self.pos\n        x = self.norm(self.transformer(x))\n        return self.proj(x[:, 0])\n\n\nclass PretrainedVisionEncoder(nn.Module):\n    \"\"\"\n    HuggingFace vision tower (e.g. \"openai/clip-vit-base-patch32\",\n    \"google/siglip-base-patch16-224\"). Images are resized to the model input\n    size and normalized with the model's statistics. Requires `transformers`.\n    \"\"\"\n\n    CLIP_MEAN = (0.48145466, 0.4578275, 0.40821073)\n    CLIP_STD = (0.26862954, 0.26130258, 0.27577711)\n\n    def __init__(self, model_name: str = \"openai/clip-vit-base-patch32\", feature_dim: int = 256,\n                 freeze: bool = True, config=None):\n        super().__init__()\n        from transformers import AutoConfig, AutoModel\n\n        if config is None:\n            model = AutoModel.from_pretrained(model_name)\n        else:  # build from a config without downloading weights (tests, custom sizes)\n            model = AutoModel.from_config(config if not isinstance(config, str) else AutoConfig.from_pretrained(config))\n        self.vision = getattr(model, \"vision_model\", model)\n        vision_cfg = getattr(self.vision, \"config\", None) or model.config\n        self.input_size = vision_cfg.image_size\n        hidden = vision_cfg.hidden_size\n        mean, std = self.CLIP_MEAN, self.CLIP_STD\n        if \"siglip\" in type(self.vision).__name__.lower():\n            mean, std = (0.5, 0.5, 0.5), (0.5, 0.5, 0.5)\n        self.register_buffer(\"mean\", torch.tensor(mean).view(1, 3, 1, 1), persistent=False)\n        self.register_buffer(\"std\", torch.tensor(std).view(1, 3, 1, 1), persistent=False)\n        if freeze:\n            for p in self.vision.parameters():\n                p.requires_grad_(False)\n        self.freeze = freeze\n        self.proj = nn.Sequential(nn.Linear(hidden, feature_dim), nn.ReLU())\n        self.feature_dim = feature_dim\n\n    def forward(self, images: torch.Tensor) -> torch.Tensor:\n        x = _to_float(images)\n        x = F.interpolate(x, size=(self.input_size, self.input_size), mode=\"bilinear\", align_corners=False)\n        x = (x - self.mean) / self.std\n        with torch.set_grad_enabled(not self.freeze and torch.is_grad_enabled()):\n            out = self.vision(pixel_values=x)\n        pooled = out.pooler_output if getattr(out, \"pooler_output\", None) is not None \\\n            else out.last_hidden_state.mean(dim=1)\n        return self.proj(pooled)\n\n\ndef build_encoder(name: str = \"cnn\", image_size: int = 64, feature_dim: int = 256,\n                  pretrained_model: Optional[str] = None, freeze: bool = True, **kwargs) -> nn.Module:\n    \"\"\"Encoder factory used by configs: name in {cnn, vit, pretrained}\"\"\"\n    if name == \"cnn\":\n        return CNNEncoder(image_size=image_size, feature_dim=feature_dim)\n    if name == \"vit\":\n        return ViTEncoder(image_size=image_size, feature_dim=feature_dim, **kwargs)\n    if name == \"pretrained\":\n        return PretrainedVisionEncoder(pretrained_model or \"openai/clip-vit-base-patch32\",\n                                       feature_dim=feature_dim, freeze=freeze)\n    raise ValueError(f\"Unknown encoder {name!r} (expected cnn, vit or pretrained)\")\n"},{"path":"diffu_moe_vlm/nn/moe.py","text":"\"\"\"\nMixture-of-Experts layers with top-k gating and a load-balancing loss.\n\nExperts are evaluated densely and combined with the sparse top-k gate weights,\nwhich is simple and efficient for the small expert counts used here.\n\"\"\"\n\nfrom typing import Tuple\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\nclass MoELayer(nn.Module):\n    \"\"\"Top-k gated mixture of MLP experts on (B, D) inputs\"\"\"\n\n    def __init__(self, dim: int, hidden_dim: int, num_experts: int = 4, top_k: int = 2, noisy_gating: bool = True):\n        super().__init__()\n        assert 1 <= top_k <= num_experts\n        self.num_experts = num_experts\n        self.top_k = top_k\n        self.noisy_gating = noisy_gating\n        self.gate = nn.Linear(dim, num_experts, bias=False)\n        self.noise = nn.Linear(dim, num_experts, bias=False)\n        self.experts = nn.ModuleList([\n            nn.Sequential(nn.Linear(dim, hidden_dim), nn.GELU(), nn.Linear(hidden_dim, dim))\n            for _ in range(num_experts)\n        ])\n        nn.init.normal_(self.gate.weight, std=0.02)\n        nn.init.zeros_(self.noise.weight)\n        self.register_buffer(\"last_load\", torch.zeros(num_experts), persistent=False)\n\n    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:\n        logits = self.gate(x)\n        if self.noisy_gating and self.training:\n            logits = logits + torch.randn_like(logits) * F.softplus(self.noise(x))\n        probs = logits.softmax(dim=-1)                                  # (B, E)\n        top_vals, top_idx = probs.topk(self.top_k, dim=-1)              # (B, k)\n        weights = top_vals / top_vals.sum(dim=-1, keepdim=True)\n\n        expert_out = torch.stack([expert(x) for expert in self.experts], dim=1)  # (B, E, D)\n        chosen = expert_out.gather(1, top_idx.unsqueeze(-1).expand(-1, -1, x.shape[-1]))\n        y = (weights.unsqueeze(-1) * chosen).sum(dim=1)\n\n        # Switch-Transformer load-balancing loss: E * sum_i f_i * P_i (1.0 when perfectly balanced)\n        dispatch = F.one_hot(top_idx[:, 0], self.num_experts).float()\n        load = dispatch.mean(dim=0)\n        importance = probs.mean(dim=0)\n        aux_loss = self.num_experts * (load * importance).sum()\n        self.last_load = load.detach()\n        return y, aux_loss\n\n\nclass MoEBlock(nn.Module):\n    \"\"\"Pre-norm residual block around an MoE layer\"\"\"\n\n    def __init__(self, dim: int, hidden_dim: int, num_experts: int = 4, top_k: int = 2):\n        super().__init__()\n        self.norm = nn.LayerNorm(dim)\n        self.moe = MoELayer(dim, hidden_dim, num_experts, top_k)\n\n    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:\n        y, aux = self.moe(self.norm(x))\n        return x + y, aux\n\n\nclass MLPBlock(nn.Module):\n    \"\"\"Dense counterpart of MoEBlock (for ablations); aux loss is zero\"\"\"\n\n    def __init__(self, dim: int, hidden_dim: int, **_):\n        super().__init__()\n        self.norm = nn.LayerNorm(dim)\n        self.mlp = nn.Sequential(nn.Linear(dim, hidden_dim), nn.GELU(), nn.Linear(hidden_dim, dim))\n\n    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:\n        return x + self.mlp(self.norm(x)), x.new_zeros(())\n\n\nclass Trunk(nn.Module):\n    \"\"\"Stack of MoE (or dense) residual blocks returning features and summed aux loss\"\"\"\n\n    def __init__(self, dim: int, hidden_dim: int, num_layers: int = 2, kind: str = \"moe\",\n                 num_experts: int = 4, top_k: int = 2):\n        super().__init__()\n        if kind not in (\"moe\", \"mlp\"):\n            raise ValueError(f\"Unknown trunk {kind!r} (expected moe or mlp)\")\n        block = MoEBlock if kind == \"moe\" else MLPBlock\n        self.blocks = nn.ModuleList([\n            block(dim, hidden_dim, num_experts=num_experts, top_k=top_k) for _ in range(num_layers)\n        ])\n        self.norm = nn.LayerNorm(dim)\n\n    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:\n        aux = x.new_zeros(())\n        for block in self.blocks:\n            x, block_aux = block(x)\n            aux = aux + block_aux\n        return self.norm(x), aux\n\n    def expert_load(self):\n        return [b.moe.last_load.tolist() for b in self.blocks if isinstance(b, MoEBlock)]\n"},{"path":"diffu_moe_vlm/nn/policy.py","text":"\"\"\"\nActor-critic policy: visual encoder -> (optional trajectory features) -> MoE trunk -> heads.\n\"\"\"\n\nfrom typing import Any, Dict, Optional, Tuple\n\nimport torch\nimport torch.nn as nn\nfrom torch.distributions import Categorical\n\nfrom .encoders import build_encoder\nfrom .moe import Trunk\nfrom .time_embedding import TrajectoryEncoder\n\n\ndef _ortho_init(module: nn.Module, gain: float):\n    if isinstance(module, nn.Linear):\n        nn.init.orthogonal_(module.weight, gain)\n        nn.init.zeros_(module.bias)\n\n\nclass ActorCritic(nn.Module):\n    \"\"\"PPO actor-critic with an MoE trunk shared by the policy and value heads\"\"\"\n\n    def __init__(self, num_actions: int, encoder: nn.Module, hidden_dim: int = 512, num_layers: int = 2,\n                 trunk: str = \"moe\", num_experts: int = 4, top_k: int = 2,\n                 trajectory_encoder: Optional[TrajectoryEncoder] = None):\n        super().__init__()\n        self.encoder = encoder\n        self.trajectory_encoder = trajectory_encoder\n        dim = encoder.feature_dim + (trajectory_encoder.out_dim if trajectory_encoder else 0)\n        self.trunk = Trunk(dim, hidden_dim, num_layers=num_layers, kind=trunk,\n                           num_experts=num_experts, top_k=top_k)\n        self.actor = nn.Linear(dim, num_actions)\n        self.critic = nn.Linear(dim, 1)\n        _ortho_init(self.actor, 0.01)\n        _ortho_init(self.critic, 1.0)\n\n    def features(self, obs: torch.Tensor, trajectory: Optional[Dict[str, torch.Tensor]] = None):\n        x = self.encoder(obs)\n        if self.trajectory_encoder is not None:\n            if trajectory is None:\n                raise ValueError(\"this policy expects trajectory inputs (positions, timestamps)\")\n            x = torch.cat([x, self.trajectory_encoder(**trajectory)], dim=-1)\n        return self.trunk(x)\n\n    def forward(self, obs: torch.Tensor, trajectory=None) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:\n        h, aux = self.features(obs, trajectory)\n        return self.actor(h), self.critic(h).squeeze(-1), aux\n\n    @torch.no_grad()\n    def act(self, obs: torch.Tensor, trajectory=None, deterministic: bool = False):\n        logits, value, _ = self(obs, trajectory)\n        dist = Categorical(logits=logits)\n        action = logits.argmax(-1) if deterministic else dist.sample()\n        return action, dist.log_prob(action), value\n\n    def evaluate_actions(self, obs: torch.Tensor, actions: torch.Tensor, trajectory=None):\n        logits, value, aux = self(obs, trajectory)\n        dist = Categorical(logits=logits)\n        return dist.log_prob(actions), dist.entropy(), value, aux\n\n\ndef build_actor_critic(model_cfg: Dict[str, Any], num_actions: int, image_size: int = 64) -> ActorCritic:\n    \"\"\"Build an ActorCritic from a plain config dict (as stored in checkpoints)\"\"\"\n    enc_cfg = dict(model_cfg.get(\"encoder\", {}))\n    encoder = build_encoder(enc_cfg.pop(\"name\", \"cnn\"), image_size=image_size, **enc_cfg)\n    traj_cfg = model_cfg.get(\"trajectory\")\n    trajectory_encoder = TrajectoryEncoder(**traj_cfg) if traj_cfg else None\n    return ActorCritic(\n        num_actions,\n        encoder,\n        hidden_dim=model_cfg.get(\"hidden_dim\", 512),\n        num_layers=model_cfg.get(\"num_layers\", 2),\n        trunk=model_cfg.get(\"trunk\", \"moe\"),\n        num_experts=model_cfg.get(\"num_experts\", 4),\n        top_k=model_cfg.get(\"top_k\", 2),\n        trajectory_encoder=trajectory_encoder,\n    )\n"},{"path":"diffu_moe_vlm/nn/time_embedding.py","text":"\"\"\"\nTime embeddings and the 3D trajectory / IMU encoder.\n\n`SinusoidalTimeEmbedding` embeds continuous times (diffusion steps or\ntimestamps in seconds). `TrajectoryEncoder` encodes irregularly sampled\nmulti-joint 3D trajectories (e.g. left hand, right hand, head from motion\ncapture or IMU-derived poses) into a single feature vector.\n\"\"\"\n\nimport math\nfrom typing import Optional\n\nimport torch\nimport torch.nn as nn\n\n\nclass SinusoidalTimeEmbedding(nn.Module):\n    \"\"\"Transformer-style sinusoidal embedding of continuous scalar times\"\"\"\n\n    def __init__(self, dim: int, max_period: float = 10000.0):\n        super().__init__()\n        assert dim % 2 == 0\n        self.dim = dim\n        self.max_period = max_period\n\n    def forward(self, t: torch.Tensor) -> torch.Tensor:\n        half = self.dim // 2\n        freqs = torch.exp(-math.log(self.max_period) * torch.arange(half, device=t.device, dtype=torch.float32) / half)\n        args = t.float().unsqueeze(-1) * freqs\n        return torch.cat([args.sin(), args.cos()], dim=-1)\n\n\nclass TrajectoryEncoder(nn.Module):\n    \"\"\"\n    Encode (B, T, J, 3) joint positions sampled at (B, T) timestamps.\n\n    Per step, positions and finite-difference velocities are projected and a\n    continuous time embedding of the timestamp (relative to the first sample,\n    scaled by `time_scale`) is added, so irregular sampling rates are handled.\n    A transformer encoder mixes the sequence and a masked mean pool returns\n    (B, out_dim).\n    \"\"\"\n\n    def __init__(self, num_joints: int = 3, dim: int = 128, out_dim: int = 128, depth: int = 2,\n                 heads: int = 4, time_scale: float = 100.0):\n        super().__init__()\n        self.num_joints = num_joints\n        self.time_scale = time_scale\n        self.input_proj = nn.Linear(num_joints * 6, dim)\n        self.time_embed = nn.Sequential(SinusoidalTimeEmbedding(dim), nn.Linear(dim, dim), nn.SiLU(), nn.Linear(dim, dim))\n        layer = nn.TransformerEncoderLayer(dim, heads, dim * 4, dropout=0.0, batch_first=True, norm_first=True)\n        self.transformer = nn.TransformerEncoder(layer, depth, enable_nested_tensor=False)\n        self.norm = nn.LayerNorm(dim)\n        self.out = nn.Linear(dim, out_dim)\n        self.out_dim = out_dim\n\n    def forward(self, positions: torch.Tensor, timestamps: torch.Tensor,\n                mask: Optional[torch.Tensor] = None) -> torch.Tensor:\n        \"\"\"\n        Args:\n            positions: (B, T, J, 3) joint positions\n            timestamps: (B, T) sample times in seconds (increasing)\n            mask: (B, T) bool, True for valid samples (default all valid)\n        \"\"\"\n        b, t, j, _ = positions.shape\n        assert j == self.num_joints, f\"expected {self.num_joints} joints, got {j}\"\n        if mask is None:\n            mask = torch.ones(b, t, dtype=torch.bool, device=positions.device)\n\n        rel_t = timestamps - timestamps[:, :1]\n        dt = torch.diff(rel_t, dim=1, prepend=rel_t[:, :1]).clamp_min(1e-3).unsqueeze(-1).unsqueeze(-1)\n        velocity = torch.diff(positions, dim=1, prepend=positions[:, :1]) / dt\n        features = torch.cat([positions, velocity], dim=-1).reshape(b, t, j * 6)\n\n        x = self.input_proj(features) + self.time_embed(rel_t * self.time_scale)\n        x = self.transformer(x, src_key_padding_mask=~mask)\n        x = self.norm(x)\n        weights = mask.float().unsqueeze(-1)\n        pooled = (x * weights).sum(dim=1) / weights.sum(dim=1).clamp_min(1.0)\n        return self.out(pooled)\n"},{"path":"diffu_moe_vlm/planner.py","text":"\"\"\"\nMC-Planner Planning Module\nMigrated to support local LLM and remove OpenAI dependencies\n\"\"\"\n\nimport os\nimport json\nimport requests\nfrom typing import Dict, List, Any, Optional\n\nfrom .core import DATA_DIR, parse_plan_to_goals, plan_steps\n\n\nclass Planner:\n    \"\"\"\n    Planning module using local LLM instead of OpenAI API\n    \"\"\"\n    \n    def __init__(self,\n                 api_base: Optional[str] = None,\n                 model: Optional[str] = None,\n                 api_key: Optional[str] = None,\n                 enabled: bool = True,\n                 timeout: float = 30.0):\n        self.dialogue = ''\n        self.logging_dialogue = ''\n        self.target: Optional[str] = None\n        \n        # When the LLM is disabled or unreachable, the rule-based fallback planner is used\n        self.llm_enabled = enabled\n        self.llm_available = enabled\n        self.timeout = timeout\n        \n        # Load configuration\n        self.data_dir = DATA_DIR\n        self.goal_lib = self.load_goal_lib()\n        self.supported_objects = self.get_supported_objects(self.goal_lib)\n        \n        # Local LLM configuration (priority: env var > constructor/config > default)\n        # api_base is an OpenAI-compatible base URL that already includes the version, e.g. http://localhost:8000/v1\n        self.llm_api_base = (os.getenv(\"LLM_API_BASE\") or api_base or \"http://localhost:8000/v1\").rstrip(\"/\")\n        self.llm_model = os.getenv(\"LLM_MODEL\") or model or \"meta-llama/Llama-3.2-1B\"\n        self.llm_api_key = os.getenv(\"LLM_API_KEY\") or api_key or \"DUMMY\"\n        \n        # FP8 configuration attributes\n        self.use_fp8 = os.getenv(\"USE_FP8\", \"\").lower() in [\"true\", \"1\"]\n        self.precision = \"fp8\" if self.use_fp8 else \"fp16\"\n        \n        # Initialize FP8 manager if available and enabled\n        self.fp8_manager = None\n        if self.use_fp8:\n            self.init_fp8_manager()\n        \n    def reset(self):\n        \"\"\"Reset planner state\"\"\"\n        self.dialogue = ''\n        self.logging_dialogue = ''\n        self.target = None\n\n    def init_fp8_manager(self):\n        \"\"\"Initialize FP8 manager if available\"\"\"\n        try:\n            from .fp8_utils import create_fp8_manager\n            self.fp8_manager = create_fp8_manager()\n            print(f\"[Planner] FP8 manager initialized for model: {self.llm_model}\")\n        except ImportError:\n            print(\"[Planner] FP8 utilities not available\")\n            self.use_fp8 = False\n            self.precision = \"fp16\"\n        except Exception as e:\n            print(f\"[Planner] Failed to initialize FP8 manager: {e}\")\n            self.use_fp8 = False\n            self.precision = \"fp16\"\n\n    def check_llm_server_status(self) -> bool:\n        \"\"\"Check if LLM server is running\"\"\"\n        try:\n            response = requests.get(\n                f\"{self.llm_api_base}/models\",\n                timeout=10\n            )\n            return response.status_code == 200\n        except:\n            return False\n\n    def load_goal_lib(self) -> Dict:\n        \"\"\"Load goal library\"\"\"\n        goal_lib_file = self.data_dir / \"goal_lib.json\"\n        if goal_lib_file.exists():\n            with open(goal_lib_file, 'r') as f:\n                return json.load(f)\n        else:\n            # Default goal library\n            return {\n                \"obtain_wooden_slab\": {\n                    \"type\": \"craft\",\n                    \"requirements\": [\"wooden_planks\"],\n                    \"description\": \"Craft wooden slab from wooden planks\"\n                },\n                \"obtain_stone_stairs\": {\n                    \"type\": \"craft\", \n                    \"requirements\": [\"cobblestone\"],\n                    \"description\": \"Craft stone stairs from cobblestone\"\n                },\n                \"obtain_painting\": {\n                    \"type\": \"craft\",\n                    \"requirements\": [\"stick\", \"wool\"],\n                    \"description\": \"Craft painting from sticks and wool\"\n                },\n                \"mine_cobblestone\": {\n                    \"type\": \"mine\",\n                    \"requirements\": [\"wooden_pickaxe\"],\n                    \"description\": \"Mine cobblestone with pickaxe\"\n                },\n                \"mine_iron_ore\": {\n                    \"type\": \"mine\",\n                    \"requirements\": [\"stone_pickaxe\"], \n                    \"description\": \"Mine iron ore with stone pickaxe\"\n                },\n                \"mine_diamond\": {\n                    \"type\": \"mine\",\n                    \"requirements\": [\"iron_pickaxe\"],\n                    \"description\": \"Mine diamond with iron pickaxe\"\n                }\n            }\n    \n    def get_supported_objects(self, goal_lib: Dict) -> Dict:\n        \"\"\"Get supported objects from goal library\"\"\"\n        supported_objs = {}\n        for key, value in goal_lib.items():\n            obj_name = key.replace(\"obtain_\", \"\").replace(\"mine_\", \"\")\n            supported_objs[obj_name] = value.get(\"type\", \"unknown\")\n        return supported_objs\n    \n    def load_initial_planning_prompt(self, group: str) -> str:\n        \"\"\"Load initial planning prompt\"\"\"\n        task_prompt_file = self.data_dir / \"task_prompt.txt\"\n        if task_prompt_file.exists():\n            with open(task_prompt_file, 'r') as f:\n                context = f.read()\n        else:\n            context = self.get_default_task_prompt()\n        \n        replan_prompt_file = self.data_dir / \"deps_prompt.txt\"\n        if replan_prompt_file.exists():\n            with open(replan_prompt_file, 'r') as f:\n                context += \"\\n\" + f.read()\n        else:\n            context += \"\\n\" + self.get_default_replan_prompt()\n        \n        return context\n    \n    def get_default_task_prompt(self) -> str:\n        \"\"\"Get default task prompt\"\"\"\n        return \"\"\"You are an expert Minecraft player tasked with planning actions to achieve specific goals.\n\nGiven a task, break it down into a sequence of achievable sub-goals. Consider:\n1. What items are needed\n2. What tools are required  \n3. The order of operations\n4. Dependencies between goals\n\nRespond with a clear, step-by-step plan.\n\nExample task: \"How to obtain wooden slab?\"\nPlan:\n1. Find trees\n2. Mine wood\n3. Craft wooden planks\n4. Craft wooden slab\n\n\"\"\"\n    \n    def get_default_replan_prompt(self) -> str:\n        \"\"\"Get default replan prompt\"\"\"\n        return \"\"\"When replanning, consider the current inventory state and adjust the plan accordingly.\nFocus on the most efficient path to achieve the goal given current resources.\n\n\"\"\"\n    \n    def load_parser_prompt(self) -> str:\n        \"\"\"Load parser prompt\"\"\"\n        parse_prompt_file = self.data_dir / \"parse_prompt.txt\"\n        if parse_prompt_file.exists():\n            with open(parse_prompt_file, 'r') as f:\n                return f.read()\n        else:\n            return \"Parse the following text and extract actionable goals:\"\n    \n    def _post_completion(self, prompt_text: str, temperature: float = 0.0, \n                    max_tokens: int = 512, stop: Optional[List[str]] = None) -> str:\n        \"\"\"Post completion request to local LLM\"\"\"\n        if not self.llm_available:\n            return self._fallback_response(prompt_text)\n        try:\n            response = requests.post(\n                f\"{self.llm_api_base}/chat/completions\",  # Changed from /completions\n                headers={\n                    \"Authorization\": f\"Bearer {self.llm_api_key}\",\n                    \"Content-Type\": \"application/json\"\n                },\n                json={\n                    \"model\": self.llm_model,\n                    \"messages\": [  # Changed to messages format\n                        {\n                            \"role\": \"user\",\n                            \"content\": prompt_text\n                        }\n                    ],\n                    \"temperature\": temperature,\n                    \"max_tokens\": max_tokens,\n                    \"stop\": stop,\n                    \"do_sample\": True if temperature > 0 else False,\n                    \"stream\": False\n                },\n                timeout=self.timeout\n            )\n            \n            if response.status_code == 200:\n                result = response.json()\n                # Changed to access message content instead of text\n                return result.get(\"choices\", [{}])[0].get(\"message\", {}).get(\"content\", \"\").strip()\n            else:\n                print(f\"[Warning] LLM API error: {response.status_code} - {response.text}\")\n                return self._fallback_response(prompt_text)\n                \n        except requests.exceptions.ConnectionError as e:\n            # Endpoint is down: stop retrying for the rest of the run\n            print(f\"[Warning] LLM API unreachable ({self.llm_api_base}); using rule-based planner: {e}\")\n            self.llm_available = False\n            return self._fallback_response(prompt_text)\n        except Exception as e:\n            print(f\"[Warning] LLM API request failed: {e}\")\n            return self._fallback_response(prompt_text)\n\n    \n    def _fallback_response(self, prompt_text: str, inventory: Optional[Dict[str, int]] = None) -> str:\n        \"\"\"Rule-based plan from the tech tree when the LLM is unavailable\"\"\"\n        if self.target is None:\n            return \"1. Assess current situation\\n2. Gather required materials\\n3. Craft or mine target item\"\n        return self.format_plan(plan_steps(self.target, inventory))\n    \n    @staticmethod\n    def format_plan(steps) -> str:\n        \"\"\"Format (verb, item) steps as a numbered plan, grouping repeats as xN\"\"\"\n        grouped = []\n        for step in steps:\n            if grouped and grouped[-1][0] == step:\n                grouped[-1][1] += 1\n            else:\n                grouped.append([step, 1])\n        lines = []\n        for i, ((verb, item), count) in enumerate(grouped, start=1):\n            suffix = f\" x{count}\" if count > 1 else \"\"\n            lines.append(f\"{i}. {verb.capitalize()} {item.replace('_', ' ')}{suffix}\")\n        return \"\\n\".join(lines)\n    \n    def query_llm(self, prompt_text: str) -> str:\n        \"\"\"Query local LLM\"\"\"\n        return self._post_completion(prompt_text)\n    \n    def online_parser(self, text: str) -> List[str]:\n        \"\"\"Parse text to extract goals\"\"\"\n        parser_prompt = self.load_parser_prompt()\n        full_prompt = f\"{parser_prompt}\\n\\nText: {text}\\n\\nGoals:\"\n        \n        response = self.query_llm(full_prompt)\n        \n        # Simple parsing - extract lines that look like goals\n        goals = []\n        for line in response.split('\\n'):\n            line = line.strip()\n            if line and (line.startswith('-') or line.startswith('*') or \n                        any(word in line.lower() for word in ['obtain', 'mine', 'craft', 'get'])):\n                # Clean up the line\n                goal = line.lstrip('- *').strip()\n                if goal:\n                    goals.append(goal)\n        \n        return goals[:5]  # Limit to 5 goals\n    \n    def check_object(self, obj: str) -> bool:\n        \"\"\"Check if object is supported\"\"\"\n        return obj in self.supported_objects\n    \n    def generate_goal_list(self, plan: str) -> List[str]:\n        \"\"\"Generate canonical goal list (e.g. mine_wood, obtain_stick) from a plan\"\"\"\n        goals = parse_plan_to_goals(plan)\n        if not goals and self.llm_available:\n            # Plan text had no recognizable items; ask the LLM to restate it as goals\n            goals = parse_plan_to_goals(\"\\n\".join(self.online_parser(plan)))\n        return goals\n    \n    def initial_planning(self, group: str, task_question: str, target: Optional[str] = None) -> str:\n        \"\"\"Generate initial plan for task\"\"\"\n        if target is not None:\n            self.target = target\n        prompt = self.load_initial_planning_prompt(group)\n        full_prompt = f\"{prompt}\\n\\nTask: {task_question}\\nPlan:\"\n        \n        plan = self.query_llm(full_prompt)\n        \n        # Update dialogue for context\n        self.dialogue += f\"Task: {task_question}\\nPlan: {plan}\\n\\n\"\n        self.logging_dialogue += f\"Task: {task_question}\\nPlan: {plan}\\n\\n\"\n        \n        return plan\n    \n    def generate_inventory_description(self, inventory: Dict[str, int]) -> str:\n        \"\"\"Generate inventory description\"\"\"\n        if not inventory:\n            return \"The inventory is empty.\"\n        \n        items = []\n        for item, count in inventory.items():\n            if count > 1:\n                items.append(f\"{count} {item}s\")\n            else:\n                items.append(f\"1 {item}\")\n        \n        return f\"Current inventory: {', '.join(items)}.\"\n    \n    def generate_success_description(self, step: str) -> str:\n        \"\"\"Generate success description\"\"\"\n        return f\"Successfully completed: {step}\"\n    \n    def generate_failure_description(self, step: str) -> str:\n        \"\"\"Generate failure description\"\"\"\n        return f\"Failed to complete: {step}\"\n    \n    def generate_explanation(self) -> str:\n        \"\"\"Generate explanation of current plan\"\"\"\n        if not self.dialogue:\n            return \"No plan generated yet.\"\n        \n        explanation_prompt = f\"Explain the following plan:\\n\\n{self.dialogue}\\n\\nExplanation:\"\n        return self.query_llm(explanation_prompt)\n    \n    def replan(self, task_question: str, inventory_desc: str = \"\",\n               inventory: Optional[Dict[str, int]] = None, failure_desc: str = \"\") -> str:\n        \"\"\"Replan based on current state (Describe, Explain, Plan and Select: describe, explain and plan step)\"\"\"\n        context = f\"Previous dialogue:\\n{self.dialogue}\\n\"\n        if failure_desc:\n            context += f\"Failure: {failure_desc}\\n\"\n        if inventory_desc:\n            context += f\"Current situation: {inventory_desc}\\n\"\n        \n        replan_prompt = f\"\"\"Given the current situation, create a new plan for: {task_question}\n\n{context}\n\nNew plan:\"\"\"\n        \n        if self.llm_available:\n            new_plan = self.query_llm(replan_prompt)\n        else:\n            new_plan = self._fallback_response(replan_prompt, inventory)\n        \n        # Update dialogue\n        self.dialogue += f\"Replan for: {task_question}\\nNew plan: {new_plan}\\n\\n\"\n        self.logging_dialogue += f\"Replan for: {task_question}\\nNew plan: {new_plan}\\n\\n\"\n        \n        return new_plan\n"},{"path":"diffu_moe_vlm/rl/__init__.py","text":"\"\"\"Training and evaluation utilities for learned policies (requires torch and crafter)\"\"\"\n"},{"path":"diffu_moe_vlm/rl/checkpoint.py","text":"\"\"\"Checkpoint save/load. A checkpoint stores the model config so it can be rebuilt without Hydra.\"\"\"\n\nfrom pathlib import Path\nfrom typing import Any, Dict, Optional\n\nimport torch\n\n\ndef save_checkpoint(path, model: torch.nn.Module, kind: str, model_cfg: Dict[str, Any],\n                    optimizer: Optional[torch.optim.Optimizer] = None, step: int = 0,\n                    extra: Optional[Dict[str, Any]] = None) -> Path:\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    torch.save({\n        'kind': kind,\n        'model_cfg': model_cfg,\n        'model': model.state_dict(),\n        'optimizer': optimizer.state_dict() if optimizer else None,\n        'step': step,\n        'extra': extra or {},\n    }, path)\n    return path\n\n\ndef load_checkpoint(path, device: str = 'cpu') -> Dict[str, Any]:\n    return torch.load(path, map_location=device, weights_only=False)\n\n\ndef load_policy(path, num_actions: int, device: str = 'cpu', image_size: int = 64):\n    \"\"\"Rebuild an ActorCritic ('ppo') or DiffusionPolicy ('diffusion') from a checkpoint\"\"\"\n    from ..nn.diffusion import build_diffusion_policy\n    from ..nn.policy import build_actor_critic\n\n    ckpt = load_checkpoint(path, device)\n    builder = {'ppo': build_actor_critic, 'diffusion': build_diffusion_policy}[ckpt['kind']]\n    model = builder(ckpt['model_cfg'], num_actions, image_size=image_size).to(device)\n    model.load_state_dict(ckpt['model'])\n    model.eval()\n    return model, ckpt\n"},{"path":"diffu_moe_vlm/rl/common.py","text":"\"\"\"Shared helpers for the training / evaluation entry points\"\"\"\n\nimport functools\nimport json\nimport random\nfrom pathlib import Path\nfrom typing import Callable, Dict, Optional\n\nimport numpy as np\nimport torch\n\nfrom ..crafter_env import CrafterEnv\nfrom .vec_env import VecEnv\n\n\ndef resolve_device(name: str = 'auto') -> str:\n    if name == 'auto':\n        return 'cuda' if torch.cuda.is_available() else 'cpu'\n    return name\n\n\ndef seed_everything(seed: int, torch_threads: Optional[int] = None):\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    if torch_threads:\n        # Leave CPU cores for environment worker processes\n        torch.set_num_threads(torch_threads)\n\n\ndef make_crafter_envs(num_envs: int, seed: int = 0, size: int = 64, length: int = 10000,\n                      num_workers: Optional[int] = None) -> VecEnv:\n    env_fn = functools.partial(CrafterEnv, size=size, length=length)\n    return VecEnv([env_fn] * num_envs, seeds=[seed + i for i in range(num_envs)], num_workers=num_workers)\n\n\ndef make_logger(wandb_cfg: Optional[Dict], run_config: Dict, jsonl_path=None) -> Callable[[Dict], None]:\n    \"\"\"Log metrics to a JSONL file and, if enabled, to Weights & Biases\"\"\"\n    wandb_run = None\n    if wandb_cfg and wandb_cfg.get('enabled', False):\n        import wandb\n        wandb_run = wandb.init(project=wandb_cfg.get('project', 'diffu-moe-vlm-crafter'),\n                               name=wandb_cfg.get('name'), tags=list(wandb_cfg.get('tags', [])),\n                               config=run_config)\n    jsonl = None\n    if jsonl_path is not None:\n        Path(jsonl_path).parent.mkdir(parents=True, exist_ok=True)\n        jsonl = open(jsonl_path, 'a')\n\n    def log(metrics: Dict):\n        if jsonl:\n            jsonl.write(json.dumps(metrics) + \"\\n\")\n            jsonl.flush()\n        if wandb_run:\n            wandb_run.log(metrics, step=int(metrics.get('step', 0)))\n\n    return log\n\n\ndef write_json(path, data: Dict):\n    Path(path).parent.mkdir(parents=True, exist_ok=True)\n    with open(path, 'w') as f:\n        json.dump(data, f, indent=2)\n"},{"path":"diffu_moe_vlm/rl/diffusion_bc.py","text":"\"\"\"Behavior cloning of the diffusion policy from recorded demonstrations\"\"\"\n\nimport time\nfrom typing import Callable, Dict, Optional\n\nimport numpy as np\nimport torch\n\nfrom .rollout import ActionChunkDataset\n\n\ndef train_diffusion_bc(model, data: Dict[str, np.ndarray], steps: int = 10_000, batch_size: int = 128,\n                       lr: float = 3e-4, device: str = 'cpu', log_every: int = 100,\n                       log_fn: Optional[Callable[[Dict], None]] = None, seed: int = 0):\n    dataset = ActionChunkDataset(data, model.horizon)\n    if len(dataset) == 0:\n        raise ValueError(f\"no demonstration windows of length {model.horizon}; collect more data\")\n    generator = torch.Generator().manual_seed(seed)\n    loader = torch.utils.data.DataLoader(dataset, batch_size=batch_size, shuffle=True, drop_last=True,\n                                         generator=generator)\n    model.to(device).train()\n    optimizer = torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=1e-4)\n    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(optimizer, steps)\n    step, start, losses = 0, time.time(), []\n    while step < steps:\n        for obs, actions in loader:\n            loss = model.loss(obs.to(device), actions.to(device))\n            optimizer.zero_grad()\n            loss.backward()\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            optimizer.step()\n            scheduler.step()\n            losses.append(loss.item())\n            step += 1\n            if step % log_every == 0 or step == steps:\n                metrics = {'step': step, 'loss/diffusion': float(np.mean(losses[-log_every:])),\n                           'sps': step * batch_size / (time.time() - start)}\n                if log_fn:\n                    log_fn(metrics)\n                print(f\"[Diffusion BC] step {step}/{steps} loss={metrics['loss/diffusion']:.4f}\")\n            if step >= steps:\n                break\n    model.eval()\n    return model\n"},{"path":"diffu_moe_vlm/rl/ppo.py","text":"\"\"\"\nProximal Policy Optimization for the MoE actor-critic.\n\nStandard clipped PPO with GAE. The MoE load-balancing loss is added to the\nobjective with `moe_aux_coef`. Episode returns and Crafter achievements are\ntracked from the vectorized environment and reported per update.\nTime-limit truncation is treated like termination when bootstrapping, which\nis negligible for Crafter's 10k-step episodes.\n\"\"\"\n\nimport time\nfrom dataclasses import dataclass\nfrom typing import Callable, Dict, Optional\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\n\nfrom ..crafter_env import AchievementTracker, format_achievements\nfrom .vec_env import VecEnv\n\n\n@dataclass\nclass PPOConfig:\n    total_steps: int = 1_000_000\n    num_envs: int = 8\n    rollout_length: int = 128\n    epochs: int = 4\n    minibatches: int = 8\n    lr: float = 3e-4\n    gamma: float = 0.95\n    gae_lambda: float = 0.65\n    clip: float = 0.2\n    value_coef: float = 0.5\n    entropy_coef: float = 0.01\n    moe_aux_coef: float = 0.01\n    max_grad_norm: float = 0.5\n    anneal_lr: bool = True\n    log_window: int = 100  # episodes used for logged success rates\n\n\nclass PPOTrainer:\n    def __init__(self, model: nn.Module, envs: VecEnv, cfg: PPOConfig, device: str = 'cpu',\n                 log_fn: Optional[Callable[[Dict], None]] = None,\n                 checkpoint_fn: Optional[Callable[[int], None]] = None, checkpoint_every: int = 0):\n        self.model = model.to(device)\n        self.envs = envs\n        self.cfg = cfg\n        self.device = device\n        self.optimizer = torch.optim.Adam(model.parameters(), lr=cfg.lr, eps=1e-5)\n        self.tracker = AchievementTracker()\n        self.log_fn = log_fn or (lambda metrics: None)\n        self.checkpoint_fn = checkpoint_fn\n        self.checkpoint_every = checkpoint_every\n        self.global_step = 0\n\n    def _collect(self, obs: np.ndarray):\n        cfg, n = self.cfg, self.envs.num_envs\n        buf_obs = np.zeros((cfg.rollout_length, n) + obs.shape[1:], dtype=np.uint8)\n        buf_actions = torch.zeros(cfg.rollout_length, n, dtype=torch.long)\n        buf_logp = torch.zeros(cfg.rollout_length, n)\n        buf_values = torch.zeros(cfg.rollout_length, n)\n        buf_rewards = torch.zeros(cfg.rollout_length, n)\n        buf_dones = torch.zeros(cfg.rollout_length, n)\n\n        self.model.eval()\n        for t in range(cfg.rollout_length):\n            buf_obs[t] = obs\n            action, logp, value = self.model.act(torch.as_tensor(obs, device=self.device))\n            obs, reward, done, episodes = self.envs.step(action.cpu().numpy())\n            buf_actions[t], buf_logp[t], buf_values[t] = action.cpu(), logp.cpu(), value.cpu()\n            buf_rewards[t] = torch.as_tensor(reward)\n            buf_dones[t] = torch.as_tensor(done)\n            for ep in episodes:\n                if ep is not None:\n                    self.tracker.add_episode(ep['achievements'], ep['return'], ep['length'])\n        self.global_step += cfg.rollout_length * n\n\n        with torch.no_grad():\n            _, last_value, _ = self.model(torch.as_tensor(obs, device=self.device))\n        advantages = torch.zeros_like(buf_rewards)\n        gae = torch.zeros(n)\n        next_value = last_value.cpu()\n        for t in reversed(range(cfg.rollout_length)):\n            not_done = 1.0 - buf_dones[t]\n            delta = buf_rewards[t] + cfg.gamma * next_value * not_done - buf_values[t]\n            gae = delta + cfg.gamma * cfg.gae_lambda * not_done * gae\n            advantages[t] = gae\n            next_value = buf_values[t]\n        returns = advantages + buf_values\n        batch = {\n            'obs': buf_obs.reshape((-1,) + buf_obs.shape[2:]),\n            'actions': buf_actions.flatten(),\n            'logp': buf_logp.flatten(),\n            'advantages': advantages.flatten(),\n            'returns': returns.flatten(),\n        }\n        return obs, batch\n\n    def _update(self, batch) -> Dict[str, float]:\n        cfg = self.cfg\n        self.model.train()\n        size = batch['actions'].shape[0]\n        mb_size = size // cfg.minibatches\n        stats = {'loss/policy': [], 'loss/value': [], 'loss/entropy': [], 'loss/moe_aux': [], 'ppo/clip_frac': [],\n                 'ppo/approx_kl': []}\n        for _ in range(cfg.epochs):\n            perm = torch.randperm(size)\n            for start in range(0, size - mb_size + 1, mb_size):\n                idx = perm[start:start + mb_size]\n                obs = torch.as_tensor(batch['obs'][idx.numpy()], device=self.device)\n                actions = batch['actions'][idx].to(self.device)\n                old_logp = batch['logp'][idx].to(self.device)\n                adv = batch['advantages'][idx].to(self.device)\n                adv = (adv - adv.mean()) / (adv.std() + 1e-8)\n                ret = batch['returns'][idx].to(self.device)\n\n                logp, entropy, value, aux = self.model.evaluate_actions(obs, actions)\n                ratio = (logp - old_logp).exp()\n                policy_loss = -torch.min(ratio * adv, ratio.clamp(1 - cfg.clip, 1 + cfg.clip) * adv).mean()\n                value_loss = 0.5 * (value - ret).pow(2).mean()\n                entropy_mean = entropy.mean()\n                loss = (policy_loss + cfg.value_coef * value_loss - cfg.entropy_coef * entropy_mean\n                        + cfg.moe_aux_coef * aux)\n\n                self.optimizer.zero_grad()\n                loss.backward()\n                nn.utils.clip_grad_norm_(self.model.parameters(), cfg.max_grad_norm)\n                self.optimizer.step()\n\n                with torch.no_grad():\n                    stats['loss/policy'].append(policy_loss.item())\n                    stats['loss/value'].append(value_loss.item())\n                    stats['loss/entropy'].append(entropy_mean.item())\n                    stats['loss/moe_aux'].append(float(aux))\n                    stats['ppo/clip_frac'].append(((ratio - 1).abs() > cfg.clip).float().mean().item())\n                    stats['ppo/approx_kl'].append((old_logp - logp).mean().item())\n        return {k: float(np.mean(v)) for k, v in stats.items()}\n\n    def train(self) -> AchievementTracker:\n        cfg = self.cfg\n        num_updates = max(1, cfg.total_steps // (cfg.rollout_length * self.envs.num_envs))\n        obs = self.envs.reset()\n        start = time.time()\n        for update in range(1, num_updates + 1):\n            if cfg.anneal_lr:\n                for group in self.optimizer.param_groups:\n                    group['lr'] = cfg.lr * (1.0 - (update - 1) / num_updates)\n            obs, batch = self._collect(obs)\n            stats = self._update(batch)\n\n            summary = self.tracker.summary(last=cfg.log_window)\n            metrics = {'step': self.global_step, 'sps': self.global_step / (time.time() - start), **stats, **summary}\n            if hasattr(self.model, 'trunk'):\n                for layer, load in enumerate(self.model.trunk.expert_load()):\n                    for e, frac in enumerate(load):\n                        metrics[f'moe/layer{layer}_expert{e}_load'] = frac\n            self.log_fn(metrics)\n            print(f\"[PPO] update {update}/{num_updates} step={self.global_step} sps={metrics['sps']:.0f} \"\n                  f\"episodes={summary['episodes']} return={summary['return_mean']:.2f} \"\n                  f\"score={summary['score']:.2f} entropy={stats['loss/entropy']:.3f}\")\n            if self.checkpoint_fn and self.checkpoint_every and update % self.checkpoint_every == 0:\n                self.checkpoint_fn(self.global_step)\n\n        if self.tracker.episodes:\n            print(\"[PPO] achievements (last window): \" +\n                  format_achievements(self.tracker.success_rates(last=cfg.log_window)))\n        return self.tracker\n"},{"path":"diffu_moe_vlm/rl/rollout.py","text":"\"\"\"\nPolicy runners, evaluation and demonstration collection.\n\nA runner maps a batch of observations (N, H, W, 3) uint8 to actions (N,)\nand is told when episodes end so chunked policies can drop queued actions.\n\"\"\"\n\nfrom pathlib import Path\nfrom typing import Dict, List, Optional\n\nimport numpy as np\nimport torch\n\nfrom ..crafter_env import AchievementTracker\nfrom .vec_env import VecEnv\n\n\nclass RandomRunner:\n    def __init__(self, num_actions: int, seed: int = 0):\n        self.num_actions = num_actions\n        self.rng = np.random.default_rng(seed)\n\n    def __call__(self, obs: np.ndarray) -> np.ndarray:\n        return self.rng.integers(self.num_actions, size=len(obs))\n\n    def episode_done(self, env_index: int):\n        pass\n\n\nclass ActorCriticRunner:\n    def __init__(self, model, device: str = 'cpu', deterministic: bool = False):\n        self.model, self.device, self.deterministic = model, device, deterministic\n\n    def __call__(self, obs: np.ndarray) -> np.ndarray:\n        action, _, _ = self.model.act(torch.as_tensor(obs, device=self.device), deterministic=self.deterministic)\n        return action.cpu().numpy()\n\n    def episode_done(self, env_index: int):\n        pass\n\n\nclass DiffusionRunner:\n    \"\"\"Receding-horizon execution: sample an action chunk, execute the first `execute_steps`, replan\"\"\"\n\n    def __init__(self, model, device: str = 'cpu', execute_steps: int = 4, sample_steps: Optional[int] = 10):\n        self.model, self.device = model, device\n        self.execute_steps = execute_steps\n        self.sample_steps = sample_steps\n        self.queues: Dict[int, List[int]] = {}\n\n    def __call__(self, obs: np.ndarray) -> np.ndarray:\n        need = [i for i in range(len(obs)) if not self.queues.get(i)]\n        if need:\n            chunks = self.model.sample(torch.as_tensor(obs[need], device=self.device), num_steps=self.sample_steps)\n            for i, chunk in zip(need, chunks.cpu().tolist()):\n                self.queues[i] = chunk[:self.execute_steps]\n        return np.array([self.queues[i].pop(0) for i in range(len(obs))])\n\n    def episode_done(self, env_index: int):\n        self.queues[env_index] = []\n\n\n@torch.no_grad()\ndef evaluate(runner, envs: VecEnv, num_episodes: int, max_steps: int = 1_000_000) -> AchievementTracker:\n    \"\"\"Run until `num_episodes` episodes have finished across all envs\"\"\"\n    tracker = AchievementTracker()\n    obs = envs.reset()\n    steps = 0\n    while len(tracker.episodes) < num_episodes and steps < max_steps:\n        obs, _, _, episodes = envs.step(runner(obs))\n        steps += 1\n        for i, ep in enumerate(episodes):\n            if ep is not None:\n                runner.episode_done(i)\n                if len(tracker.episodes) < num_episodes:\n                    tracker.add_episode(ep['achievements'], ep['return'], ep['length'])\n    return tracker\n\n\n@torch.no_grad()\ndef collect_demonstrations(runner, envs: VecEnv, num_steps: int, path=None) -> Dict[str, np.ndarray]:\n    \"\"\"\n    Record (observation, action) pairs. Returns arrays `obs` (N, H, W, 3),\n    `actions` (N,) and `episode` (N,) ids; frames of one episode are contiguous.\n    \"\"\"\n    obs = envs.reset()\n    per_env = [{'obs': [], 'actions': []} for _ in range(envs.num_envs)]\n    out_obs, out_actions, out_episode = [], [], []\n    episode_id = 0\n    total = 0\n\n    def flush(i):\n        nonlocal episode_id\n        if per_env[i]['actions']:\n            out_obs.extend(per_env[i]['obs'])\n            out_actions.extend(per_env[i]['actions'])\n            out_episode.extend([episode_id] * len(per_env[i]['actions']))\n            episode_id += 1\n        per_env[i] = {'obs': [], 'actions': []}\n\n    while total < num_steps:\n        actions = runner(obs)\n        for i in range(envs.num_envs):\n            per_env[i]['obs'].append(obs[i])\n            per_env[i]['actions'].append(int(actions[i]))\n        obs, _, _, episodes = envs.step(actions)\n        total += envs.num_envs\n        for i, ep in enumerate(episodes):\n            if ep is not None:\n                runner.episode_done(i)\n                flush(i)\n    for i in range(envs.num_envs):\n        flush(i)\n\n    data = {\n        'obs': np.stack(out_obs).astype(np.uint8),\n        'actions': np.array(out_actions, dtype=np.int64),\n        'episode': np.array(out_episode, dtype=np.int64),\n    }\n    if path is not None:\n        Path(path).parent.mkdir(parents=True, exist_ok=True)\n        np.savez_compressed(path, **data)\n    return data\n\n\nclass ActionChunkDataset(torch.utils.data.Dataset):\n    \"\"\"(obs_t, actions_{t..t+H-1}) windows that stay within one episode\"\"\"\n\n    def __init__(self, data: Dict[str, np.ndarray], horizon: int):\n        self.obs = data['obs']\n        self.actions = data['actions']\n        episode = data['episode']\n        ends_ok = np.zeros(len(episode), dtype=bool)\n        if len(episode) >= horizon:\n            same = episode[:len(episode) - horizon + 1] == episode[horizon - 1:]\n            ends_ok[:len(same)] = same\n        self.starts = np.nonzero(ends_ok)[0]\n        self.horizon = horizon\n\n    def __len__(self):\n        return len(self.starts)\n\n    def __getitem__(self, i):\n        s = self.starts[i]\n        return torch.as_tensor(self.obs[s]), torch.as_tensor(self.actions[s:s + self.horizon])\n"},{"path":"diffu_moe_vlm/rl/vec_env.py","text":"\"\"\"\nMinimal vectorized environment with same-step auto-reset.\n\nEach sub-environment runs in its own process (or in-process when\n`num_workers=0`). When an episode ends, the worker records its return, length\nand final achievements, resets, and returns the first observation of the next\nepisode, so rollouts never contain a terminal observation.\n\"\"\"\n\nimport multiprocessing as mp\nfrom typing import Callable, List, Optional, Tuple\n\nimport numpy as np\n\n\nclass _EpisodeEnv:\n    \"\"\"Wraps one env, tracks episode statistics and auto-resets\"\"\"\n\n    def __init__(self, env_fn: Callable, seed: Optional[int]):\n        self.env = env_fn()\n        self.seed = seed\n        self.episode_return = 0.0\n        self.episode_length = 0\n\n    def reset(self):\n        obs, _ = self.env.reset(seed=self.seed)\n        self.seed = None\n        self.episode_return, self.episode_length = 0.0, 0\n        return obs\n\n    def step(self, action):\n        obs, reward, terminated, truncated, info = self.env.step(action)\n        self.episode_return += reward\n        self.episode_length += 1\n        episode = None\n        done = terminated or truncated\n        if done:\n            episode = {\n                'return': self.episode_return,\n                'length': self.episode_length,\n                'achievements': dict(info.get('achievements', {})),\n                'terminated': terminated,\n            }\n            obs = self.reset()\n        return obs, reward, done, episode\n\n\ndef _worker(remote, env_fn, seed):\n    env = _EpisodeEnv(env_fn, seed)\n    try:\n        while True:\n            cmd, data = remote.recv()\n            if cmd == 'reset':\n                remote.send(env.reset())\n            elif cmd == 'step':\n                remote.send(env.step(data))\n            elif cmd == 'close':\n                break\n    finally:\n        remote.close()\n\n\nclass VecEnv:\n    def __init__(self, env_fns: List[Callable], seeds: Optional[List[int]] = None, num_workers: Optional[int] = None):\n        self.num_envs = len(env_fns)\n        seeds = seeds or [None] * self.num_envs\n        self.parallel = (num_workers if num_workers is not None else self.num_envs) > 0\n        if self.parallel:\n            ctx = mp.get_context('spawn')\n            self.remotes, self.processes = [], []\n            for fn, seed in zip(env_fns, seeds):\n                parent, child = ctx.Pipe()\n                proc = ctx.Process(target=_worker, args=(child, fn, seed), daemon=True)\n                proc.start()\n                child.close()\n                self.remotes.append(parent)\n                self.processes.append(proc)\n        else:\n            self.envs = [_EpisodeEnv(fn, seed) for fn, seed in zip(env_fns, seeds)]\n\n    def reset(self) -> np.ndarray:\n        if self.parallel:\n            for r in self.remotes:\n                r.send(('reset', None))\n            return np.stack([r.recv() for r in self.remotes])\n        return np.stack([e.reset() for e in self.envs])\n\n    def step(self, actions) -> Tuple[np.ndarray, np.ndarray, np.ndarray, List[Optional[dict]]]:\n        if self.parallel:\n            for r, a in zip(self.remotes, actions):\n                r.send(('step', int(a)))\n            results = [r.recv() for r in self.remotes]\n        else:\n            results = [e.step(int(a)) for e, a in zip(self.envs, actions)]\n        obs, rewards, dones, episodes = zip(*results)\n        return np.stack(obs), np.array(rewards, dtype=np.float32), np.array(dones, dtype=np.float32), list(episodes)\n\n    def close(self):\n        if self.parallel:\n            for r in self.remotes:\n                try:\n                    r.send(('close', None))\n                except (BrokenPipeError, EOFError):\n                    pass\n            for p in self.processes:\n                p.join(timeout=5)\n"},{"path":"diffu_moe_vlm/selector.py","text":"\"\"\"\nMC-Planner Selector Module\nGoal selection and horizon planning without Java dependencies\n\"\"\"\n\nimport random\nfrom typing import List, Dict, Any, Optional\n\nfrom .core import action_requirements, apply_action, goal_item, obtain_method\n\n\nclass Selector:\n    \"\"\"\n    Goal selector for MC-Planner\n    Implements various selection strategies for goal prioritization\n    \"\"\"\n    \n    STRATEGIES = [\"plan_order\", \"priority\", \"random\", \"round_robin\", \"dependency\"]\n\n    def __init__(self, strategy: str = \"plan_order\", priorities: Optional[Dict[str, float]] = None):\n        if strategy not in self.STRATEGIES:\n            raise ValueError(f\"Invalid strategy {strategy!r}. Must be one of: {self.STRATEGIES}\")\n        self.strategy = strategy\n        self.goal_priorities = self._initialize_priorities()\n        if priorities:\n            self.goal_priorities.update(priorities)\n        self.selection_history = []\n        \n    def _initialize_priorities(self) -> Dict[str, float]:\n        \"\"\"Initialize goal priorities\"\"\"\n        return {\n            # Basic resources (high priority)\n            \"mine_wood\": 1.0,\n            \"mine_stone\": 0.9,\n            \"mine_cobblestone\": 0.9,\n            \n            # Tools (medium-high priority)\n            \"obtain_wooden_pickaxe\": 0.8,\n            \"obtain_stone_pickaxe\": 0.7,\n            \"obtain_iron_pickaxe\": 0.6,\n            \n            # Advanced materials (medium priority)\n            \"mine_iron_ore\": 0.5,\n            \"obtain_iron_ingot\": 0.5,\n            \"mine_coal\": 0.4,\n            \n            # Crafted items (lower priority)\n            \"obtain_wooden_slab\": 0.3,\n            \"obtain_stone_stairs\": 0.3,\n            \"obtain_painting\": 0.2,\n            \n            # Rare materials (variable priority)\n            \"mine_diamond\": 0.1,\n        }\n    \n    def check_precondition(self, goal: str, inventory: Dict[str, int] = None) -> bool:\n        \"\"\"\n        Check if preconditions for a goal are met\n        \"\"\"\n        if inventory is None:\n            return True  # No inventory check\n        \n        item = goal_item(goal)\n        verb = obtain_method(item)\n        if verb is None:\n            return False\n        \n        # Direct requirements of one action from the tech tree\n        tools, consumed = action_requirements(verb, item)\n        for req, required_amount in {**tools, **consumed}.items():\n            if inventory.get(req, 0) < required_amount:\n                return False\n        \n        return True\n    \n    def generate_candidate_goal_list(self, goal_list: List[str], \n                                   inventory: Dict[str, int] = None,\n                                   max_candidates: int = 5) -> List[str]:\n        \"\"\"\n        Generate candidate goals from the full goal list\n        \"\"\"\n        if not goal_list:\n            return []\n        \n        candidates = []\n        \n        # Filter goals based on preconditions\n        for goal in goal_list:\n            if self.check_precondition(goal, inventory):\n                candidates.append(goal)\n        \n        # If no goal is directly executable, keep the earliest one; the controller\n        # gathers its prerequisites\n        if not candidates:\n            candidates = goal_list[:1]\n        \n        # Limit candidates\n        return candidates[:max_candidates]\n    \n    def horizon_select(self, candidate_goal_list: List[str], \n                      inventory: Dict[str, int] = None,\n                      context: Dict[str, Any] = None) -> str:\n        \"\"\"\n        Select the best goal from candidates using the configured strategy\n        \"\"\"\n        if not candidate_goal_list:\n            return \"\"\n        \n        if len(candidate_goal_list) == 1:\n            selected = candidate_goal_list[0]\n        else:\n            if self.strategy == \"plan_order\":\n                selected = candidate_goal_list[0]\n            elif self.strategy == \"priority\":\n                selected = self._priority_select(candidate_goal_list)\n            elif self.strategy == \"random\":\n                selected = self._random_select(candidate_goal_list)\n            elif self.strategy == \"round_robin\":\n                selected = self._round_robin_select(candidate_goal_list)\n            elif self.strategy == \"dependency\":\n                selected = self._dependency_select(candidate_goal_list, inventory)\n            else:\n                # Default to priority\n                selected = self._priority_select(candidate_goal_list)\n        \n        # Record selection\n        self.selection_history.append(selected)\n        \n        return selected\n    \n    def _priority_select(self, candidates: List[str]) -> str:\n        \"\"\"Select based on predefined priorities\"\"\"\n        best_goal = candidates[0]\n        best_priority = self.goal_priorities.get(best_goal, 0.0)\n        \n        for goal in candidates[1:]:\n            priority = self.goal_priorities.get(goal, 0.0)\n            if priority > best_priority:\n                best_goal = goal\n                best_priority = priority\n        \n        return best_goal\n    \n    def _random_select(self, candidates: List[str]) -> str:\n        \"\"\"Random selection\"\"\"\n        return random.choice(candidates)\n    \n    def _round_robin_select(self, candidates: List[str]) -> str:\n        \"\"\"Round-robin selection to ensure diversity\"\"\"\n        if not self.selection_history:\n            return candidates[0]\n        \n        # Find candidates not recently selected\n        recent_selections = set(self.selection_history[-len(candidates):])\n        unselected = [goal for goal in candidates if goal not in recent_selections]\n        \n        if unselected:\n            return unselected[0]\n        else:\n            return candidates[0]\n    \n    def _dependency_select(self, candidates: List[str], \n                          inventory: Dict[str, int] = None) -> str:\n        \"\"\"Select based on dependency analysis\"\"\"\n        if inventory is None:\n            return self._priority_select(candidates)\n        \n        # Score goals based on how many dependencies they fulfill\n        dependency_scores = {}\n        \n        for goal in candidates:\n            score = 0\n            \n            # Check what this goal enables\n            if \"pickaxe\" in goal:\n                score += 2  # Tools enable mining\n            if \"mine\" in goal:\n                score += 1  # Mining provides materials\n            if \"wood\" in goal:\n                score += 1.5  # Wood is fundamental\n            \n            # Bonus for goals that use current inventory\n            if goal.startswith(\"obtain_\"):\n                # Check if we have materials for crafting\n                if \"wooden\" in goal and inventory.get(\"wood\", 0) > 0:\n                    score += 1\n                if \"stone\" in goal and inventory.get(\"cobblestone\", 0) > 0:\n                    score += 1\n            \n            dependency_scores[goal] = score\n        \n        # Select highest scoring goal\n        best_goal = max(candidates, key=lambda g: dependency_scores.get(g, 0))\n        return best_goal\n    \n    def set_strategy(self, strategy: str):\n        \"\"\"Change selection strategy\"\"\"\n        if strategy in self.STRATEGIES:\n            self.strategy = strategy\n        else:\n            raise ValueError(f\"Invalid strategy. Must be one of: {self.STRATEGIES}\")\n    \n    def update_priorities(self, new_priorities: Dict[str, float]):\n        \"\"\"Update goal priorities\"\"\"\n        self.goal_priorities.update(new_priorities)\n    \n    def get_selection_stats(self) -> Dict[str, Any]:\n        \"\"\"Get statistics about goal selection\"\"\"\n        if not self.selection_history:\n            return {\"total_selections\": 0}\n        \n        from collections import Counter\n        selection_counts = Counter(self.selection_history)\n        \n        return {\n            \"total_selections\": len(self.selection_history),\n            \"unique_goals\": len(selection_counts),\n            \"most_common\": selection_counts.most_common(5),\n            \"recent_selections\": self.selection_history[-10:],\n        }\n    \n    def reset(self):\n        \"\"\"Reset selector state\"\"\"\n        self.selection_history = []\n\n\nclass HorizonSelector(Selector):\n    \"\"\"\n    Advanced selector with horizon planning capabilities\n    \"\"\"\n    \n    def __init__(self, horizon: int = 3, strategy: str = \"plan_order\",\n                 priorities: Optional[Dict[str, float]] = None):\n        super().__init__(strategy, priorities)\n        self.horizon = horizon\n        self.planned_sequence = []\n        \n    def horizon_select(self, candidate_goal_list: List[str], \n                      inventory: Dict[str, int] = None,\n                      context: Dict[str, Any] = None) -> str:\n        \"\"\"\n        Select goal considering multi-step horizon\n        \"\"\"\n        if not candidate_goal_list:\n            return \"\"\n        \n        # If we have a planned sequence, continue with it\n        if self.planned_sequence:\n            next_goal = self.planned_sequence.pop(0)\n            if next_goal in candidate_goal_list:\n                self.selection_history.append(next_goal)\n                return next_goal\n            else:\n                # Clear invalid sequence\n                self.planned_sequence = []\n        \n        # Plan new sequence\n        self.planned_sequence = self._plan_horizon_sequence(\n            candidate_goal_list, inventory, self.horizon\n        )\n        \n        if self.planned_sequence:\n            selected = self.planned_sequence.pop(0)\n            self.selection_history.append(selected)\n            return selected\n        else:\n            # Fallback to single-step selection\n            return super().horizon_select(candidate_goal_list, inventory, context)\n    \n    def _plan_horizon_sequence(self, candidates: List[str], \n                              inventory: Dict[str, int], \n                              horizon: int) -> List[str]:\n        \"\"\"\n        Plan a sequence of goals for the given horizon\n        \"\"\"\n        if horizon <= 1 or not candidates:\n            return candidates[:1]\n        \n        # Simple horizon planning: prioritize dependency chains\n        sequence = []\n        remaining_candidates = candidates.copy()\n        current_inventory = inventory.copy() if inventory else {}\n        \n        for step in range(min(horizon, len(candidates))):\n            if not remaining_candidates:\n                break\n            \n            # Select best goal for current state\n            best_goal = self._select_best_for_state(remaining_candidates, current_inventory)\n            sequence.append(best_goal)\n            remaining_candidates.remove(best_goal)\n            \n            # Simulate inventory update\n            current_inventory = self._simulate_goal_completion(best_goal, current_inventory)\n        \n        return sequence\n    \n    def _select_best_for_state(self, candidates: List[str], \n                              inventory: Dict[str, int]) -> str:\n        \"\"\"Select best goal for current inventory state\"\"\"\n        # Prefer goals that are directly executable in the simulated state\n        executable = [g for g in candidates if self.check_precondition(g, inventory)] or candidates\n        if self.strategy == \"plan_order\":\n            return executable[0]\n        return self._dependency_select(executable, inventory)\n    \n    def _simulate_goal_completion(self, goal: str, \n                                 inventory: Dict[str, int]) -> Dict[str, int]:\n        \"\"\"Simulate inventory changes after goal completion\"\"\"\n        item = goal_item(goal)\n        verb = obtain_method(item)\n        if verb is None:\n            return inventory.copy()\n        new_inventory, _, _ = apply_action(inventory, verb, item)\n        return new_inventory\n    \n    def reset(self):\n        \"\"\"Reset selector state, including the planned horizon sequence\"\"\"\n        super().reset()\n        self.planned_sequence = []\n"},{"path":"diffu_moe_vlm/utils.py","text":"\"\"\"\nUtility functions for MC-Planner migration\n\"\"\"\n\nimport numpy as np\nfrom typing import Dict, List, Any, Optional, Tuple\nimport cv2\nfrom pathlib import Path\n\n\ndef resize_image_numpy(img: np.ndarray, target_resolution: Tuple[int, int] = (128, 128)) -> np.ndarray:\n    \"\"\"Resize image to target resolution\"\"\"\n    return cv2.resize(img, dsize=target_resolution, interpolation=cv2.INTER_LINEAR)\n\n\ndef normalize_action(action: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Normalize action values to expected ranges\"\"\"\n    normalized = action.copy()\n    \n    # Ensure camera values are in [-1, 1] range\n    if 'camera' in normalized:\n        camera = np.array(normalized['camera'])\n        camera = np.clip(camera, -1.0, 1.0)\n        normalized['camera'] = camera\n    \n    # Ensure discrete actions are integers\n    discrete_actions = ['movement', 'use', 'attack', 'jump']\n    for key in discrete_actions:\n        if key in normalized:\n            normalized[key] = int(normalized[key])\n    \n    return normalized\n\n\ndef calculate_inventory_hash(inventory: Dict[str, int]) -> str:\n    \"\"\"Calculate hash of inventory state for caching\"\"\"\n    import hashlib\n    \n    # Sort items for consistent hashing\n    sorted_items = sorted(inventory.items())\n    inventory_str = str(sorted_items)\n    \n    return hashlib.md5(inventory_str.encode()).hexdigest()\n\n\ndef format_inventory_description(inventory: Dict[str, int]) -> str:\n    \"\"\"Format inventory for human-readable description\"\"\"\n    if not inventory:\n        return \"Empty inventory\"\n    \n    items = []\n    for item, count in sorted(inventory.items()):\n        if count > 0:\n            if count == 1:\n                items.append(f\"{count} {item}\")\n            else:\n                items.append(f\"{count} {item}s\")\n    \n    if not items:\n        return \"Empty inventory\"\n    \n    return \", \".join(items)\n\n\ndef check_goal_completion(goal: str, inventory: Dict[str, int]) -> bool:\n    \"\"\"Check if a goal is completed based on inventory\"\"\"\n    # Extract target item from goal\n    if goal.startswith(\"obtain_\"):\n        target_item = goal.replace(\"obtain_\", \"\")\n    elif goal.startswith(\"mine_\"):\n        target_item = goal.replace(\"mine_\", \"\")\n    else:\n        target_item = goal\n    \n    return inventory.get(target_item, 0) > 0\n\n\ndef estimate_goal_difficulty(goal: str, inventory: Dict[str, int]) -> float:\n    \"\"\"Estimate difficulty of achieving a goal given current inventory\"\"\"\n    # Basic difficulty scoring\n    base_difficulties = {\n        'mine_wood': 0.1,\n        'obtain_wooden_planks': 0.1,\n        'obtain_stick': 0.2,\n        'obtain_wooden_pickaxe': 0.3,\n        'mine_cobblestone': 0.4,\n        'obtain_stone_pickaxe': 0.5,\n        'mine_iron_ore': 0.6,\n        'obtain_iron_ingot': 0.7,\n        'obtain_iron_pickaxe': 0.8,\n        'mine_diamond': 0.9,\n        'obtain_wooden_slab': 0.3,\n        'obtain_stone_stairs': 0.4,\n        'obtain_painting': 0.8,\n    }\n    \n    base_difficulty = base_difficulties.get(goal, 0.5)\n    \n    # Adjust based on available resources\n    if goal.startswith(\"obtain_\"):\n        target_item = goal.replace(\"obtain_\", \"\")\n        \n        # Check if we have required materials\n        requirements = {\n            'wooden_slab': {'wooden_planks': 3},\n            'stone_stairs': {'cobblestone': 6},\n            'painting': {'stick': 8, 'wool': 1},\n            'wooden_pickaxe': {'wooden_planks': 3, 'stick': 2},\n            'stone_pickaxe': {'cobblestone': 3, 'stick': 2},\n            'iron_pickaxe': {'iron_ingot': 3, 'stick': 2},\n        }\n        \n        if target_item in requirements:\n            required_items = requirements[target_item]\n            missing_items = 0\n            total_items = len(required_items)\n            \n            for item, required_amount in required_items.items():\n                if inventory.get(item, 0) < required_amount:\n                    missing_items += 1\n            \n            # Reduce difficulty if we have required materials\n            availability_factor = (total_items - missing_items) / total_items\n            base_difficulty *= (1 - availability_factor * 0.5)\n    \n    return base_difficulty\n\n\ndef create_action_sequence(action_type: str, **kwargs) -> List[Dict[str, Any]]:\n    \"\"\"Create a sequence of actions for common tasks\"\"\"\n    actions = []\n    \n    if action_type == \"move_forward\":\n        times = kwargs.get('times', 5)\n        for _ in range(times):\n            actions.append({\n                'movement': 0,  # forward\n                'camera': np.array([0.0, 0.0]),\n                'use': 0,\n                'attack': 0,\n                'jump': 0\n            })\n    \n    elif action_type == \"mine\":\n        times = kwargs.get('times', 20)\n        for _ in range(times):\n            actions.append({\n                'movement': 0,\n                'camera': np.array([0.0, 0.0]),\n                'use': 0,\n                'attack': 1,  # mine/attack\n                'jump': 0\n            })\n    \n    elif action_type == \"use_item\":\n        actions.append({\n            'movement': 0,\n            'camera': np.array([0.0, 0.0]),\n            'use': 1,  # use/interact\n            'attack': 0,\n            'jump': 0\n        })\n    \n    elif action_type == \"look_around\":\n        # Look in different directions\n        directions = [\n            np.array([0.3, 0.0]),   # right\n            np.array([0.0, 0.3]),   # up\n            np.array([-0.3, 0.0]),  # left\n            np.array([0.0, -0.3]),  # down\n            np.array([0.0, 0.0])    # center\n        ]\n        for direction in directions:\n            actions.append({\n                'movement': 0,\n                'camera': direction,\n                'use': 0,\n                'attack': 0,\n                'jump': 0\n            })\n    \n    elif action_type == \"no_op\":\n        times = kwargs.get('times', 1)\n        for _ in range(times):\n            actions.append({\n                'movement': 0,\n                'camera': np.array([0.0, 0.0]),\n                'use': 0,\n                'attack': 0,\n                'jump': 0\n            })\n    \n    return actions\n\n\ndef save_experiment_results(results: Dict[str, Any], output_path: str):\n    \"\"\"Save experiment results to file\"\"\"\n    import json\n    from datetime import datetime\n    \n    # Add timestamp\n    results['timestamp'] = datetime.now().isoformat()\n    results['experiment_info'] = {\n        'framework': 'MC-Planner Migration',\n        'environment': 'Gymnasium',\n        'version': '0.1.0'\n    }\n    \n    output_path = Path(output_path)\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n    \n    with open(output_path, 'w') as f:\n        json.dump(results, f, indent=2)\n    \n    print(f\"Results saved to: {output_path}\")\n\n\ndef load_experiment_config(config_path: str) -> Dict[str, Any]:\n    \"\"\"Load experiment configuration\"\"\"\n    import yaml\n    \n    config_path = Path(config_path)\n    if not config_path.exists():\n        raise FileNotFoundError(f\"Config file not found: {config_path}\")\n    \n    with open(config_path, 'r') as f:\n        config = yaml.safe_load(f)\n    \n    return config\n"},{"path":"diffu_moe_vlm/wandb_integration.py","text":"\"\"\"\nWeights & Biases Integration for MineDojo-style Benchmarking\nProvides comprehensive logging and visualization for Diffu_MoE_VLM experiments\n\"\"\"\n\nimport os\nimport time\nimport wandb\nimport numpy as np\nfrom typing import Dict, List, Any, Optional, Union\nfrom pathlib import Path\nfrom .benchmark_metrics import BenchmarkMetrics, TaskResult, EpisodeMetrics, BenchmarkSuite\n\n\nclass WandBLogger:\n    \"\"\"\n    Weights & Biases logger for MineDojo-style benchmarking\n    \"\"\"\n    \n    def __init__(self, \n                 project_name: str = \"diffu-moe-vlm-minecraft\",\n                 experiment_name: Optional[str] = None,\n                 config: Optional[Dict] = None,\n                 tags: Optional[List[str]] = None,\n                 notes: Optional[str] = None,\n                 enabled: bool = True):\n        \n        self.enabled = enabled\n        self.project_name = project_name\n        self.experiment_name = experiment_name or f\"experiment_{int(time.time())}\"\n        \n        if not self.enabled:\n            print(\"[WandB] Logging disabled\")\n            return\n        \n        # Initialize WandB\n        try:\n            wandb.init(\n                project=project_name,\n                name=self.experiment_name,\n                config=config or {},\n                tags=tags or [],\n                notes=notes\n            )\n            \n            # Define custom metrics\n            self._define_custom_metrics()\n            print(f\"[WandB] Initialized project: {project_name}, experiment: {self.experiment_name}\")\n            \n        except Exception as e:\n            print(f\"[WandB] Failed to initialize: {e}\")\n            self.enabled = False\n    \n    def _define_custom_metrics(self):\n        \"\"\"Define custom metrics for MineDojo benchmarking\"\"\"\n        if not self.enabled:\n            return\n            \n        # Define step-based metrics\n        wandb.define_metric(\"episode/step\")\n        wandb.define_metric(\"episode/*\", step_metric=\"episode/step\")\n        \n        # Define task-based metrics\n        wandb.define_metric(\"task/index\")\n        wandb.define_metric(\"task/*\", step_metric=\"task/index\")\n        \n        # Define benchmark suite metrics\n        wandb.define_metric(\"benchmark/task_count\")\n        wandb.define_metric(\"benchmark/*\", step_metric=\"benchmark/task_count\")\n    \n    def log_config(self, config: Dict):\n        \"\"\"Log experiment configuration\"\"\"\n        if not self.enabled:\n            return\n            \n        wandb.config.update(config)\n    \n    def log_step_metrics(self, \n                        step: int,\n                        reward: float,\n                        action: Dict,\n                        inventory: Dict,\n                        obs: Dict,\n                        info: Dict,\n                        planning_time: Optional[float] = None):\n        \"\"\"Log metrics for each environment step\"\"\"\n        if not self.enabled:\n            return\n        \n        metrics = {\n            \"episode/step\": step,\n            \"episode/reward\": reward,\n            \"episode/cumulative_reward\": wandb.run.summary.get(\"episode/cumulative_reward\", 0) + reward,\n            \"episode/inventory_size\": len(inventory),\n            \"episode/inventory_diversity\": len(set(inventory.keys())),\n        }\n        \n        # Log action distribution\n        for action_name, action_value in action.items():\n            if isinstance(action_value, (int, float)):\n                metrics[f\"action/{action_name}\"] = action_value\n        \n        # Log inventory details\n        for item, count in inventory.items():\n            metrics[f\"inventory/{item}\"] = count\n        \n        # Log observation statistics\n        if \"rgb\" in obs:\n            rgb = obs[\"rgb\"]\n            if isinstance(rgb, np.ndarray):\n                metrics.update({\n                    \"obs/rgb_mean\": np.mean(rgb),\n                    \"obs/rgb_std\": np.std(rgb),\n                })\n        \n        # Log life stats\n        life_stats = info.get(\"life_stats\", {})\n        for stat_name, stat_value in life_stats.items():\n            if isinstance(stat_value, (int, float)):\n                metrics[f\"life/{stat_name}\"] = stat_value\n        \n        # Log location stats\n        location_stats = info.get(\"location_stats\", {})\n        if \"pos\" in location_stats:\n            pos = location_stats[\"pos\"]\n            if len(pos) >= 3:\n                metrics.update({\n                    \"location/x\": pos[0],\n                    \"location/y\": pos[1],\n                    \"location/z\": pos[2],\n                    \"location/distance_from_origin\": np.sqrt(sum(p**2 for p in pos))\n                })\n        \n        # Log planning metrics\n        if planning_time is not None:\n            metrics[\"planning/time_seconds\"] = planning_time\n        \n        wandb.log(metrics)\n    \n    def log_episode_metrics(self, episode_metrics: EpisodeMetrics, task_id: str):\n        \"\"\"Log comprehensive episode metrics\"\"\"\n        if not self.enabled:\n            return\n        \n        episode_duration = episode_metrics.end_time - episode_metrics.start_time\n        \n        metrics = {\n            \"episode/duration_seconds\": episode_duration,\n            \"episode/total_steps\": episode_metrics.total_steps,\n            \"episode/total_reward\": episode_metrics.total_reward,\n            \"episode/success\": int(episode_metrics.success),\n            \"episode/inventory_diversity\": episode_metrics.inventory_diversity,\n            \"episode/crafting_events\": episode_metrics.crafting_events,\n            \"episode/mining_events\": episode_metrics.mining_events,\n            \"episode/exploration_area\": episode_metrics.exploration_area,\n            \"episode/planning_time\": episode_metrics.planning_time,\n            \"episode/replanning_count\": episode_metrics.replanning_count,\n            \"episode/goal_completion_rate\": episode_metrics.goal_completion_rate,\n            \"episode/actions_per_second\": episode_metrics.actions_per_second,\n            \"episode/reward_per_step\": episode_metrics.reward_per_step,\n            \"episode/task_id\": task_id,\n        }\n        \n        if episode_metrics.time_to_first_success is not None:\n            metrics[\"episode/time_to_first_success\"] = episode_metrics.time_to_first_success\n        \n        wandb.log(metrics)\n        \n        # Log episode summary to wandb.run.summary for tracking across episodes\n        wandb.run.summary.update({\n            \"latest_episode_success\": episode_metrics.success,\n            \"latest_episode_reward\": episode_metrics.total_reward,\n            \"latest_episode_steps\": episode_metrics.total_steps,\n            \"total_episodes\": wandb.run.summary.get(\"total_episodes\", 0) + 1\n        })\n    \n    def log_task_result(self, task_result: TaskResult, task_index: int):\n        \"\"\"Log individual task results\"\"\"\n        if not self.enabled:\n            return\n        \n        metrics = {\n            \"task/index\": task_index,\n            \"task/success\": int(task_result.success),\n            \"task/completion_time\": task_result.completion_time,\n            \"task/total_steps\": task_result.total_steps,\n            \"task/reward\": task_result.reward,\n            \"task/completion_percentage\": task_result.completion_percentage,\n            \"task/efficiency_score\": task_result.efficiency_score,\n            \"task/planning_iterations\": task_result.planning_iterations,\n            \"task/goal_changes\": task_result.goal_changes,\n            \"task/type\": task_result.task_type,\n            \"task/category\": self._get_task_category(task_result.task_id),\n        }\n        \n        # Log final inventory diversity\n        metrics[\"task/final_inventory_diversity\"] = len(task_result.final_inventory)\n        \n        # Log specific inventory items\n        for item, count in task_result.final_inventory.items():\n            metrics[f\"task/final_inventory/{item}\"] = count\n        \n        wandb.log(metrics)\n        \n        # Update task-level summaries\n        wandb.run.summary.update({\n            f\"tasks/{task_result.task_type}_success_rate\": self._calculate_category_success_rate(task_result.task_type),\n            \"tasks/total_completed\": wandb.run.summary.get(\"tasks/total_completed\", 0) + 1,\n            \"tasks/total_successful\": wandb.run.summary.get(\"tasks/total_successful\", 0) + (1 if task_result.success else 0)\n        })\n    \n    def log_benchmark_summary(self, benchmark_suite: BenchmarkSuite):\n        \"\"\"Log comprehensive benchmark suite results\"\"\"\n        if not self.enabled:\n            return\n        \n        suite_duration = benchmark_suite.end_time - benchmark_suite.start_time\n        \n        # Main benchmark metrics\n        metrics = {\n            \"benchmark/total_tasks\": benchmark_suite.total_tasks,\n            \"benchmark/successful_tasks\": benchmark_suite.successful_tasks,\n            \"benchmark/overall_success_rate\": benchmark_suite.overall_success_rate,\n            \"benchmark/average_completion_time\": benchmark_suite.average_completion_time,\n            \"benchmark/average_steps_per_task\": benchmark_suite.average_steps_per_task,\n            \"benchmark/average_reward\": benchmark_suite.average_reward,\n            \"benchmark/suite_duration\": suite_duration,\n        }\n        \n        # Category-specific metrics\n        for category, results in [\n            (\"programmatic\", benchmark_suite.programmatic_results),\n            (\"creative\", benchmark_suite.creative_results),\n            (\"playthrough\", benchmark_suite.playthrough_results)\n        ]:\n            if results:\n                success_rate = sum(1 for r in results if r.success) / len(results) * 100\n                avg_steps = np.mean([r.total_steps for r in results])\n                avg_reward = np.mean([r.reward for r in results])\n                \n                metrics.update({\n                    f\"benchmark/{category}_tasks\": len(results),\n                    f\"benchmark/{category}_success_rate\": success_rate,\n                    f\"benchmark/{category}_avg_steps\": avg_steps,\n                    f\"benchmark/{category}_avg_reward\": avg_reward,\n                })\n        \n        # Tech tree progression\n        for item, obtained in benchmark_suite.tech_tree_progression.items():\n            metrics[f\"tech_tree/{item}\"] = int(obtained)\n        \n        # Survival metrics\n        for metric, value in benchmark_suite.survival_metrics.items():\n            metrics[f\"survival/{metric}\"] = value\n        \n        # Combat metrics\n        for metric, value in benchmark_suite.combat_metrics.items():\n            metrics[f\"combat/{metric}\"] = value\n        \n        wandb.log(metrics)\n        \n        # Update final summary\n        wandb.run.summary.update({\n            \"final/overall_success_rate\": benchmark_suite.overall_success_rate,\n            \"final/total_tasks\": benchmark_suite.total_tasks,\n            \"final/successful_tasks\": benchmark_suite.successful_tasks,\n            \"final/suite_duration\": suite_duration,\n        })\n    \n    def log_planning_metrics(self, \n                           plan: str,\n                           goal_list: List[str],\n                           selected_goal: Optional[str] = None,\n                           planning_time: float = 0.0,\n                           is_replanning: bool = False):\n        \"\"\"Log planning-specific metrics\"\"\"\n        if not self.enabled:\n            return\n        \n        metrics = {\n            \"planning/time_seconds\": planning_time,\n            \"planning/goal_list_size\": len(goal_list),\n            \"planning/is_replanning\": int(is_replanning),\n        }\n        \n        if selected_goal:\n            metrics[\"planning/selected_goal\"] = selected_goal\n        \n        wandb.log(metrics)\n        \n        # Log plan and goals as text\n        wandb.log({\n            \"planning/plan_text\": wandb.Html(f\"<p><strong>Plan:</strong> {plan}</p>\"),\n            \"planning/goals\": wandb.Html(f\"<ul>{''.join(f'<li>{goal}</li>' for goal in goal_list)}</ul>\")\n        })\n    \n    def log_media(self, \n                  step: int,\n                  rgb_obs: Optional[np.ndarray] = None,\n                  video_path: Optional[str] = None,\n                  caption: Optional[str] = None):\n        \"\"\"Log images and videos\"\"\"\n        if not self.enabled:\n            return\n        \n        media_dict = {}\n        \n        if rgb_obs is not None:\n            media_dict[\"obs/rgb_image\"] = wandb.Image(\n                rgb_obs, \n                caption=caption or f\"Step {step}\"\n            )\n        \n        if video_path and Path(video_path).exists():\n            media_dict[\"episode/video\"] = wandb.Video(\n                video_path,\n                caption=caption or \"Episode recording\"\n            )\n        \n        if media_dict:\n            wandb.log(media_dict, step=step)\n    \n    def log_histogram(self, name: str, data: List[float], step: Optional[int] = None):\n        \"\"\"Log histogram data\"\"\"\n        if not self.enabled or not data:\n            return\n        \n        wandb.log({\n            name: wandb.Histogram(data)\n        }, step=step)\n    \n    def log_table(self, name: str, columns: List[str], data: List[List[Any]]):\n        \"\"\"Log table data\"\"\"\n        if not self.enabled:\n            return\n        \n        table = wandb.Table(columns=columns, data=data)\n        wandb.log({name: table})\n    \n    def log(self, metrics: Dict[str, Any]):\n        \"\"\"Log arbitrary metrics (no-op when disabled)\"\"\"\n        if not self.enabled:\n            return\n        wandb.log(metrics)\n    \n    def log_artifact(self, file_path: str, artifact_name: str, artifact_type: str = \"dataset\"):\n        \"\"\"Log artifacts (datasets, models, etc.)\"\"\"\n        if not self.enabled:\n            return\n        \n        artifact = wandb.Artifact(artifact_name, type=artifact_type)\n        artifact.add_file(file_path)\n        wandb.log_artifact(artifact)\n    \n    def _get_task_category(self, task_id: str) -> str:\n        \"\"\"Get task category for logging\"\"\"\n        from .benchmark_metrics import MinecraftTaskCategories\n        return MinecraftTaskCategories.get_task_category(task_id)\n    \n    def _calculate_category_success_rate(self, task_type: str) -> float:\n        \"\"\"Calculate success rate for a specific task category\"\"\"\n        # This would need access to all previous results\n        # For now, return current session success rate from wandb.run.summary\n        total_key = f\"tasks/{task_type}_total\"\n        success_key = f\"tasks/{task_type}_successful\"\n        \n        total = wandb.run.summary.get(total_key, 0)\n        successful = wandb.run.summary.get(success_key, 0)\n        \n        return (successful / max(total, 1)) * 100\n    \n    def finish(self):\n        \"\"\"Finish WandB logging\"\"\"\n        if self.enabled:\n            wandb.finish()\n            print(\"[WandB] Logging finished\")\n\n\nclass WandBIntegratedBenchmark:\n    \"\"\"\n    Integration of BenchmarkMetrics with WandB logging\n    \"\"\"\n    \n    def __init__(self, \n                 benchmark_metrics: BenchmarkMetrics,\n                 wandb_logger: WandBLogger):\n        self.benchmark_metrics = benchmark_metrics\n        self.wandb_logger = wandb_logger\n        self.current_task_index = 0\n    \n    def start_episode(self, episode_id: str, task_id: str):\n        \"\"\"Start episode with both benchmark and WandB tracking\"\"\"\n        self.benchmark_metrics.start_episode(episode_id, task_id)\n        \n        # Log episode start to WandB\n        self.wandb_logger.log_step_metrics(\n            step=0,\n            reward=0.0,\n            action={},\n            inventory={},\n            obs={},\n            info={}\n        )\n    \n    def log_step(self, \n                obs: Dict,\n                action: Dict,\n                reward: float,\n                info: Dict,\n                planning_time: Optional[float] = None):\n        \"\"\"Log step to both systems\"\"\"\n        # Update benchmark metrics\n        self.benchmark_metrics.update_step_metrics(obs, action, reward, info)\n        \n        # Log to WandB\n        inventory = info.get('inventory', {})\n        step = self.benchmark_metrics.current_episode_metrics.total_steps if self.benchmark_metrics.current_episode_metrics else 0\n        \n        self.wandb_logger.log_step_metrics(\n            step=step,\n            reward=reward,\n            action=action,\n            inventory=inventory,\n            obs=obs,\n            info=info,\n            planning_time=planning_time\n        )\n    \n    def log_planning(self, \n                    plan: str,\n                    goal_list: List[str],\n                    selected_goal: Optional[str] = None,\n                    planning_time: float = 0.0,\n                    is_replanning: bool = False):\n        \"\"\"Log planning information\"\"\"\n        # Update benchmark metrics\n        self.benchmark_metrics.update_planning_metrics(planning_time, is_replanning)\n        \n        # Log to WandB\n        self.wandb_logger.log_planning_metrics(\n            plan=plan,\n            goal_list=goal_list,\n            selected_goal=selected_goal,\n            planning_time=planning_time,\n            is_replanning=is_replanning\n        )\n    \n    def end_episode(self, success: bool, final_inventory: Dict, task_id: str):\n        \"\"\"End episode with both systems\"\"\"\n        # End benchmark episode\n        episode_metrics = self.benchmark_metrics.end_episode(success, final_inventory)\n        \n        # Log to WandB\n        self.wandb_logger.log_episode_metrics(episode_metrics, task_id)\n        \n        return episode_metrics\n    \n    def complete_task(self, \n                     task_id: str,\n                     success: bool,\n                     completion_time: float,\n                     total_steps: int,\n                     total_reward: float,\n                     final_inventory: Dict,\n                     planning_iterations: int = 0,\n                     goal_changes: int = 0,\n                     error_message: Optional[str] = None):\n        \"\"\"Complete task evaluation with both systems\"\"\"\n        # Evaluate task with benchmark metrics\n        task_result = self.benchmark_metrics.evaluate_task(\n            task_id=task_id,\n            success=success,\n            completion_time=completion_time,\n            total_steps=total_steps,\n            total_reward=total_reward,\n            final_inventory=final_inventory,\n            planning_iterations=planning_iterations,\n            goal_changes=goal_changes,\n            error_message=error_message\n        )\n        \n        # Log to WandB\n        self.wandb_logger.log_task_result(task_result, self.current_task_index)\n        self.current_task_index += 1\n        \n        return task_result\n    \n    def finish_benchmark(self):\n        \"\"\"Finish benchmark suite and log final results\"\"\"\n        # Compute benchmark summary\n        benchmark_suite = self.benchmark_metrics.compute_benchmark_summary()\n        \n        # Log to WandB\n        self.wandb_logger.log_benchmark_summary(benchmark_suite)\n        \n        # Save benchmark results\n        results_path = self.benchmark_metrics.save_results()\n        \n        # Log results file as artifact\n        self.wandb_logger.log_artifact(\n            str(results_path),\n            \"benchmark_results\",\n            \"results\"\n        )\n        \n        # Print summary\n        self.benchmark_metrics.print_summary()\n        \n        # Finish WandB\n        self.wandb_logger.finish()\n        \n        return benchmark_suite\n"},{"path":"evaluate_policy.py","text":"\"\"\"\nEvaluate a policy on Crafter and report achievement success rates and score.\n\n    python evaluate_policy.py policy=random\n    python evaluate_policy.py policy=runs/ppo/checkpoint.pt episodes=50\n    python evaluate_policy.py policy=runs/diffusion/checkpoint.pt\n\"\"\"\n\nfrom pathlib import Path\n\nimport hydra\n\nfrom diffu_moe_vlm.crafter_env import CRAFTER_ACTIONS, format_achievements\nfrom diffu_moe_vlm.rl.checkpoint import load_policy\nfrom diffu_moe_vlm.rl.common import make_crafter_envs, resolve_device, seed_everything, write_json\nfrom diffu_moe_vlm.rl.rollout import ActorCriticRunner, DiffusionRunner, RandomRunner, evaluate\n\n\n@hydra.main(config_path=\"configs\", config_name=\"eval_policy\", version_base=None)\ndef main(cfg) -> None:\n    seed_everything(cfg.seed, cfg.get(\"torch_threads\"))\n    device = resolve_device(cfg.device)\n    num_actions = len(CRAFTER_ACTIONS)\n    if cfg.policy == 'random':\n        runner = RandomRunner(num_actions, cfg.seed)\n    else:\n        model, ckpt = load_policy(cfg.policy, num_actions, device, cfg.env.size)\n        if ckpt['kind'] == 'ppo':\n            runner = ActorCriticRunner(model, device, deterministic=cfg.deterministic)\n        else:\n            runner = DiffusionRunner(model, device, cfg.execute_steps, cfg.sample_steps)\n\n    envs = make_crafter_envs(cfg.num_envs, cfg.seed, cfg.env.size, cfg.env.length, cfg.env.num_workers)\n    try:\n        result = evaluate(runner, envs, cfg.episodes)\n    finally:\n        envs.close()\n    summary = result.summary()\n    out = Path(cfg.output_dir) / 'eval.json'\n    write_json(out, {'policy': str(cfg.policy), **summary})\n    print(f\"[Eval] policy={cfg.policy} episodes={summary['episodes']} return={summary['return_mean']:.2f} \"\n          f\"length={summary['length_mean']:.0f} score={summary['score']:.2f}\")\n    print(\"[Eval] \" + format_achievements(result.success_rates()))\n    print(f\"[Eval] saved {out}\")\n\n\nif __name__ == '__main__':\n    main()\n"},{"path":"main.py","text":"\"\"\"\nMC-Planner main entry point (Hydra).\n\n    python main.py                                   # all tasks\n    python main.py eval.single_task=true eval.task_name=obtain_stone_pickaxe\n\"\"\"\n\nimport json\nimport warnings\nfrom pathlib import Path\n\nimport hydra\nfrom omegaconf import OmegaConf\n\nfrom diffu_moe_vlm.evaluator import Evaluator\n\nwarnings.filterwarnings('ignore')\n\n\n@hydra.main(config_path=\"configs\", config_name=\"defaults\", version_base=None)\ndef main(cfg: OmegaConf) -> None:\n    \"\"\"Main entry point\"\"\"\n    print(\"Starting MC-Planner evaluation...\")\n    print(f\"Configuration: {OmegaConf.to_yaml(cfg)}\")\n    \n    # Initialize evaluator\n    evaluator = Evaluator(cfg)\n    \n    try:\n        # Run evaluation\n        # Evaluation options live under `eval`; top-level keys are kept for backward compatibility\n        eval_cfg = cfg.get('eval', {})\n        single_task = eval_cfg.get('single_task') or cfg.get('single_task', False)\n        if single_task:\n            # Run single task\n            task = cfg.get('task_name') or eval_cfg.get('task_name') or evaluator.task_list[0]\n            result = evaluator.single_task_evaluate(task)\n            \n            # Save single task result\n            output_file = Path(cfg.get('output_dir', '.')) / f'result_{task}.json'\n            output_file.parent.mkdir(parents=True, exist_ok=True)\n            with open(output_file, 'w') as f:\n                json.dump(result, f, indent=2)\n            \n            print(f\"Single task result saved to {output_file}\")\n            \n        else:\n            # Run all tasks\n            results = evaluator.run_all_tasks()\n            \n            # Save results\n            output_file = Path(cfg.get('output_dir', '.')) / 'results.json'\n            output_file.parent.mkdir(parents=True, exist_ok=True)\n            with open(output_file, 'w') as f:\n                json.dump(results, f, indent=2)\n            \n            print(f\"Results saved to {output_file}\")\n            \n            # Log results file as WandB artifact\n            evaluator.wandb_logger.log_artifact(\n                str(output_file),\n                \"final_results\",\n                \"results\"\n            )\n    \n    except Exception as e:\n        print(f\"[Error] Evaluation failed: {e}\")\n        \n        # Log error to WandB\n        if hasattr(evaluator, 'wandb_logger') and evaluator.wandb_logger.enabled:\n            evaluator.wandb_logger.log({\n                \"errors/fatal_error\": str(e),\n                \"errors/evaluation_failed\": True\n            })\n        \n        raise e\n    \n    finally:\n        # Ensure WandB is properly closed\n        if hasattr(evaluator, 'wandb_logger') and evaluator.wandb_logger.enabled:\n            evaluator.wandb_logger.finish()\n            print(\"[WandB] Logging session finished\")\n\n\nif __name__ == '__main__':\n    main()\n"},{"path":"pyproject.toml","text":"[build-system]\nrequires = [\"setuptools>=61\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"diffu-moe-vlm\"\nversion = \"0.2.0\"\ndescription = \"LLM planning agent in the Describe, Explain, Plan and Select style on a symbolic Minecraft tech tree\"\nreadme = \"README.md\"\nrequires-python = \">=3.9\"\ndependencies = [\n    \"numpy>=1.21.0\",\n    \"gymnasium>=0.29.0\",\n    \"opencv-python>=4.5.0\",\n    \"omegaconf>=2.2.0\",\n    \"hydra-core>=1.2.0\",\n    \"pyyaml>=6.0\",\n    \"requests>=2.28.0\",\n    \"wandb>=0.15.0\",\n]\n\n[project.optional-dependencies]\nml = [\"torch>=2.0.0\", \"transformers>=4.20.0\", \"pillow>=9.0.0\"]\nrl = [\"torch>=2.0.0\", \"crafter>=1.8.0\"]\n# Craftax in JAX; for GPUs install a CUDA build of jax, e.g. pip install -U \"jax[cuda12]\"\njax = [\"jax>=0.4.30\", \"flax>=0.8.0\", \"optax>=0.2.0\", \"distrax>=0.1.5\", \"craftax>=1.4.0\"]\ndev = [\"pytest>=7.0.0\", \"black>=22.0.0\", \"flake8>=5.0.0\"]\n\n[tool.setuptools.packages.find]\ninclude = [\"diffu_moe_vlm*\"]\n\n[tool.setuptools.package-data]\ndiffu_moe_vlm = [\"data/*.json\", \"data/*.txt\"]\n\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\n"},{"path":"run_benchmark.py","text":"#!/usr/bin/env python3\n\"\"\"\nQuick Start Script for MineDojo-style Benchmarking\nUsage: python run_benchmark.py [--config CONFIG] [--task TASK] [--no-wandb]\n\"\"\"\n\nimport argparse\nimport sys\nfrom pathlib import Path\nimport hydra\nfrom omegaconf import OmegaConf\n\n# Add project root to path\nsys.path.append(str(Path(__file__).parent))\n\nfrom main import main\n\n\ndef parse_args():\n    \"\"\"Parse command line arguments\"\"\"\n    parser = argparse.ArgumentParser(\n        description=\"Run MineDojo-style benchmarking for Diffu_MoE_VLM\"\n    )\n    \n    parser.add_argument(\n        \"--config\", \n        type=str, \n        default=\"benchmark\",\n        help=\"Configuration file name (default: benchmark)\"\n    )\n    \n    parser.add_argument(\n        \"--task\",\n        type=str,\n        default=None,\n        help=\"Single task to run (if not specified, runs all tasks)\"\n    )\n    \n    parser.add_argument(\n        \"--no-wandb\",\n        action=\"store_true\",\n        help=\"Disable WandB logging\"\n    )\n    \n    parser.add_argument(\n        \"--experiment-name\",\n        type=str,\n        default=None,\n        help=\"Name for this experiment\"\n    )\n    \n    parser.add_argument(\n        \"--tags\",\n        nargs=\"+\",\n        default=None,\n        help=\"Tags for WandB logging\"\n    )\n    \n    parser.add_argument(\n        \"--notes\",\n        type=str,\n        default=None,\n        help=\"Notes for this experiment\"\n    )\n    \n    parser.add_argument(\n        \"--output-dir\",\n        type=str,\n        default=None,\n        help=\"Output directory for results\"\n    )\n    \n    parser.add_argument(\n        \"--dry-run\",\n        action=\"store_true\",\n        help=\"Test configuration without running evaluation\"\n    )\n    \n    return parser.parse_args()\n\n\ndef run_benchmark_with_args(args):\n    \"\"\"Run benchmark with command line arguments\"\"\"\n    \n    # Build Hydra overrides\n    overrides = []\n    \n    if args.task:\n        overrides.extend([\n            \"eval.single_task=true\",\n            f\"eval.task_name={args.task}\"\n        ])\n    \n    if args.no_wandb:\n        overrides.append(\"wandb.enabled=false\")\n    \n    if args.experiment_name:\n        overrides.append(f\"experiment_name={args.experiment_name}\")\n    \n    if args.output_dir:\n        overrides.append(f\"output.base_dir={args.output_dir}\")\n    \n    if args.tags:\n        tag_str = \"[\" + \",\".join(f'\"{tag}\"' for tag in args.tags) + \"]\"\n        overrides.append(f\"wandb.tags={tag_str}\")\n    \n    if args.notes:\n        overrides.append(f'wandb.notes=\"{args.notes}\"')\n    \n    # Set config name\n    config_name = args.config\n    \n    if args.dry_run:\n        print(\"DRY RUN MODE - Configuration Preview:\")\n        print(\"=\" * 50)\n        print(f\"Config: {config_name}\")\n        print(f\"Overrides: {overrides}\")\n        \n        # Load and display config\n        from hydra import initialize, compose\n        \n        with initialize(config_path=\"configs\", version_base=None):\n            cfg = compose(config_name=config_name, overrides=overrides)\n            print(\"Final Configuration:\")\n            print(OmegaConf.to_yaml(cfg))\n        \n        return\n    \n    # Create temporary Hydra config\n    @hydra.main(config_path=\"configs\", config_name=config_name, version_base=None)\n    def hydra_main(cfg):\n        return main(cfg)\n    \n    # Override sys.argv for Hydra\n    original_argv = sys.argv.copy()\n    sys.argv = [sys.argv[0]] + overrides\n    \n    try:\n        result = hydra_main()\n        return result\n    finally:\n        sys.argv = original_argv\n\n\ndef quick_examples():\n    \"\"\"Print quick usage examples\"\"\"\n    print(\"Quick Start Examples:\")\n    print(\"=\" * 50)\n    print()\n    print(\"1. Run full benchmark suite:\")\n    print(\"   python run_benchmark.py\")\n    print()\n    print(\"2. Run single task:\")\n    print(\"   python run_benchmark.py --task obtain_wooden_slab\")\n    print()\n    print(\"3. Run without WandB logging:\")\n    print(\"   python run_benchmark.py --no-wandb\")\n    print()\n    print(\"4. Custom experiment:\")\n    print(\"   python run_benchmark.py --experiment-name my_experiment --tags test baseline\")\n    print()\n    print(\"5. Test configuration:\")\n    print(\"   python run_benchmark.py --dry-run\")\n    print()\n    print(\"6. Creative tasks only:\")\n    print(\"   python run_benchmark.py --config creative_benchmark\")\n    print()\n\n\ndef main_cli():\n    \"\"\"Main CLI entry point\"\"\"\n    args = parse_args()\n    \n    if len(sys.argv) == 1:\n        print(\"MineDojo-style Benchmarking for Diffu_MoE_VLM\")\n        print(\"=\" * 50)\n        quick_examples()\n        return\n    \n    print(\"Starting MineDojo-style Benchmarking...\")\n    print(f\"Configuration: {args.config}\")\n    print(f\"Single task: {args.task or 'All tasks'}\")\n    print(f\"WandB enabled: {not args.no_wandb}\")\n    print()\n    \n    try:\n        result = run_benchmark_with_args(args)\n        \n        if not args.dry_run:\n            print()\n            print(\"Benchmarking completed successfully!\")\n            if result:\n                print(f\"Results: {result}\")\n    \n    except KeyboardInterrupt:\n        print(\"\\nBenchmarking interrupted by user\")\n        sys.exit(1)\n    \n    except Exception as e:\n        print(f\"\\nError during benchmarking: {e}\")\n        sys.exit(1)\n\n\nif __name__ == \"__main__\":\n    main_cli()\n"},{"path":"run_icm_ablation.py","text":"\"\"\"\nDoes moving-mean normalization of the ICM bonus stop the intrinsic reward from\nrunning away, and does it actually improve exploration?\n\nRuns the same Craftax PPO with one change per arm (train_craftax.py underneath),\nthen compares the arms with analyze_icm_ablation.py:\n\n    ppo        no curiosity bonus (baseline)\n    icm_none   raw forward-model error           (expected: bonus runs away)\n    icm_std    error / running std               (expected: still too large)\n    icm_mean   error / running mean   (default)  (claim: bounded, explores more)\n    icm_ema    error / exponential moving mean   (follows a shrinking error)\n\nAll ICM arms use the same icm_reward_coef, so only the normalization differs.\n\nGPU (the experiment; ~3-4 h per 1e9-step run on one GPU, 5 arms x 3 seeds):\n    python run_icm_ablation.py\n    python run_icm_ablation.py --steps 2e8 --arms ppo icm_mean icm_std   # shorter screen\n\nCPU (debugging only: tiny envs/network, a few updates; checks that every arm\nruns, logs the icm/* and exploration metrics and that the analysis works.\nIts numbers say nothing about the hypothesis):\n    python run_icm_ablation.py --preset cpu-debug\n\nRuns are resumable: re-running the same command skips finished runs and resumes\ninterrupted ones from their checkpoints. Use --dry-run to print the commands.\n\"\"\"\n\nimport argparse\nimport json\nimport os\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\n\nARMS = {\n    \"ppo\": {\"algo.icm\": \"false\"},\n    \"icm_none\": {\"algo.icm\": \"true\", \"algo.icm_normalize\": \"none\"},\n    \"icm_std\": {\"algo.icm\": \"true\", \"algo.icm_normalize\": \"std\"},\n    \"icm_mean\": {\"algo.icm\": \"true\", \"algo.icm_normalize\": \"mean\"},\n    \"icm_ema\": {\"algo.icm\": \"true\", \"algo.icm_normalize\": \"ema\"},\n}\n\nPRESETS = {\n    # Full Craftax baseline config (configs/train_craftax.yaml) on an accelerator\n    \"gpu\": {\"steps\": 1e9, \"seeds\": [0, 1, 2], \"overrides\": {\"log_every\": 10, \"checkpoint_every\": 50}},\n    # Small enough to finish in minutes on a laptop CPU; for debugging the pipeline only\n    \"cpu-debug\": {\"steps\": 32 * 16 * 12, \"seeds\": [0], \"env\": {\"JAX_PLATFORMS\": \"cpu\"}, \"overrides\": {\n        \"algo.num_envs\": 32, \"algo.num_steps\": 16, \"algo.num_minibatches\": 2, \"algo.update_epochs\": 1,\n        \"algo.layer_size\": 64, \"algo.num_layers\": 2, \"algo.reset_ratio\": 4,\n        \"log_every\": 1, \"checkpoint_every\": 6}},\n}\n\n\ndef build_runs(preset: str, arms, seeds, steps: float, out: Path, extra=()):\n    p = PRESETS[preset]\n    runs = []\n    for arm in arms:\n        for seed in seeds:\n            run_dir = out / arm / f\"seed{seed}\"\n            overrides = {**p[\"overrides\"], **ARMS[arm], \"seed\": seed, \"algo.total_timesteps\": int(steps),\n                         \"output_dir\": str(run_dir), \"name\": f\"{arm}-seed{seed}\"}\n            cmd = [sys.executable, str(HERE / \"train_craftax.py\")] + [f\"{k}={v}\" for k, v in overrides.items()]\n            runs.append({\"arm\": arm, \"seed\": seed, \"dir\": run_dir, \"cmd\": cmd + list(extra)})\n    return runs\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    parser.add_argument(\"--preset\", choices=sorted(PRESETS), default=\"gpu\")\n    parser.add_argument(\"--arms\", nargs=\"+\", choices=list(ARMS), default=list(ARMS))\n    parser.add_argument(\"--seeds\", nargs=\"+\", type=int, help=\"default: preset seeds\")\n    parser.add_argument(\"--steps\", type=float, help=\"env steps per run (default: preset)\")\n    parser.add_argument(\"--out\", default=None, help=\"default: runs/icm_ablation[_cpu_debug]\")\n    parser.add_argument(\"--wandb\", action=\"store_true\", help=\"also log every run to Weights & Biases\")\n    parser.add_argument(\"--dry-run\", action=\"store_true\")\n    parser.add_argument(\"--no-analysis\", action=\"store_true\")\n    args = parser.parse_args()\n\n    p = PRESETS[args.preset]\n    out = Path(args.out or (\"runs/icm_ablation\" if args.preset == \"gpu\" else \"runs/icm_ablation_cpu_debug\"))\n    seeds = args.seeds or p[\"seeds\"]\n    steps = args.steps or p[\"steps\"]\n    extra = [\"wandb.enabled=true\", \"wandb.project=Craftax_ICM_ablation\"] if args.wandb else []\n    runs = build_runs(args.preset, args.arms, seeds, steps, out, extra)\n    env = {**os.environ, **p.get(\"env\", {})}\n    print(f\"[icm-ablation] preset={args.preset} arms={args.arms} seeds={seeds} steps={steps:.3g} -> {out}\")\n    if args.preset == \"cpu-debug\":\n        print(\"[icm-ablation] CPU debug preset: checks the pipeline only; results do not test the hypothesis\")\n\n    for i, run in enumerate(runs, 1):\n        tag = f\"[{i}/{len(runs)}] {run['arm']} seed {run['seed']}\"\n        if (run[\"dir\"] / \"summary.json\").exists():\n            print(f\"{tag}: finished, skipping\")\n            continue\n        print(f\"{tag}: {' '.join(run['cmd'][1:])}\", flush=True)\n        if not args.dry_run:\n            subprocess.run(run[\"cmd\"], cwd=HERE, env=env, check=True)\n\n    if args.dry_run or args.no_analysis:\n        return\n    from analyze_icm_ablation import analyze, write_report\n    result = analyze(out, args.arms)\n    report = write_report(result, out, debug=args.preset == \"cpu-debug\")\n    print(report)\n    print(f\"[icm-ablation] report: {out / 'report.md'}, data: {out / 'summary.json'}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"test_benchmarking.py","text":"#!/usr/bin/env python3\n\"\"\"\nTest script for MineDojo-style benchmarking integration\nValidates the benchmarking and WandB logging systems\n\"\"\"\n\nimport os\nimport sys\nimport time\nimport numpy as np\nfrom pathlib import Path\n\n# Add project root to path\nsys.path.append(str(Path(__file__).parent))\n\nfrom diffu_moe_vlm.benchmark_metrics import BenchmarkMetrics, TaskResult, EpisodeMetrics\nfrom diffu_moe_vlm.wandb_integration import WandBLogger, WandBIntegratedBenchmark\nfrom diffu_moe_vlm.minedojo_tasks import TaskRegistry, create_task_adapter\n\n\ndef test_benchmark_metrics():\n    \"\"\"Test the benchmark metrics system\"\"\"\n    print(\"Testing Benchmark Metrics System...\")\n    \n    # Initialize benchmark metrics\n    benchmark = BenchmarkMetrics(\"./test_benchmark_results\")\n    \n    # Test episode tracking\n    benchmark.start_episode(\"test_episode_1\", \"obtain_wooden_slab\")\n    \n    # Simulate some steps\n    for step in range(10):\n        obs = {\"rgb\": np.random.rand(64, 64, 3)}\n        action = {\"movement\": 1, \"camera\": [0.1, 0.0], \"attack\": 0}\n        reward = np.random.rand()\n        info = {\n            \"inventory\": {\"wooden_planks\": step // 2, \"stick\": step // 3},\n            \"life_stats\": {\"health\": 20.0, \"food\": 18.0},\n            \"location_stats\": {\"pos\": [step * 2, 64, step * 1.5]}\n        }\n        \n        benchmark.update_step_metrics(obs, action, reward, info)\n        time.sleep(0.1)  # Simulate processing time\n    \n    # Test planning metrics\n    benchmark.update_planning_metrics(1.5, is_replanning=False)\n    benchmark.update_planning_metrics(0.8, is_replanning=True)\n    \n    # End episode\n    final_inventory = {\"wooden_planks\": 4, \"stick\": 2, \"wooden_slab\": 1}\n    episode_metrics = benchmark.end_episode(success=True, final_inventory=final_inventory)\n    \n    print(f\"Episode completed: {episode_metrics.success}\")\n    print(f\"Total steps: {episode_metrics.total_steps}\")\n    print(f\"Total reward: {episode_metrics.total_reward:.3f}\")\n    \n    # Test task evaluation\n    task_result = benchmark.evaluate_task(\n        task_id=\"obtain_wooden_slab\",\n        success=True,\n        completion_time=30.5,\n        total_steps=10,\n        total_reward=episode_metrics.total_reward,\n        final_inventory=final_inventory,\n        planning_iterations=2,\n        goal_changes=1\n    )\n    \n    print(f\"Task result: {task_result.success}\")\n    print(f\"Efficiency score: {task_result.efficiency_score:.3f}\")\n    \n    # Test benchmark summary\n    benchmark_suite = benchmark.compute_benchmark_summary()\n    print(f\"Benchmark suite success rate: {benchmark_suite.overall_success_rate:.1f}%\")\n    \n    # Save results\n    results_file = benchmark.save_results()\n    print(f\"Results saved to: {results_file}\")\n    \n    # Print summary\n    benchmark.print_summary()\n    \n    print(\"✓ Benchmark Metrics Test Passed\\n\")\n\n\ndef test_task_registry():\n    \"\"\"Test the task registry system\"\"\"\n    print(\"Testing Task Registry System...\")\n    \n    # Test task listing\n    all_tasks = TaskRegistry.list_task_ids()\n    print(f\"Total tasks available: {len(all_tasks)}\")\n    \n    # Test task categories\n    categories = [\"survival\", \"harvest\", \"mining\", \"tech_tree\", \"combat\", \"creative\"]\n    for category in categories:\n        tasks = TaskRegistry.get_tasks_by_type(category)\n        print(f\"{category.title()} tasks: {len(tasks)}\")\n    \n    # Test specific task info\n    task_info = TaskRegistry.get_task_info(\"obtain_wooden_slab\")\n    print(f\"Task info for 'obtain_wooden_slab': {task_info['description']}\")\n    \n    # Test task adapter\n    adapter = create_task_adapter()\n    adapter.start_task(\"obtain_wooden_slab\")\n    \n    # Test completion check\n    test_inventory = {\"wooden_slab\": 1}\n    test_info = {}\n    is_complete = adapter.check_task_completion(test_inventory, test_info)\n    print(f\"Task completion check: {is_complete}\")\n    \n    # Test reward calculation\n    reward = adapter.get_task_reward(test_inventory, test_info, 100)\n    print(f\"Task reward: {reward:.2f}\")\n    \n    print(\"✓ Task Registry Test Passed\\n\")\n\n\ndef test_wandb_integration():\n    \"\"\"Test WandB integration (mock mode if no internet)\"\"\"\n    print(\"Testing WandB Integration...\")\n    \n    try:\n        # Initialize WandB logger (will use offline mode if no internet)\n        wandb_logger = WandBLogger(\n            project_name=\"test-project\",\n            experiment_name=\"test-experiment\",\n            config={\"test\": True, \"max_steps\": 100},\n            tags=[\"test\", \"integration\"],\n            notes=\"Integration test for WandB logging\",\n            enabled=True\n        )\n        \n        # Test basic logging\n        wandb_logger.log_step_metrics(\n            step=1,\n            reward=1.5,\n            action={\"movement\": 1},\n            inventory={\"wooden_planks\": 2},\n            obs={\"rgb\": np.random.rand(64, 64, 3)},\n            info={\"life_stats\": {\"health\": 20.0}}\n        )\n        \n        # Test planning metrics\n        wandb_logger.log_planning_metrics(\n            plan=\"1. Find trees\\n2. Mine wood\\n3. Craft planks\",\n            goal_list=[\"mine_wood\", \"craft_planks\"],\n            selected_goal=\"mine_wood\",\n            planning_time=2.1\n        )\n        \n        # Test histogram\n        wandb_logger.log_histogram(\"test_rewards\", [1.0, 1.5, 2.0, 1.2, 1.8])\n        \n        # Test table\n        wandb_logger.log_table(\n            \"test_results\",\n            [\"Task\", \"Success\", \"Time\"],\n            [[\"task1\", True, 10.5], [\"task2\", False, 8.2]]\n        )\n        \n        wandb_logger.finish()\n        print(\"✓ WandB Integration Test Passed\\n\")\n        \n    except Exception as e:\n        print(f\"⚠ WandB Integration Test Failed (this is expected without internet): {e}\\n\")\n\n\ndef test_integrated_benchmark():\n    \"\"\"Test the integrated benchmark system\"\"\"\n    print(\"Testing Integrated Benchmark System...\")\n    \n    # Initialize systems\n    benchmark_metrics = BenchmarkMetrics(\"./test_integrated_results\")\n    \n    # Initialize WandB in offline mode for testing\n    wandb_logger = WandBLogger(\n        project_name=\"test-integrated\",\n        experiment_name=\"test-integrated-experiment\",\n        config={\"integrated_test\": True},\n        enabled=False  # Disable for testing\n    )\n    \n    integrated_benchmark = WandBIntegratedBenchmark(benchmark_metrics, wandb_logger)\n    \n    # Test episode workflow\n    integrated_benchmark.start_episode(\"integrated_episode_1\", \"obtain_wooden_slab\")\n    \n    # Simulate steps\n    for step in range(5):\n        obs = {\"rgb\": np.random.rand(32, 32, 3)}\n        action = {\"movement\": 1, \"attack\": step % 2}\n        reward = np.random.rand() * 2\n        info = {\n            \"inventory\": {\"wooden_planks\": step},\n            \"life_stats\": {\"health\": 20.0}\n        }\n        \n        integrated_benchmark.log_step(obs, action, reward, info)\n    \n    # Test planning logging\n    integrated_benchmark.log_planning(\n        plan=\"Test plan for integration\",\n        goal_list=[\"test_goal_1\", \"test_goal_2\"],\n        selected_goal=\"test_goal_1\",\n        planning_time=1.0\n    )\n    \n    # End episode\n    final_inventory = {\"wooden_slab\": 1}\n    episode_metrics = integrated_benchmark.end_episode(\n        success=True,\n        final_inventory=final_inventory,\n        task_id=\"obtain_wooden_slab\"\n    )\n    \n    # Complete task\n    task_result = integrated_benchmark.complete_task(\n        task_id=\"obtain_wooden_slab\",\n        success=True,\n        completion_time=15.2,\n        total_steps=5,\n        total_reward=5.5,\n        final_inventory=final_inventory\n    )\n    \n    print(f\"Integrated test completed successfully: {task_result.success}\")\n    print(\"✓ Integrated Benchmark Test Passed\\n\")\n\n\ndef main():\n    \"\"\"Run all tests\"\"\"\n    print(\"=\" * 60)\n    print(\"MineDojo-style Benchmarking Integration Tests\")\n    print(\"=\" * 60)\n    \n    # Run individual tests\n    test_benchmark_metrics()\n    test_task_registry()\n    test_wandb_integration()\n    test_integrated_benchmark()\n    \n    print(\"=\" * 60)\n    print(\"All Tests Completed Successfully!\")\n    print(\"=\" * 60)\n    \n    # Cleanup test files\n    cleanup_test_files()\n\n\ndef cleanup_test_files():\n    \"\"\"Clean up test result files\"\"\"\n    import shutil\n    \n    test_dirs = [\"./test_benchmark_results\", \"./test_integrated_results\"]\n    for test_dir in test_dirs:\n        if Path(test_dir).exists():\n            shutil.rmtree(test_dir)\n            print(f\"Cleaned up {test_dir}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"test_fp8_integration.py","text":"#!/usr/bin/env python3\n\"\"\"\nTest script for FP8 integration with NVIDIA Llama-3.3-70B-Instruct-FP8\nValidates FP8 model configuration and performance\n\"\"\"\n\nimport os\nimport sys\nimport time\nfrom pathlib import Path\n\n# Add project root to path\nsys.path.append(str(Path(__file__).parent))\n\nfrom diffu_moe_vlm.fp8_utils import validate_fp8_environment, create_fp8_manager\nfrom diffu_moe_vlm.planner import Planner\n\n\ndef test_fp8_environment():\n    \"\"\"Test FP8 environment setup\"\"\"\n    print(\"Testing FP8 Environment...\")\n    print(\"=\" * 50)\n    \n    # Validate environment\n    env_status = validate_fp8_environment()\n    \n    print(f\"Overall Status: {env_status['status']}\")\n    print(\"\\nDetailed Checks:\")\n    for check, result in env_status['checks'].items():\n        status = \"✓\" if result else \"✗\"\n        print(f\"  {status} {check}: {result}\")\n    \n    if env_status['recommendations']:\n        print(\"\\nRecommendations:\")\n        for rec in env_status['recommendations']:\n            print(f\"  • {rec}\")\n    \n    print(\"\\n\" + \"=\" * 50)\n    return env_status['status'] in ['ready', 'partial']\n\n\ndef test_fp8_manager():\n    \"\"\"Test FP8 model manager\"\"\"\n    print(\"Testing FP8 Model Manager...\")\n    print(\"=\" * 50)\n    \n    try:\n        # Create manager\n        manager = create_fp8_manager()\n        \n        # Get model info\n        info = manager.get_model_info()\n        print(f\"Model: {info['model_name']}\")\n        print(f\"Precision: {info['precision']}\")\n        print(f\"FP8 Enabled: {info['use_fp8']}\")\n        print(f\"TensorRT Available: {info['tensorrt_available']}\")\n        \n        # Check memory savings\n        memory_info = manager.estimate_memory_savings()\n        print(f\"\\nMemory Estimation:\")\n        print(f\"  FP16 Memory: {memory_info['fp16_memory_gb']:.1f} GB\")\n        print(f\"  FP8 Memory: {memory_info['fp8_memory_gb']:.1f} GB\")\n        print(f\"  Savings: {memory_info['memory_savings_gb']:.1f} GB ({memory_info['savings_percentage']:.1f}%)\")\n        \n        # Test validation\n        validation = manager.validate_fp8_setup()\n        print(f\"\\nValidation Results:\")\n        for check, result in validation.items():\n            status = \"✓\" if result else \"✗\"\n            print(f\"  {status} {check}: {result}\")\n        \n        # Test data conversion\n        import torch\n        test_data = torch.randn(2, 4)\n        converted = manager.convert_to_fp8(test_data)\n        print(f\"\\nData Conversion Test:\")\n        print(f\"  Original: {test_data.dtype}, shape: {test_data.shape}\")\n        print(f\"  Converted: {converted.dtype}, shape: {converted.shape}\")\n        print(f\"  Max difference: {torch.max(torch.abs(test_data.float() - converted.float())):.6f}\")\n        \n        print(\"\\n✓ FP8 Manager Test Passed\")\n        return True\n        \n    except Exception as e:\n        print(f\"✗ FP8 Manager Test Failed: {e}\")\n        return False\n\n\ndef test_planner_fp8_integration():\n    \"\"\"Test planner with FP8 integration\"\"\"\n    print(\"Testing Planner FP8 Integration...\")\n    print(\"=\" * 50)\n    \n    try:\n        # Initialize planner with FP8\n        os.environ[\"USE_FP8\"] = \"true\"\n        os.environ[\"LLM_MODEL\"] = \"nvidia/Llama-3.3-70B-Instruct-FP8\"\n        \n        planner = Planner()\n        \n        print(f\"Planner initialized with:\")\n        print(f\"  Model: {planner.llm_model}\")\n        print(f\"  FP8 Enabled: {planner.use_fp8}\")\n        print(f\"  Precision: {planner.precision}\")\n        print(f\"  FP8 Manager: {planner.fp8_manager is not None}\")\n        \n        # Test simple query\n        test_prompt = \"How to obtain wooden slab in Minecraft?\"\n        print(f\"\\nTesting query: '{test_prompt}'\")\n        \n        start_time = time.time()\n        try:\n            response = planner.query_llm(test_prompt, max_tokens=128, temperature=0.1)\n            elapsed = time.time() - start_time\n            \n            print(f\"Response received in {elapsed:.2f}s:\")\n            print(f\"  {response[:200]}{'...' if len(response) > 200 else ''}\")\n            \n            # Get performance stats if FP8 manager is available\n            if planner.fp8_manager:\n                stats = planner.fp8_manager.get_performance_stats()\n                print(f\"\\nPerformance Stats:\")\n                print(f\"  Requests: {stats['total_requests']}\")\n                print(f\"  Avg Latency: {stats['avg_latency_seconds']:.2f}s\")\n                print(f\"  Throughput: {stats['throughput_tokens_per_second']:.1f} tokens/s\")\n            \n            print(\"\\n✓ Planner FP8 Integration Test Passed\")\n            return True\n            \n        except Exception as e:\n            print(f\"Query failed (expected without actual model): {e}\")\n            print(\"✓ Planner FP8 Integration Test Passed (configuration)\")\n            return True\n        \n    except Exception as e:\n        print(f\"✗ Planner FP8 Integration Test Failed: {e}\")\n        return False\n\n\ndef test_benchmark_fp8_config():\n    \"\"\"Test benchmark configuration with FP8\"\"\"\n    print(\"Testing Benchmark FP8 Configuration...\")\n    print(\"=\" * 50)\n    \n    try:\n        import yaml\n        from omegaconf import OmegaConf\n        \n        # Load FP8 model config\n        fp8_config_path = Path(__file__).parent / \"configs\" / \"fp8_model.yaml\"\n        if fp8_config_path.exists():\n            with open(fp8_config_path, 'r') as f:\n                fp8_config = yaml.safe_load(f)\n            \n            print(\"FP8 Model Configuration:\")\n            print(f\"  Model: {fp8_config['model_name']}\")\n            print(f\"  Quantization: {fp8_config['quantization']['enabled']}\")\n            print(f\"  Precision: {fp8_config['quantization']['precision']}\")\n            print(f\"  Data Type: {fp8_config['quantization']['data_type']}\")\n            print(f\"  Max Context: {fp8_config['engine']['max_context_length']}\")\n            print(f\"  Tensor Parallel: {fp8_config['performance']['tensor_parallel_size']}\")\n        \n        # Load benchmark config\n        benchmark_config_path = Path(__file__).parent / \"configs\" / \"benchmark.yaml\"\n        if benchmark_config_path.exists():\n            with open(benchmark_config_path, 'r') as f:\n                benchmark_config = yaml.safe_load(f)\n            \n            llm_config = benchmark_config.get('llm', {})\n            print(f\"\\nBenchmark LLM Configuration:\")\n            print(f\"  Model: {llm_config.get('model')}\")\n            print(f\"  FP8 Enabled: {llm_config.get('use_fp8')}\")\n            print(f\"  Precision: {llm_config.get('precision')}\")\n            \n            if 'quantization' in llm_config:\n                quant = llm_config['quantization']\n                print(f\"  Quantization: {quant.get('enable_fp8')}\")\n                print(f\"  KV Cache FP8: {quant.get('fp8_kv_cache')}\")\n        \n        print(\"\\n✓ Benchmark FP8 Configuration Test Passed\")\n        return True\n        \n    except Exception as e:\n        print(f\"✗ Benchmark FP8 Configuration Test Failed: {e}\")\n        return False\n\n\ndef run_performance_comparison():\n    \"\"\"Run performance comparison between FP8 and non-FP8\"\"\"\n    print(\"Performance Comparison (FP8 vs Standard)...\")\n    print(\"=\" * 50)\n    \n    # This would require actual model access for meaningful comparison\n    print(\"Note: Actual performance comparison requires model deployment\")\n    \n    # Theoretical comparison based on model specifications\n    print(\"Theoretical Performance (70B model):\")\n    print(\"  FP16 Memory: ~140 GB\")\n    print(\"  FP8 Memory: ~70 GB (50% reduction)\")\n    print(\"  FP16 Accuracy: MMLU 83.3%, GSM8K 95.3%\")\n    print(\"  FP8 Accuracy: MMLU 83.2%, GSM8K 94.3%\")\n    print(\"  Accuracy Drop: <1% across benchmarks\")\n    \n    print(\"\\n✓ Performance Comparison Information Provided\")\n    return True\n\n\ndef main():\n    \"\"\"Run all FP8 tests\"\"\"\n    print(\"FP8 Integration Test Suite\")\n    print(\"=\" * 60)\n    print(\"Testing NVIDIA Llama-3.3-70B-Instruct-FP8 integration\")\n    print(\"=\" * 60)\n    \n    tests = [\n        (\"Environment Validation\", test_fp8_environment),\n        (\"FP8 Manager\", test_fp8_manager),\n        (\"Planner Integration\", test_planner_fp8_integration),\n        (\"Benchmark Configuration\", test_benchmark_fp8_config),\n        (\"Performance Analysis\", run_performance_comparison)\n    ]\n    \n    results = []\n    for test_name, test_func in tests:\n        print(f\"\\n{test_name}\")\n        print(\"-\" * len(test_name))\n        try:\n            result = test_func()\n            results.append((test_name, result))\n        except Exception as e:\n            print(f\"Test failed with exception: {e}\")\n            results.append((test_name, False))\n    \n    # Summary\n    print(\"\\n\" + \"=\" * 60)\n    print(\"TEST SUMMARY\")\n    print(\"=\" * 60)\n    \n    passed = 0\n    for test_name, result in results:\n        status = \"PASS\" if result else \"FAIL\"\n        print(f\"{test_name}: {status}\")\n        if result:\n            passed += 1\n    \n    print(f\"\\nOverall: {passed}/{len(results)} tests passed\")\n    \n    if passed == len(results):\n        print(\"🎉 All tests passed! FP8 integration is ready.\")\n    else:\n        print(\"⚠️  Some tests failed. Check configuration and dependencies.\")\n    \n    return passed == len(results)\n\n\nif __name__ == \"__main__\":\n    success = main()\n    sys.exit(0 if success else 1)\n"},{"path":"test_wandb_integration.py","text":"#!/usr/bin/env python3\n\"\"\"\nTest script for WandB integration in main.py\n\"\"\"\n\nimport os\nimport sys\nfrom pathlib import Path\nimport tempfile\n\n# Add project root to path\nproject_root = Path(__file__).parent\nsys.path.append(str(project_root))\n\ndef test_wandb_integration():\n    \"\"\"Test WandB integration\"\"\"\n    print(\"Testing WandB integration...\")\n    \n    # Create temporary output directory\n    with tempfile.TemporaryDirectory() as temp_dir:\n        # Set environment variables for testing\n        os.environ[\"WANDB_MODE\"] = \"offline\"  # Run in offline mode for testing\n        \n        # Test configuration\n        test_config = {\n            'wandb': {\n                'enabled': True,\n                'project': 'test-diffu-moe-vlm',\n                'experiment_name': 'test_run',\n                'tags': ['test', 'minecraft'],\n                'notes': 'Test run for WandB integration',\n                'log_images': False,  # Disable image logging for test\n                'mode': 'offline'\n            },\n            'eval': {\n                'env_name': 'Plains',\n                'max_steps': 10  # Very short test\n            },\n            'simulator': {\n                'resolution': [64, 64]  # Small resolution for test\n            },\n            'goal_model': {\n                'freq': 5,\n                'queue_size': 3\n            },\n            'record': {\n                'frames': False\n            },\n            'single_task': True,\n            'task_name': 'obtain_wooden_slab',\n            'output_dir': temp_dir\n        }\n        \n        try:\n            # Import and test\n            from omegaconf import OmegaConf\n            cfg = OmegaConf.create(test_config)\n            \n            # Test imports\n            from diffu_moe_vlm.wandb_integration import WandBLogger, WandBIntegratedBenchmark\n            from diffu_moe_vlm.benchmark_metrics import BenchmarkMetrics\n            \n            print(\"✓ Successfully imported WandB integration modules\")\n            \n            # Test WandB logger initialization\n            logger = WandBLogger(\n                project_name=test_config['wandb']['project'],\n                experiment_name=test_config['wandb']['experiment_name'],\n                config=test_config,\n                tags=test_config['wandb']['tags'],\n                notes=test_config['wandb']['notes'],\n                enabled=True\n            )\n            \n            print(\"✓ Successfully initialized WandB logger\")\n            \n            # Test basic logging\n            logger.log_step_metrics(\n                step=0,\n                reward=0.0,\n                action={'movement': 0},\n                inventory={},\n                obs={'rgb': None},\n                info={}\n            )\n            \n            print(\"✓ Successfully logged test metrics\")\n            \n            # Clean up\n            logger.finish()\n            print(\"✓ Successfully finished WandB session\")\n            \n            print(\"\\n🎉 WandB integration test passed!\")\n            return True\n            \n        except ImportError as e:\n            print(f\"❌ Import error: {e}\")\n            print(\"Please ensure all required modules are available\")\n            return False\n        except Exception as e:\n            print(f\"❌ Test failed: {e}\")\n            return False\n\nif __name__ == \"__main__\":\n    success = test_wandb_integration()\n    sys.exit(0 if success else 1)\n"},{"path":"tests/test_core.py","text":"import pytest\n\nfrom diffu_moe_vlm.core import (\n    apply_action, goal_item, goal_name, mc, obtain_method, parse_plan_to_goals, plan_steps, task_registry,\n)\nfrom diffu_moe_vlm.planner import Planner\n\n\ndef simulate(steps, inventory=None):\n    inventory = dict(inventory or {})\n    for verb, item in steps:\n        inventory, ok, error = apply_action(inventory, verb, item)\n        assert ok, error\n    return inventory\n\n\ndef test_apply_action_consumes_ingredients_and_requires_tools():\n    inv, ok, _ = apply_action({'wood': 1}, 'craft', 'wooden_planks')\n    assert ok and inv == {'wooden_planks': 4}\n\n    inv, ok, error = apply_action({}, 'mine', 'cobblestone')\n    assert not ok and 'wooden_pickaxe' in error\n\n    inv, ok, _ = apply_action({'wooden_pickaxe': 1}, 'mine', 'cobblestone')\n    assert ok and inv == {'wooden_pickaxe': 1, 'cobblestone': 1}  # tools are not consumed\n\n\ndef test_apply_action_rejects_wrong_verb():\n    _, ok, _ = apply_action({'wood': 5}, 'mine', 'wooden_planks')\n    assert not ok\n\n\n@pytest.mark.parametrize(\"task\", sorted(task_registry.tasks))\ndef test_plan_steps_reach_every_task_target(task):\n    target = task_registry.get_task(task)['target']\n    final = simulate(plan_steps(target))\n    assert final.get(target, 0) >= 1\n\n\ndef test_plan_steps_respects_quantities_and_existing_inventory():\n    steps = plan_steps('stone_stairs')\n    assert steps.count(('mine', 'cobblestone')) == 6\n    # Two planks are not enough for a pickaxe (needs 3), so more wood is gathered\n    steps = plan_steps('wooden_pickaxe', {'crafting_table': 1, 'wooden_planks': 2, 'stick': 4})\n    assert steps == [('mine', 'wood'), ('craft', 'wooden_planks'), ('craft', 'wooden_pickaxe')]\n\n\ndef test_goal_names_roundtrip():\n    for item in mc.ALL_ITEMS:\n        assert goal_item(goal_name(item)) == item\n    assert goal_name('wood') == 'mine_wood'\n    assert goal_name('iron_ingot') == 'obtain_iron_ingot'\n    assert obtain_method('unknown_item') is None\n\n\ndef test_parse_plan_to_goals_handles_llm_style_text():\n    plan = (\n        \"1. Find and approach trees\\n\"\n        \"2. Mine wood logs from trees\\n\"\n        \"3. Craft wooden planks from wood (4 planks per log)\\n\"\n        \"4. Craft a crafting table\\n\"\n        \"5. Craft a stone pickaxe\\n\"\n        \"6. Mine stone x3\\n\"\n        \"7. Look around\\n\"\n    )\n    assert parse_plan_to_goals(plan) == [\n        'mine_wood', 'obtain_wooden_planks', 'obtain_crafting_table', 'obtain_stone_pickaxe',\n        'mine_cobblestone', 'mine_cobblestone', 'mine_cobblestone',\n    ]\n\n\ndef test_fallback_plan_roundtrips_through_parser():\n    steps = plan_steps('iron_pickaxe')\n    goals = parse_plan_to_goals(Planner.format_plan(steps))\n    assert [goal_item(g) for g in goals] == [item for _, item in steps]\n"},{"path":"tests/test_env_controller.py","text":"import pytest\nfrom gymnasium.utils.env_checker import check_env\n\nfrom diffu_moe_vlm.controller import GoalController\nfrom diffu_moe_vlm.core import goal_name, task_registry\nfrom diffu_moe_vlm.env import MinecraftGymnasiumEnv\n\n\ndef make_env(**kwargs):\n    return MinecraftGymnasiumEnv(img_size=(32, 24), **kwargs)\n\n\ndef test_passes_gymnasium_env_checker():\n    check_env(make_env(), skip_render_check=True)\n\n\ndef test_observation_layout():\n    env = make_env()\n    obs, info = env.reset(options={'task': 'obtain_wooden_slab'})\n    assert obs['rgb'].shape == (24, 32, 3)\n    assert obs['inventory'].sum() == 0\n    assert info['target'] == 'wooden_slab' and info['inventory'] == {}\n\n\ndef test_actions_change_inventory_and_succeed_on_target():\n    env = make_env()\n    env.reset(options={'task': 'obtain_wooden_slab'})\n    _, _, _, _, info = env.step({'type': 'craft', 'item': 'wooden_planks'})\n    assert not info['action_success'] and 'wood' in info['action_error']\n\n    env.step(('mine', 'wood'))\n    env.step(env.encode_action('craft', 'wooden_planks'))\n    _, reward, terminated, truncated, info = env.step({'type': 'craft', 'item': 'wooden_slab'})\n    assert info['inventory']['wooden_slab'] == 6\n    assert reward == 1.0 and terminated and not truncated and info['task_success']\n\n\ndef test_truncates_at_max_steps():\n    env = make_env(max_steps=2)\n    env.reset(options={'task': 'mine_diamond'})\n    assert not env.step(0)[3]\n    assert env.step(0)[3]\n\n\ndef test_unknown_task_raises():\n    with pytest.raises(ValueError):\n        make_env().reset(options={'task': 'obtain_unobtainium'})\n\n\n@pytest.mark.parametrize(\"task\", sorted(task_registry.tasks))\ndef test_controller_with_prerequisites_reaches_every_target(task):\n    env = make_env(max_steps=200)\n    _, info = env.reset(options={'task': task})\n    controller = GoalController(auto_prerequisites=True)\n    goal = goal_name(info['target'])\n    for _ in range(200):\n        _, _, terminated, truncated, info = env.step(controller.next_action(goal, info['inventory']))\n        assert info['action_success'], info['action_error']\n        if terminated or truncated:\n            break\n    assert info['task_success']\n\n\ndef test_controller_without_prerequisites_only_attempts_goal():\n    controller = GoalController(auto_prerequisites=False)\n    assert controller.next_action('obtain_iron_pickaxe', {}) == {'type': 'craft', 'item': 'iron_pickaxe'}\n    assert controller.next_action('obtain_nothing', {}) is None\n"},{"path":"tests/test_evaluator.py","text":"from pathlib import Path\n\nimport pytest\nfrom omegaconf import OmegaConf\n\nfrom diffu_moe_vlm.evaluator import Evaluator\n\nCONFIG_DIR = Path(__file__).resolve().parent.parent / \"configs\"\n\n\n@pytest.fixture\ndef cfg(tmp_path):\n    cfg = OmegaConf.load(CONFIG_DIR / \"defaults.yaml\")\n    for group in (\"data/planning\", \"eval/planning\", \"goal_model/horizon\"):\n        name = group.split(\"/\")[0]\n        cfg[name] = OmegaConf.merge(OmegaConf.load(CONFIG_DIR / f\"{group}.yaml\"), cfg.get(name, {}))\n    cfg.wandb.enabled = False\n    cfg.llm.enabled = False\n    cfg.output_dir = str(tmp_path)\n    cfg.simulator.resolution = [32, 24]\n    return cfg\n\n\ndef test_rule_based_baseline_solves_default_tasks(cfg):\n    results = Evaluator(cfg).run_all_tasks()\n    assert len(results) == 6\n    assert all(r['success'] for r in results), results\n\n\n@pytest.mark.parametrize(\"auto_prerequisites\", [True, False])\ndef test_replanning_recovers_from_random_action_failures(cfg, auto_prerequisites):\n    cfg.env.action_failure_prob = 0.3\n    cfg.controller.auto_prerequisites = auto_prerequisites\n    result = Evaluator(cfg).single_task_evaluate('obtain_stone_stairs')\n    assert result['success']\n\n\ndef test_bad_plan_needs_controller_prerequisites(cfg):\n    \"\"\"An LLM plan that skips steps only works when the controller fills the gaps\"\"\"\n    outcomes = {}\n    for auto in (True, False):\n        cfg.controller.auto_prerequisites = auto\n        evaluator = Evaluator(cfg)\n        evaluator.planner.llm_available = True\n        evaluator.planner.query_llm = lambda prompt: \"1. Craft a wooden pickaxe\\n2. Mine cobblestone\"\n        outcomes[auto] = evaluator.single_task_evaluate('mine_cobblestone')\n    assert outcomes[True]['success']\n    assert not outcomes[False]['success']\n    assert outcomes[False]['replans'] == cfg.eval.max_replans\n"},{"path":"tests/test_jax_rl.py","text":"\"\"\"Tests for the JAX Craftax path (skipped without jax/flax/craftax)\"\"\"\n\nimport numpy as np\nimport pytest\n\njax = pytest.importorskip(\"jax\")\npytest.importorskip(\"flax\")\npytest.importorskip(\"craftax\")\n\nimport jax.numpy as jnp  # noqa: E402\n\nfrom diffu_moe_vlm.jax_rl.networks import ActorCriticRNN, MoEDense, ScannedGRU  # noqa: E402\nfrom diffu_moe_vlm.jax_rl.ppo import RunningMoments, compute_gae, make_train, update_moments  # noqa: E402\nfrom diffu_moe_vlm.jax_rl.wrappers import LogWrapper, OptimisticResetBatchEnv  # noqa: E402\n\n\ndef numpy_gae(rewards, values, dones, last_value, gamma, lam):\n    adv = np.zeros_like(rewards)\n    gae = np.zeros_like(last_value)\n    next_value = last_value\n    for t in reversed(range(len(rewards))):\n        nd = 1.0 - dones[t]\n        delta = rewards[t] + gamma * next_value * nd - values[t]\n        gae = delta + gamma * lam * nd * gae\n        adv[t] = gae\n        next_value = values[t]\n    return adv\n\n\ndef test_gae_matches_numpy_reference():\n    rng = np.random.default_rng(0)\n    r, v = rng.normal(size=(7, 3)).astype(np.float32), rng.normal(size=(7, 3)).astype(np.float32)\n    d = rng.random((7, 3)) < 0.3\n    last = rng.normal(size=3).astype(np.float32)\n    adv, tgt = compute_gae(jnp.asarray(r), jnp.asarray(v), jnp.asarray(d), jnp.asarray(last), 0.99, 0.8)\n    np.testing.assert_allclose(np.asarray(adv), numpy_gae(r, v, d.astype(np.float32), last, 0.99, 0.8), rtol=1e-5, atol=1e-5)\n    np.testing.assert_allclose(np.asarray(tgt), np.asarray(adv) + v, rtol=1e-6)\n\n\ndef test_running_moments_match_numpy():\n    rng = np.random.default_rng(1)\n    chunks = [rng.exponential(size=50).astype(np.float32) for _ in range(4)]\n    m = RunningMoments(jnp.zeros(()), jnp.ones(()), jnp.asarray(1e-4))\n    for c in chunks:\n        m = update_moments(m, jnp.asarray(c))\n    allx = np.concatenate(chunks)\n    assert abs(float(m.mean) - allx.mean()) < 1e-3 and abs(float(m.var) - allx.var()) < 1e-2\n\n\nclass CounterEnv:\n    \"\"\"Minimal env exposing step_env/reset_env: episode ends after 3 steps; reset draws a random id\"\"\"\n\n    def reset_env(self, key, params):\n        state = {\"t\": jnp.zeros((), jnp.int32), \"id\": jax.random.randint(key, (), 0, 1_000_000)}\n        return jnp.zeros(2), state\n\n    def reset(self, key, params):\n        return self.reset_env(key, params)\n\n    def step_env(self, key, state, action, params):\n        state = {\"t\": state[\"t\"] + 1, \"id\": state[\"id\"]}\n        done = state[\"t\"] >= 3\n        return jnp.ones(2) * state[\"t\"], state, jnp.float32(1.0), done, {}\n\n\ndef test_optimistic_resets_restart_done_envs_with_distinct_worlds():\n    env = LogWrapper(OptimisticResetBatchEnv(CounterEnv(), num_envs=8, reset_ratio=2))\n    obs, state = env.reset(jax.random.PRNGKey(0), None)\n    actions = jnp.zeros(8, jnp.int32)\n    for i in range(3):\n        obs, state, reward, done, info = env.step(jax.random.PRNGKey(i + 1), state, actions, None)\n    assert bool(done.all())\n    assert (np.asarray(state.env_state[\"t\"]) == 0).all()                  # every env restarted\n    assert len(set(np.asarray(state.env_state[\"id\"]).tolist())) >= 4      # 4 fresh worlds for 8 envs\n    assert np.allclose(np.asarray(info[\"returned_episode_returns\"]), 3.0)\n    assert np.allclose(np.asarray(info[\"returned_episode_lengths\"]), 3)\n\n\ndef test_moe_dense_shapes_and_balance_loss():\n    layer = MoEDense(features=16, num_experts=4, top_k=2)\n    x = jax.random.normal(jax.random.PRNGKey(0), (64, 8))\n    params = layer.init(jax.random.PRNGKey(1), x)\n    y, aux = layer.apply(params, x)\n    assert y.shape == (64, 16) and 1.0 <= float(aux) <= 4.0\n\n\ndef test_rnn_resets_hidden_state_on_episode_boundary():\n    net = ActorCriticRNN(action_dim=5, width=16)\n    obs = jax.random.normal(jax.random.PRNGKey(0), (3, 2, 10))\n    h0 = ScannedGRU.initialize_carry(2, 16)\n    params = net.init(jax.random.PRNGKey(1), h0, (obs, jnp.zeros((3, 2), bool)))\n    warm = jnp.ones((2, 16))\n    _, pi_reset, v_reset, _ = net.apply(params, warm, (obs[:1], jnp.ones((1, 2), bool)))\n    _, pi_fresh, v_fresh, _ = net.apply(params, h0, (obs[:1], jnp.zeros((1, 2), bool)))\n    np.testing.assert_allclose(np.asarray(v_reset), np.asarray(v_fresh), rtol=1e-6)\n    _, _, v_warm, _ = net.apply(params, warm, (obs[:1], jnp.zeros((1, 2), bool)))\n    assert not np.allclose(np.asarray(v_warm), np.asarray(v_fresh))\n\n\n@pytest.mark.parametrize(\"rnn\", [False, True])\ndef test_training_is_deterministic_given_seed(rnn):\n    cfg = dict(env_name=\"Craftax-Classic-Symbolic-v1\", num_envs=16, num_steps=8, num_minibatches=2,\n               update_epochs=1, layer_size=32, total_timesteps=16 * 8 * 2, reset_ratio=4, rnn=rnn)\n    train = jax.jit(make_train(cfg))\n    a, b, c = (train(jax.random.PRNGKey(s))[\"metrics\"] for s in (0, 0, 1))\n    for key in a:\n        np.testing.assert_array_equal(np.asarray(a[key]), np.asarray(b[key]))\n    assert any(not np.array_equal(np.asarray(a[k]), np.asarray(c[k])) for k in (\"loss/total\", \"loss/value\"))\n    assert np.isfinite(np.asarray(a[\"loss/total\"])).all()\n\n\ndef test_resume_from_checkpoint_is_bitwise_identical(tmp_path):\n    from diffu_moe_vlm.jax_rl.ppo import load_runner, save_runner\n\n    cfg = dict(env_name=\"Craftax-Classic-Symbolic-v1\", num_envs=16, num_steps=8, num_minibatches=2,\n               update_epochs=1, layer_size=32, total_timesteps=16 * 8 * 4, reset_ratio=4, rnn=True)\n    train = make_train(cfg)\n    runner = train.init(jax.random.PRNGKey(3))\n    straight, m_straight = train.run_updates(runner, 0, 4)\n\n    half, m_first = train.run_updates(runner, 0, 2)\n    save_runner(tmp_path / \"ckpt.npz\", half, 2)\n    restored, next_update = load_runner(tmp_path / \"ckpt.npz\", train.init(jax.random.PRNGKey(99)))\n    resumed, m_second = train.run_updates(restored, next_update, 2)\n\n    assert next_update == 2\n    for key in m_straight:\n        np.testing.assert_array_equal(np.asarray(m_straight[key]),\n                                      np.concatenate([np.asarray(m_first[key]), np.asarray(m_second[key])]))\n    for a, b in zip(jax.tree_util.tree_leaves(straight[0].params), jax.tree_util.tree_leaves(resumed[0].params)):\n        np.testing.assert_array_equal(np.asarray(a), np.asarray(b))\n\n\n# ---- ICM normalization ablation ----\n\ndef test_ema_initializes_with_first_batch_then_decays():\n    from diffu_moe_vlm.jax_rl.ppo import update_ema\n\n    m = RunningMoments(jnp.zeros(()), jnp.ones(()), jnp.asarray(1e-4))\n    m = update_ema(m, jnp.full((4,), 10.0), 0.9)\n    assert float(m.mean) == pytest.approx(10.0) and float(m.count) == 1\n    m = update_ema(m, jnp.full((4,), 0.0), 0.9)\n    assert float(m.mean) == pytest.approx(9.0) and float(m.count) == 2\n\n\ndef test_icm_normalizer_modes():\n    from diffu_moe_vlm.jax_rl.ppo import icm_normalizer\n\n    assert icm_normalizer({\"icm_normalize\": True}) == \"mean\"\n    assert icm_normalizer({\"icm_normalize\": False}) == \"none\"\n    assert icm_normalizer({\"icm_normalize\": \"ema\"}) == \"ema\"\n    with pytest.raises(ValueError):\n        icm_normalizer({\"icm_normalize\": \"max\"})\n\n\ndef test_craftax_score_matches_formula():\n    from diffu_moe_vlm.jax_rl.ppo import craftax_score\n\n    rates = np.array([0.0, 10.0, 100.0], np.float32)\n    assert float(craftax_score(jnp.asarray(rates))) == pytest.approx(np.exp(np.log1p(rates).mean()) - 1, rel=1e-5)\n\n\n@pytest.mark.parametrize(\"mode\", [\"none\", \"std\", \"mean\", \"ema\"])\ndef test_icm_modes_log_bonus_and_exploration_metrics(mode):\n    coef = 0.01\n    cfg = dict(env_name=\"Craftax-Classic-Symbolic-v1\", num_envs=16, num_steps=8, num_minibatches=2,\n               update_epochs=1, layer_size=32, total_timesteps=16 * 8 * 2, reset_ratio=4,\n               icm=True, icm_normalize=mode, icm_reward_coef=coef)\n    m = jax.jit(make_train(cfg))(jax.random.PRNGKey(0))[\"metrics\"]\n    share = np.asarray(m[\"icm/bonus_share\"])\n    assert ((share >= 0) & (share <= 1)).all()\n    for key in (\"craftax_score\", \"achievement_coverage\", \"icm/raw_error_mean\", \"icm/bonus_max\", \"icm/scale\"):\n        assert np.isfinite(np.asarray(m[key])).all()\n    first_bonus = float(np.asarray(m[\"icm/bonus_mean\"])[0])\n    first_raw = float(np.asarray(m[\"icm/raw_error_mean\"])[0])\n    if mode in (\"mean\", \"ema\"):     # the first batch defines the scale, so the bonus averages the coefficient\n        assert first_bonus == pytest.approx(coef, rel=1e-3)\n    elif mode == \"none\":\n        assert first_bonus == pytest.approx(coef * first_raw, rel=1e-4)\n\n\ndef _rows(shares, returns, covered):\n    rows = []\n    for i, (s, r) in enumerate(zip(shares, returns)):\n        row = {\"update\": i + 1, \"env_steps\": (i + 1) * 2e7, \"episodes\": 4, \"episode_return\": r,\n               \"craftax_score\": r / 10, \"achievements\": r, \"achievement_coverage\": float(covered),\n               \"Achievements/a\": 50.0, \"Achievements/b\": 10.0 if covered > 1 else 0.0}\n        if s is not None:\n            row.update({\"icm/bonus_share\": s, \"icm/raw_error_mean\": 1.0 + i, \"icm/bonus_mean\": s, \"icm/bonus_max\": s})\n        rows.append(row)\n    return rows\n\n\ndef test_analysis_detects_runaway_and_paired_exploration(tmp_path):\n    import json as _json\n\n    from analyze_icm_ablation import analyze, write_report\n\n    # icm_mean: early bonus share is high (sparse extrinsic reward) but falls; it must not count as runaway\n    arms = {\"ppo\": ([None] * 5, [1, 2, 3, 3, 3], 1), \"icm_mean\": ([0.8, 0.6, 0.3, 0.2, 0.1], [1, 2, 3, 4, 4], 2),\n            \"icm_none\": ([0.2, 0.6, 0.9, 0.95, 0.97], [1, 1, 0, 0, 0], 1)}\n    for arm, (shares, rets, cov) in arms.items():\n        for seed in range(3):\n            d = tmp_path / arm / f\"seed{seed}\"\n            d.mkdir(parents=True)\n            (d / \"metrics.jsonl\").write_text(\"\\n\".join(_json.dumps(r) for r in _rows(shares, rets, cov)))\n    result = analyze(tmp_path)\n    none, mean = result[\"arms\"][\"icm_none\"][\"seeds\"][0], result[\"arms\"][\"icm_mean\"][\"seeds\"][0]\n    assert none[\"runaway_fraction\"] == pytest.approx(0.8) and none[\"runaway\"] == 1.0\n    assert none[\"bonus_growth\"] == pytest.approx(0.97 / 0.2)\n    assert mean[\"runaway\"] == 0.0 and mean[\"bonus_growth\"] < 1.0\n    assert result[\"comparisons\"][\"icm_mean\"][\"coverage_ever\"][\"positive\"] == 3\n    assert result[\"verdict\"][\"H1\"][0] == \"supported\" and result[\"verdict\"][\"H2\"][0] == \"supported\"\n    assert \"Verdict\" in write_report(result, tmp_path) and (tmp_path / \"summary.json\").exists()\n    assert list(result[\"arms\"]) == [\"ppo\", \"icm_none\", \"icm_mean\"]\n\n\ndef test_analysis_refuses_verdict_on_short_runs(tmp_path):\n    import json as _json\n\n    from analyze_icm_ablation import analyze\n\n    for arm in (\"ppo\", \"icm_mean\"):\n        d = tmp_path / arm / \"seed0\"\n        d.mkdir(parents=True)\n        rows = _rows([None if arm == \"ppo\" else 0.1] * 3, [1, 2, 3], 1)\n        for r in rows:\n            r[\"env_steps\"] = 1000.0\n        (d / \"metrics.jsonl\").write_text(\"\\n\".join(_json.dumps(r) for r in rows))\n    assert analyze(tmp_path)[\"verdict\"][\"H1\"][0] == \"too short\"\n\n\ndef test_ablation_runner_builds_one_change_per_arm(tmp_path):\n    from run_icm_ablation import build_runs\n\n    runs = build_runs(\"gpu\", [\"ppo\", \"icm_mean\", \"icm_std\"], [0, 1], 1e9, tmp_path)\n    assert len(runs) == 6\n    by_arm = {r[\"arm\"]: r[\"cmd\"] for r in runs if r[\"seed\"] == 0}\n    assert \"algo.icm=false\" in by_arm[\"ppo\"] and \"algo.icm_normalize=mean\" in by_arm[\"icm_mean\"]\n    common = lambda cmd: sorted(a for a in cmd[2:] if not a.startswith((\"algo.icm\", \"output_dir\", \"name\")))\n    assert common(by_arm[\"ppo\"]) == common(by_arm[\"icm_mean\"]) == common(by_arm[\"icm_std\"])\n"},{"path":"tests/test_nn.py","text":"import numpy as np\nimport pytest\n\ntorch = pytest.importorskip(\"torch\")\n\nfrom diffu_moe_vlm.imu import load_trajectories, make_synthetic_trajectories, save_trajectories, to_torch_batch  # noqa: E402\nfrom diffu_moe_vlm.nn.diffusion import build_diffusion_policy  # noqa: E402\nfrom diffu_moe_vlm.nn.encoders import build_encoder  # noqa: E402\nfrom diffu_moe_vlm.nn.moe import MoELayer, Trunk  # noqa: E402\nfrom diffu_moe_vlm.nn.policy import build_actor_critic  # noqa: E402\nfrom diffu_moe_vlm.nn.time_embedding import TrajectoryEncoder  # noqa: E402\n\n\ndef images(n=4, seed=0):\n    g = torch.Generator().manual_seed(seed)\n    return torch.randint(0, 256, (n, 64, 64, 3), dtype=torch.uint8, generator=g)\n\n\n@pytest.mark.parametrize(\"name\", [\"cnn\", \"vit\"])\ndef test_encoders_output_feature_dim(name):\n    enc = build_encoder(name, feature_dim=96)\n    assert enc(images()).shape == (4, 96)\n\n\ndef test_pretrained_encoder_from_config():\n    transformers = pytest.importorskip(\"transformers\")\n    config = transformers.CLIPVisionConfig(hidden_size=32, intermediate_size=64, num_hidden_layers=1,\n                                           num_attention_heads=2, image_size=32, patch_size=8)\n    from diffu_moe_vlm.nn.encoders import PretrainedVisionEncoder\n    enc = PretrainedVisionEncoder(feature_dim=48, config=config)\n    assert enc(images(2)).shape == (2, 48)\n    assert not any(p.requires_grad for p in enc.vision.parameters())\n\n\ndef test_moe_routes_top_k_and_balances():\n    torch.manual_seed(0)\n    layer = MoELayer(dim=16, hidden_dim=32, num_experts=4, top_k=2)\n    x = torch.randn(256, 16)\n    y, aux = layer(x)\n    assert y.shape == x.shape\n    assert 1.0 <= aux.item() <= 4.0       # 1 = perfectly balanced, E = everything on one expert\n    assert abs(layer.last_load.sum().item() - 1.0) < 1e-5\n    (y.pow(2).mean() + aux).backward()\n    assert layer.gate.weight.grad is not None and layer.gate.weight.grad.abs().sum() > 0\n\n\ndef test_moe_aux_loss_penalizes_collapse():\n    layer = MoELayer(dim=8, hidden_dim=16, num_experts=4, top_k=1, noisy_gating=False)\n    with torch.no_grad():\n        layer.gate.weight.zero_()\n        layer.gate.weight[0] = 10.0       # every positive input goes to expert 0\n    _, aux = layer(torch.ones(32, 8))\n    assert aux.item() > 3.5\n\n\ndef test_dense_trunk_has_no_aux_loss():\n    h, aux = Trunk(16, 32, kind=\"mlp\")(torch.randn(3, 16))\n    assert h.shape == (3, 16) and aux.item() == 0.0\n    with pytest.raises(ValueError):\n        Trunk(16, 32, kind=\"unknown\")\n\n\ndef test_actor_critic_shapes_and_trajectory_conditioning():\n    model = build_actor_critic({\"encoder\": {\"name\": \"cnn\", \"feature_dim\": 64}, \"hidden_dim\": 64,\n                                \"trajectory\": {\"num_joints\": 3, \"dim\": 32, \"out_dim\": 16}}, num_actions=17)\n    traj = to_torch_batch(make_synthetic_trajectories(4, 20))\n    logits, value, aux = model(images(), traj)\n    assert logits.shape == (4, 17) and value.shape == (4,) and aux.ndim == 0\n    action, logp, _ = model.act(images(), traj)\n    assert action.shape == (4,) and torch.all(logp <= 0)\n    with pytest.raises(ValueError):\n        model(images())\n\n\ndef test_trajectory_encoder_ignores_masked_padding():\n    torch.manual_seed(0)\n    enc = TrajectoryEncoder(num_joints=3, dim=32, out_dim=8).eval()\n    data = to_torch_batch(make_synthetic_trajectories(2, 30))\n    short = enc(data[\"positions\"][:, :20], data[\"timestamps\"][:, :20])\n    mask = torch.zeros(2, 30, dtype=torch.bool)\n    mask[:, :20] = True\n    padded = enc(data[\"positions\"], data[\"timestamps\"], mask)\n    assert torch.allclose(short, padded, atol=1e-5)\n\n\ndef test_trajectory_encoder_learns_synthetic_motions(tmp_path):\n    torch.manual_seed(0)\n    path = tmp_path / \"traj.npz\"\n    save_trajectories(path, make_synthetic_trajectories(512, 48, seed=1))\n    data = load_trajectories(path)\n    labels = torch.as_tensor(data[\"labels\"])\n    enc = TrajectoryEncoder(num_joints=3, dim=64, out_dim=4)\n    opt = torch.optim.Adam(enc.parameters(), lr=1e-3)\n    train, test = np.arange(384), np.arange(384, 512)\n    for step in range(150):\n        idx = np.random.default_rng(step).choice(train, 64)\n        loss = torch.nn.functional.cross_entropy(enc(**to_torch_batch(data, idx)), labels[idx])\n        opt.zero_grad()\n        loss.backward()\n        opt.step()\n    with torch.no_grad():\n        acc = (enc(**to_torch_batch(data, test)).argmax(-1) == labels[test]).float().mean().item()\n    assert acc > 0.9, acc\n\n\ndef test_diffusion_policy_memorizes_observation_conditioned_chunks():\n    torch.manual_seed(0)\n    policy = build_diffusion_policy({\"encoder\": {\"name\": \"cnn\", \"feature_dim\": 64}, \"horizon\": 4,\n                                     \"num_diffusion_steps\": 20, \"hidden_dim\": 128, \"depth\": 2}, num_actions=5)\n    obs = torch.zeros(2, 64, 64, 3, dtype=torch.uint8)\n    obs[1] = 255\n    targets = torch.tensor([[0, 1, 2, 3], [4, 4, 0, 2]])\n    opt = torch.optim.Adam(policy.parameters(), lr=1e-3)\n    for _ in range(200):\n        loss = policy.loss(obs.repeat(16, 1, 1, 1), targets.repeat(16, 1))\n        opt.zero_grad()\n        loss.backward()\n        opt.step()\n    policy.eval()\n    for seed in range(5):\n        g = torch.Generator().manual_seed(seed)\n        assert torch.equal(policy.sample(obs, generator=g), targets)              # full DDPM\n        assert torch.equal(policy.sample(obs, num_steps=5, generator=g), targets)  # strided DDIM\n\n\ndef test_diffusion_epsilon_prediction_runs():\n    policy = build_diffusion_policy({\"encoder\": {\"name\": \"cnn\", \"feature_dim\": 32}, \"horizon\": 2,\n                                     \"num_diffusion_steps\": 5, \"hidden_dim\": 32, \"depth\": 1,\n                                     \"prediction_type\": \"epsilon\"}, num_actions=3)\n    obs = torch.zeros(2, 64, 64, 3, dtype=torch.uint8)\n    assert policy.loss(obs, torch.zeros(2, 2, dtype=torch.long)).ndim == 0\n    assert policy.sample(obs).shape == (2, 2) and policy.sample(obs, num_steps=2).shape == (2, 2)\n    with pytest.raises(ValueError):\n        build_diffusion_policy({\"prediction_type\": \"v\"}, num_actions=3)\n"},{"path":"tests/test_rl.py","text":"import functools\n\nimport gymnasium as gym\nimport numpy as np\nimport pytest\n\ntorch = pytest.importorskip(\"torch\")\n\nfrom diffu_moe_vlm.crafter_env import CRAFTER_ACHIEVEMENTS, AchievementTracker, crafter_score  # noqa: E402\nfrom diffu_moe_vlm.nn.policy import build_actor_critic  # noqa: E402\nfrom diffu_moe_vlm.rl.checkpoint import load_policy, save_checkpoint  # noqa: E402\nfrom diffu_moe_vlm.rl.ppo import PPOConfig, PPOTrainer  # noqa: E402\nfrom diffu_moe_vlm.rl.rollout import (ActionChunkDataset, ActorCriticRunner, RandomRunner,  # noqa: E402\n                                      collect_demonstrations, evaluate)\nfrom diffu_moe_vlm.rl.vec_env import VecEnv  # noqa: E402\n\n\nclass ColorBanditEnv(gym.Env):\n    \"\"\"One-step task: the image is dark or bright and the correct action is 0 or 1 accordingly\"\"\"\n\n    observation_space = gym.spaces.Box(0, 255, (64, 64, 3), np.uint8)\n    action_space = gym.spaces.Discrete(3)\n\n    def reset(self, seed=None, options=None):\n        super().reset(seed=seed)\n        self.target = int(self.np_random.integers(2))\n        return np.full((64, 64, 3), 255 * self.target, np.uint8), {}\n\n    def step(self, action):\n        reward = 1.0 if int(action) == self.target else 0.0\n        obs, _ = self.reset()\n        return obs, reward, True, False, {'achievements': {'collect_wood': int(reward)}}\n\n\ndef small_model(num_actions):\n    return build_actor_critic({\"encoder\": {\"name\": \"cnn\", \"feature_dim\": 64}, \"hidden_dim\": 64,\n                               \"num_experts\": 2, \"top_k\": 1}, num_actions)\n\n\ndef test_crafter_score_and_tracker():\n    assert crafter_score({name: 0.0 for name in CRAFTER_ACHIEVEMENTS}) == pytest.approx(0.0)\n    assert crafter_score({name: 100.0 for name in CRAFTER_ACHIEVEMENTS}) == pytest.approx(100.0)\n    tracker = AchievementTracker()\n    tracker.add_episode({'eat_plant': 1, 'collect_wood': 3}, 2.0, 100)\n    tracker.add_episode({'collect_wood': 1}, 1.0, 50)\n    rates = tracker.success_rates()\n    assert rates['collect_wood'] == 100.0 and rates['eat_plant'] == 50.0 and rates['collect_diamond'] == 0.0\n    summary = tracker.summary()\n    assert summary['return_mean'] == 1.5 and summary['achievements/eat_plant'] == 50.0\n\n\ndef test_ppo_solves_color_bandit():\n    torch.manual_seed(0)\n    envs = VecEnv([ColorBanditEnv] * 8, seeds=list(range(8)), num_workers=0)\n    cfg = PPOConfig(total_steps=8 * 32 * 12, num_envs=8, rollout_length=32, epochs=4, minibatches=4,\n                    lr=1e-3, entropy_coef=0.0, log_window=200)\n    tracker = PPOTrainer(small_model(3), envs, cfg).train()\n    assert np.mean(tracker.returns[-200:]) > 0.9\n\n\ndef test_checkpoint_roundtrip(tmp_path):\n    model = small_model(17).eval()\n    cfg = {\"encoder\": {\"name\": \"cnn\", \"feature_dim\": 64}, \"hidden_dim\": 64, \"num_experts\": 2, \"top_k\": 1}\n    path = save_checkpoint(tmp_path / \"ckpt.pt\", model, \"ppo\", cfg, step=7)\n    loaded, ckpt = load_policy(path, 17)\n    obs = torch.randint(0, 256, (3, 64, 64, 3), dtype=torch.uint8)\n    assert ckpt[\"step\"] == 7\n    assert torch.allclose(model(obs)[0], loaded(obs)[0])\n\n\ndef test_action_chunk_windows_stay_inside_episodes():\n    data = {'obs': np.zeros((7, 64, 64, 3), np.uint8), 'actions': np.arange(7),\n            'episode': np.array([0, 0, 0, 1, 1, 1, 1])}\n    ds = ActionChunkDataset(data, horizon=3)\n    assert [ds[i][1].tolist() for i in range(len(ds))] == [[0, 1, 2], [3, 4, 5], [4, 5, 6]]\n\n\ndef test_crafter_wrapper_evaluation_and_demos():\n    pytest.importorskip(\"crafter\")\n    from diffu_moe_vlm.crafter_env import CrafterEnv\n\n    env = CrafterEnv(length=5)\n    obs, info = env.reset(seed=0)\n    assert obs.shape == (64, 64, 3) and obs.dtype == np.uint8\n    for _ in range(5):\n        obs, reward, terminated, truncated, info = env.step(0)\n    assert truncated and not terminated and set(info['achievements']) == set(CRAFTER_ACHIEVEMENTS)\n\n    envs = VecEnv([functools.partial(CrafterEnv, length=20)] * 2, seeds=[0, 1], num_workers=0)\n    tracker = evaluate(RandomRunner(17), envs, num_episodes=3)\n    assert len(tracker.episodes) == 3 and all(length <= 20 for length in tracker.lengths)\n\n    data = collect_demonstrations(ActorCriticRunner(small_model(17).eval()), envs, num_steps=40)\n    assert data['obs'].shape[0] == data['actions'].shape[0] == data['episode'].shape[0] >= 40\n"},{"path":"train_craftax.py","text":"\"\"\"\nPPO / PPO-RNN on Craftax in JAX (runs end-to-end on one GPU).\n\n    python train_craftax.py                                  # PPO, Craftax-Symbolic-v1, 1B steps\n    python train_craftax.py algo.rnn=true                    # PPO-RNN\n    python train_craftax.py algo.moe=true                    # MoE hidden layers\n    python train_craftax.py algo.icm=true                    # + normalized ICM bonus\n    python train_craftax.py algo.total_timesteps=10000000 algo.num_envs=256   # small CPU run\n\nWrites metrics.jsonl (one line per logged update), checkpoint.npz (full\ntraining state, written every `checkpoint_every` updates), params.msgpack and\nsummary.json to output_dir. Re-running with the same output_dir resumes from\nthe checkpoint with identical results, so preempted or crashed runs can be\ncontinued; `max_updates_per_run` stops early on purpose (time-limited jobs).\nCompare a finished run with the reference W&B results using\ncompare_craftax_run.py.\n\"\"\"\n\nimport json\nimport time\nfrom pathlib import Path\n\nimport hydra\nimport jax\nimport numpy as np\nfrom flax import serialization\nfrom omegaconf import OmegaConf\n\nfrom diffu_moe_vlm.jax_rl.ppo import load_runner, make_train, save_runner\n\n\ndef run_name(cfg) -> str:\n    algo = cfg[\"algo\"]\n    tag = \"PPO_RNN-\" if algo[\"rnn\"] else \"\"\n    tag += \"MoE-\" if algo[\"moe\"] else \"\"\n    tag += f\"ICM_{algo['icm_normalize']}-\" if algo[\"icm\"] else \"\"\n    return f\"{algo['env_name']}-{tag}{int(algo['total_timesteps'] // 1_000_000)}M\"\n\n\n@hydra.main(config_path=\"configs\", config_name=\"train_craftax\", version_base=None)\ndef main(cfg) -> None:\n    cfg = OmegaConf.to_container(cfg, resolve=True)\n    out = Path(cfg[\"output_dir\"])\n    out.mkdir(parents=True, exist_ok=True)\n    name = cfg.get(\"name\") or run_name(cfg)\n    print(f\"[Craftax] {name} on {jax.devices()}\")\n    print(json.dumps(cfg[\"algo\"], indent=2))\n\n    wandb_run = None\n    if cfg[\"wandb\"][\"enabled\"]:\n        import wandb\n        wandb_run = wandb.init(project=cfg[\"wandb\"][\"project\"], name=name, config=cfg[\"algo\"])\n\n    start = time.time()\n    state = {\"last_step\": None, \"last_time\": start}\n    jsonl = None\n\n    def log_fn(metrics, update_idx):\n        update = int(update_idx) + 1\n        if update % cfg[\"log_every\"] and update != train.num_updates:\n            return\n        m = {k: float(np.asarray(v)) for k, v in metrics.items()}\n        now = time.time()\n        if state[\"last_step\"] is not None:\n            m[\"sps\"] = (m[\"env_steps\"] - state[\"last_step\"]) / max(now - state[\"last_time\"], 1e-9)\n        state.update(last_step=m[\"env_steps\"], last_time=now)\n        jsonl.write(json.dumps(m) + \"\\n\")\n        jsonl.flush()\n        if wandb_run:\n            wandb_run.log(m, step=update)\n        print(f\"[Craftax] update {update}/{train.num_updates} steps={m['env_steps']:.3g} sps={m.get('sps', 0):.0f} \"\n              f\"return={m['episode_return']:.2f} length={m['episode_length']:.0f} episodes={m['episodes']:.0f}\",\n              flush=True)\n\n    train = make_train(cfg[\"algo\"], log_fn=log_fn)\n    ckpt_path = out / \"checkpoint.npz\"\n    runner = train.init(jax.random.PRNGKey(cfg[\"seed\"]))\n    next_update = 0\n    if cfg[\"resume\"] and ckpt_path.exists():\n        runner, next_update = load_runner(ckpt_path, runner)\n        print(f\"[Craftax] resumed from {ckpt_path} at update {next_update}/{train.num_updates}\")\n    jsonl = open(out / \"metrics.jsonl\", \"a\" if next_update else \"w\")\n\n    budget = cfg.get(\"max_updates_per_run\") or train.num_updates\n    stop_at = min(train.num_updates, next_update + budget)\n    chunk = max(1, int(cfg[\"checkpoint_every\"]))\n    while next_update < stop_at:\n        num = min(chunk, stop_at - next_update)\n        runner, _ = jax.block_until_ready(train.run_updates(runner, next_update, num))\n        next_update += num\n        save_runner(ckpt_path, runner, next_update)\n    jsonl.close()\n\n    if next_update < train.num_updates:\n        print(f\"[Craftax] stopped at update {next_update}/{train.num_updates}; re-run to resume from {ckpt_path}\")\n        return\n    params = runner[0].params\n    (out / \"params.msgpack\").write_bytes(serialization.to_bytes(params))\n    rows = [json.loads(line) for line in (out / \"metrics.jsonl\").read_text().splitlines() if line.strip()]\n    summary = {\"name\": name, \"seed\": cfg[\"seed\"], \"final\": rows[-1] if rows else {}, \"config\": train.config}\n    (out / \"summary.json\").write_text(json.dumps(summary, indent=2))\n    print(f\"[Craftax] finished {train.num_updates} updates; saved to {out}\")\n    if wandb_run:\n        wandb_run.finish()\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"train_diffusion.py","text":"\"\"\"\nBehavior-clone a diffusion policy on Crafter.\n\nDemonstrations come from an existing .npz (`demos.path`) or are collected with\na PPO checkpoint (`demos.policy_checkpoint`); without either, a random policy\nis used (only useful as a smoke test).\n\n    python train_diffusion.py demos.policy_checkpoint=runs/ppo/checkpoint.pt\n\"\"\"\n\nfrom pathlib import Path\n\nimport hydra\nimport numpy as np\nfrom omegaconf import OmegaConf\n\nfrom diffu_moe_vlm.crafter_env import CRAFTER_ACTIONS, format_achievements\nfrom diffu_moe_vlm.nn.diffusion import build_diffusion_policy\nfrom diffu_moe_vlm.rl.checkpoint import load_policy, save_checkpoint\nfrom diffu_moe_vlm.rl.common import make_crafter_envs, make_logger, resolve_device, seed_everything, write_json\nfrom diffu_moe_vlm.rl.diffusion_bc import train_diffusion_bc\nfrom diffu_moe_vlm.rl.rollout import ActorCriticRunner, DiffusionRunner, RandomRunner, collect_demonstrations, evaluate\n\n\n@hydra.main(config_path=\"configs\", config_name=\"train_diffusion\", version_base=None)\ndef main(cfg) -> None:\n    run_cfg = OmegaConf.to_container(cfg, resolve=True)\n    print(OmegaConf.to_yaml(cfg))\n    seed_everything(cfg.seed, cfg.get(\"torch_threads\"))\n    device = resolve_device(cfg.device)\n    out = Path(cfg.output_dir)\n    num_actions = len(CRAFTER_ACTIONS)\n\n    # 1. Demonstrations\n    if cfg.demos.path and Path(cfg.demos.path).exists():\n        with np.load(cfg.demos.path) as f:\n            data = {k: f[k] for k in f.files}\n        print(f\"[Demos] loaded {len(data['actions'])} steps from {cfg.demos.path}\")\n    else:\n        if cfg.demos.policy_checkpoint:\n            teacher, _ = load_policy(cfg.demos.policy_checkpoint, num_actions, device, cfg.env.size)\n            runner = ActorCriticRunner(teacher, device)\n            print(f\"[Demos] collecting with {cfg.demos.policy_checkpoint}\")\n        else:\n            runner = RandomRunner(num_actions, cfg.seed)\n            print(\"[Demos] no teacher checkpoint given: collecting RANDOM demonstrations (smoke test only)\")\n        envs = make_crafter_envs(cfg.demos.num_envs, cfg.seed, cfg.env.size, cfg.env.length, cfg.env.num_workers)\n        try:\n            data = collect_demonstrations(runner, envs, cfg.demos.num_steps, path=out / 'demos.npz')\n        finally:\n            envs.close()\n        print(f\"[Demos] collected {len(data['actions'])} steps in {data['episode'].max() + 1} episodes\")\n\n    # 2. Behavior cloning\n    model_cfg = run_cfg['model']\n    model = build_diffusion_policy(model_cfg, num_actions, image_size=cfg.env.size)\n    log = make_logger(run_cfg.get('wandb'), run_cfg, out / 'metrics.jsonl')\n    train_diffusion_bc(model, data, steps=cfg.train.steps, batch_size=cfg.train.batch_size, lr=cfg.train.lr,\n                       device=device, log_fn=log, seed=cfg.seed)\n    path = save_checkpoint(out / 'checkpoint.pt', model, 'diffusion', model_cfg, step=cfg.train.steps)\n    print(f\"[Diffusion BC] saved {path}\")\n\n    # 3. Evaluation\n    if cfg.eval.episodes > 0:\n        envs = make_crafter_envs(cfg.eval.num_envs, cfg.seed + 10_000, cfg.env.size, cfg.env.length,\n                                 cfg.env.num_workers)\n        runner = DiffusionRunner(model, device, cfg.eval.execute_steps, cfg.eval.sample_steps)\n        try:\n            result = evaluate(runner, envs, cfg.eval.episodes)\n        finally:\n            envs.close()\n        summary = result.summary()\n        write_json(out / 'eval.json', summary)\n        print(f\"[Eval] episodes={summary['episodes']} return={summary['return_mean']:.2f} score={summary['score']:.2f}\")\n        print(\"[Eval] \" + format_achievements(result.success_rates()))\n\n\nif __name__ == '__main__':\n    main()\n"},{"path":"train_ppo.py","text":"\"\"\"\nTrain the MoE actor-critic on Crafter with PPO.\n\n    python train_ppo.py                                   # defaults: configs/train_ppo.yaml\n    python train_ppo.py ppo.total_steps=200000 model.encoder.name=vit\n    python train_ppo.py model.trunk=mlp                   # dense ablation\n\"\"\"\n\nfrom pathlib import Path\n\nimport hydra\nfrom omegaconf import OmegaConf\n\nfrom diffu_moe_vlm.crafter_env import CRAFTER_ACTIONS, format_achievements\nfrom diffu_moe_vlm.nn.policy import build_actor_critic\nfrom diffu_moe_vlm.rl.checkpoint import save_checkpoint\nfrom diffu_moe_vlm.rl.common import make_crafter_envs, make_logger, resolve_device, seed_everything, write_json\nfrom diffu_moe_vlm.rl.ppo import PPOConfig, PPOTrainer\nfrom diffu_moe_vlm.rl.rollout import ActorCriticRunner, evaluate\n\n\n@hydra.main(config_path=\"configs\", config_name=\"train_ppo\", version_base=None)\ndef main(cfg) -> None:\n    run_cfg = OmegaConf.to_container(cfg, resolve=True)\n    print(OmegaConf.to_yaml(cfg))\n    seed_everything(cfg.seed, cfg.get(\"torch_threads\"))\n    device = resolve_device(cfg.device)\n    out = Path(cfg.output_dir)\n\n    model_cfg = run_cfg['model']\n    model = build_actor_critic(model_cfg, len(CRAFTER_ACTIONS), image_size=cfg.env.size)\n    print(f\"[PPO] parameters: {sum(p.numel() for p in model.parameters()):,} on {device}\")\n\n    ppo_cfg = PPOConfig(**run_cfg['ppo'])\n    envs = make_crafter_envs(ppo_cfg.num_envs, cfg.seed, cfg.env.size, cfg.env.length, cfg.env.num_workers)\n    log = make_logger(run_cfg.get('wandb'), run_cfg, out / 'metrics.jsonl')\n    trainer = PPOTrainer(\n        model, envs, ppo_cfg, device=device, log_fn=log, checkpoint_every=cfg.checkpoint_every,\n        checkpoint_fn=lambda step: save_checkpoint(out / 'checkpoint.pt', model, 'ppo', model_cfg,\n                                                   trainer.optimizer, step),\n    )\n    try:\n        tracker = trainer.train()\n    finally:\n        envs.close()\n    path = save_checkpoint(out / 'checkpoint.pt', model, 'ppo', model_cfg, trainer.optimizer, trainer.global_step,\n                           extra={'train_summary': tracker.summary(last=ppo_cfg.log_window)})\n    print(f\"[PPO] saved {path}\")\n\n    if cfg.eval_episodes > 0:\n        eval_envs = make_crafter_envs(cfg.eval_num_envs, cfg.seed + 10_000, cfg.env.size, cfg.env.length,\n                                      cfg.env.num_workers)\n        try:\n            result = evaluate(ActorCriticRunner(model.eval(), device), eval_envs, cfg.eval_episodes)\n        finally:\n            eval_envs.close()\n        summary = result.summary()\n        write_json(out / 'eval.json', summary)\n        print(f\"[Eval] episodes={summary['episodes']} return={summary['return_mean']:.2f} score={summary['score']:.2f}\")\n        print(\"[Eval] \" + format_achievements(result.success_rates()))\n\n\nif __name__ == '__main__':\n    main()\n"}]};
